function Save-WfxViewHtml {
    <# Writes ConvertTo-WfxViewHtml output to <case root>\views\ and returns the file path. #>
    param([object[]]$Rows, [string]$Title, [string]$Key = 'view', [object[]]$Note = @())
    $dir = Join-Path (Get-WfxCaseRoot) 'views'
    if (-not (Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
    $safeKey = $Key -replace '[^A-Za-z0-9_-]', '_'
    $f = Join-Path $dir ("{0}_{1}_{2}.html" -f [Environment]::MachineName, $safeKey, (Get-Date).ToUniversalTime().ToString('yyyyMMdd-HHmmss'))
    [IO.File]::WriteAllText($f, (ConvertTo-WfxViewHtml -Rows $Rows -Title $Title -Note $Note), (New-Object System.Text.UTF8Encoding($false)))
    $f
}


# ===== Public/Compare-WfxCase.ps1 =====
function Compare-WfxCase {
    <#
    .SYNOPSIS
        Diffs two collections of the same (or a reference) host — "what changed since the baseline?".
        Reports added / removed processes (by image), autostarts, services & drivers, listening ports,
        DNS names, exposure items and (when both cases have result.json) findings.
    .DESCRIPTION
        Typical uses: a known-good "golden" baseline vs. a suspect host; before vs. after a malware sample
        runs in a lab VM / CTF challenge; this week's collection vs. last week's.
    .PARAMETER Baseline  Case folder or bundle.json of the reference state.
    .PARAMETER Current   Case folder or bundle.json of the state to check.
    .PARAMETER OutputPath Optional .csv or .json file to write the differences to.
    .EXAMPLE
        Compare-WfxCase -Baseline .\WFX_pc01_baseline -Current .\WFX_pc01_today | Where-Object Change -eq 'Added'
    #>
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$Baseline, [Parameter(Mandatory)][string]$Current, [string]$OutputPath = '')
    $load = {
        param($p)
        $bp = Resolve-WfxBundlePath -Path $p
        $b = Get-Content -LiteralPath $bp -Raw -Encoding UTF8 | ConvertFrom-Json
        $rp = Join-Path (Split-Path -Parent (Split-Path -Parent $bp)) 'result.json'
        $r = if (Test-Path -LiteralPath $rp) { Get-Content -LiteralPath $rp -Raw -Encoding UTF8 | ConvertFrom-Json } else { $null }
        [pscustomobject]@{ Bundle = $b; Result = $r }
    }
    $A = & $load $Baseline
    $B = & $load $Current
    $sections = [ordered]@{
        Process     = { param($x) @(Get-WfxValue $x.Bundle 'Process' @()) | ForEach-Object { $k = ("{0}|{1}" -f $_.Name, $_.Path).ToLowerInvariant(); [pscustomobject]@{ K = $k; D = "$($_.Name)  $($_.Path)" } } }
        Autostart   = { param($x) @(Get-WfxValue $x.Bundle 'Persistence' @()) | Where-Object { $_.Kind -notin 'Service', 'Driver' } | ForEach-Object { [pscustomobject]@{ K = ("{0}|{1}|{2}" -f $_.Kind, $_.Name, $_.Command).ToLowerInvariant(); D = "$($_.Kind): $($_.Name) → $($_.Command)" } } }
        Service     = { param($x) @(Get-WfxValue $x.Bundle 'Persistence' @()) | Where-Object { $_.Kind -in 'Service', 'Driver' } | ForEach-Object { [pscustomobject]@{ K = ("{0}|{1}|{2}" -f $_.Kind, $_.Name, $_.Path).ToLowerInvariant(); D = "$($_.Kind): $($_.Name) [$($_.Location)] $($_.Path) sig=$($_.SignatureStatus)" } } }
        Listener    = { param($x) @(Get-WfxValue $x.Bundle 'Network' @()) | Where-Object { $_.State -match '^(?:Listen|Bound)$' } | ForEach-Object { [pscustomobject]@{ K = ("{0}|{1}|{2}|{3}" -f $_.Protocol, $_.LocalAddress, $_.LocalPort, $_.Process).ToLowerInvariant(); D = "$($_.Protocol) $($_.LocalAddress):$($_.LocalPort) ($($_.Process))" } } }
        Dns         = { param($x) @(Get-WfxValue $x.Bundle 'Dns' @()) | ForEach-Object { [pscustomobject]@{ K = ([string]$_.Name).ToLowerInvariant(); D = "$($_.Name)" } } }
        Exposure    = { param($x) @(Get-WfxValue $x.Bundle 'Exposure' @()) | ForEach-Object { [pscustomobject]@{ K = ("{0}|{1}" -f $_.Kind, $_.Path).ToLowerInvariant(); D = "$($_.Kind): $($_.Path) $($_.Detail)" } } }
        Finding     = { param($x) if ($x.Result) { @($x.Result.Findings) | ForEach-Object { [pscustomobject]@{ K = ("{0}|{1}" -f $_.Id, $_.Entity).ToLowerInvariant(); D = "[$($_.Severity)] $($_.Title)" } } } }
    }
    $diff = New-Object System.Collections.Generic.List[object]
    foreach ($name in $sections.Keys) {
        $ia = @{}; foreach ($r in @(& $sections[$name] $A)) { if ($r) { $ia[$r.K] = $r.D } }
        $ib = @{}; foreach ($r in @(& $sections[$name] $B)) { if ($r) { $ib[$r.K] = $r.D } }
        foreach ($k in $ib.Keys) { if (-not $ia.ContainsKey($k)) { $diff.Add([pscustomobject]@{ Section = $name; Change = 'Added'; Detail = $ib[$k] }) } }
        foreach ($k in $ia.Keys) { if (-not $ib.ContainsKey($k)) { $diff.Add([pscustomobject]@{ Section = $name; Change = 'Removed'; Detail = $ia[$k] }) } }
    }
    $out = @($diff | Sort-Object Section, Change, Detail)
    Write-WfxSection 'Case comparison'
    Write-WfxConsole ("Baseline: {0} ({1})   Current: {2} ({3})" -f (Get-WfxValue $A.Bundle 'HostName' '?'), (Get-WfxValue $A.Bundle 'Collected' '?'), (Get-WfxValue $B.Bundle 'HostName' '?'), (Get-WfxValue $B.Bundle 'Collected' '?')) -Kind Dim
    foreach ($g in ($out | Group-Object Section)) {
        $add = @($g.Group | Where-Object Change -eq 'Added').Count; $rem = @($g.Group | Where-Object Change -eq 'Removed').Count
        Write-WfxConsole ("  {0,-10} +{1}  -{2}" -f $g.Name, $add, $rem) -Kind $(if ($add) { 'Warn' } else { 'Plain' })
    }
    if (-not $out.Count) { Write-WfxConsole '  No differences.' -Kind Ok }
    if ($OutputPath) {
        if ($OutputPath -match '\.json$') { Save-WfxJson -InputObject $out -Path $OutputPath -Depth 4 } else { $out | Export-Csv -Path $OutputPath -NoTypeInformation -Encoding UTF8 }
        Write-WfxConsole "Differences written to $OutputPath" -Kind Info
    }
    $out
}


# ===== Public/ConvertFrom-WfxEncodedCommand.ps1 =====
function ConvertFrom-WfxEncodedCommand {
    <#
    .SYNOPSIS
        Safely decodes obfuscated command payloads for analysis — PowerShell -EncodedCommand, Base64
        (UTF-16LE / UTF-8), gzip-wrapped Base64, and nested FromBase64String('...') layers.
        DECODE ONLY: nothing is ever executed.
    .PARAMETER InputObject A full command line (the -enc argument is located automatically) or a raw Base64 string.
    .PARAMETER Depth       How many nested FromBase64String layers to follow (default 3).
    .EXAMPLE
        ConvertFrom-WfxEncodedCommand 'powershell -nop -w hidden -enc VwByAGkAdABlAC0ATwB1AHQAcAB1AHQAIAAnAGgAaQAnAA=='
    .EXAMPLE
        Get-Content .\blob.txt -Raw | ConvertFrom-WfxEncodedCommand
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory, ValueFromPipeline)][AllowEmptyString()][string]$InputObject,
        [ValidateRange(1, 10)][int]$Depth = 3
    )
    process {
        $layers = New-Object System.Collections.Generic.List[object]
        $text = Get-WfxEncodedCommandPayload $InputObject
        $how = '-EncodedCommand argument'
        if (-not $text) { $text = ConvertFrom-WfxBase64Text $InputObject; $how = 'raw Base64' }
        if (-not $text) {
            Write-Warning 'No decodable -EncodedCommand argument or Base64 payload was found.'
            return
        }
        $layers.Add([pscustomobject]@{ Layer = 1; Source = $how; Text = $text })
        $cur = $text
        for ($i = 2; $i -le $Depth; $i++) {
            $m = [regex]::Match($cur, '(?i)FromBase64String\s*\(\s*["'']([A-Za-z0-9+/=\s]{16,})["'']')
            if (-not $m.Success) { $m = [regex]::Match($cur, '(?i)(?:^|\s)[-/]e(?:nc\w*|c)?\s+([A-Za-z0-9+/=]{16,})') }
            if (-not $m.Success) { break }
            $next = ConvertFrom-WfxBase64Text $m.Groups[1].Value
            if (-not $next) { break }
            $layers.Add([pscustomobject]@{ Layer = $i; Source = 'nested Base64'; Text = $next })
            $cur = $next
        }
        $iocs = Get-WfxIocFromText -Text @($layers | ForEach-Object Text)
        [pscustomobject]@{
            PSTypeName = 'WinForensicX.DecodedCommand'
            Decoded    = $cur
            Layers     = $layers.ToArray()
            Rules      = @(try { Test-WfxCommandLine -CommandLine $cur -Image 'powershell.exe' | ForEach-Object { "$($_.id): $($_.title)" } } catch { "rule pack unavailable: $($_.Exception.Message)" })
            Iocs       = $iocs
            Note       = 'Decoded for analysis only. Nothing was executed.'
        }
    }
}


# ===== Public/Export-WfxTimeline.ps1 =====
function Get-WfxTimeline {
    <#
    .SYNOPSIS Builds a single, UTC-sorted timeline from a case or bundle: host boot/install, process starts,
    connection creation, event-log records, file writes/creations, and (when result.json is present) findings.
    .PARAMETER InputPath  A case folder or bundle.json.
    .PARAMETER From/To    Optional UTC window.
    #>
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$InputPath, [datetime]$From = [datetime]::MinValue, [datetime]$To = [datetime]::MaxValue)
    $bundlePath = Resolve-WfxBundlePath -Path $InputPath
    $b = Get-Content -LiteralPath $bundlePath -Raw -Encoding UTF8 | ConvertFrom-Json
    $hn = [string](Get-WfxValue $b 'HostName' '')
    $rows = New-Object System.Collections.Generic.List[object]
    $add = {
        param($Time, $Source, $Type, $Summary, $Detail = '')
        $t = ConvertTo-WfxDateTime $Time
        if (-not $t -or $t -lt $From.ToUniversalTime() -or $t -gt $To.ToUniversalTime()) { return }
        $d = [string]$Detail; if ($d.Length -gt 1000) { $d = $d.Substring(0, 1000) + ' …' }
        $rows.Add([pscustomobject]@{ TimeUtc = (ConvertTo-WfxUtcString $t); Host = $hn; Source = $Source; Type = $Type; Summary = [string]$Summary; Detail = $d; _t = $t })
    }
    $h = Get-WfxValue $b 'Host' $null
    if ($h) { & $add (Get-WfxValue $h 'BootUtc' (Get-WfxValue $h 'Boot' '')) 'host' 'boot' 'System boot'; & $add (Get-WfxValue $h 'InstallUtc' '') 'host' 'install' 'Windows installed' }
    foreach ($p in @(Get-WfxValue $b 'Process' @())) { & $add $p.CreateTime 'process' 'process-start' "$($p.Name) (pid $($p.Pid), parent $($p.ParentName))" $p.CommandLine }
    foreach ($c in @(Get-WfxValue $b 'Network' @())) { & $add (Get-WfxValue $c 'CreatedUtc' '') 'network' "$($c.Protocol)-$($c.State)" "$($c.Process) $($c.LocalAddress):$($c.LocalPort) → $($c.RemoteAddress):$($c.RemotePort)" }
    foreach ($e in @(Get-WfxValue $b 'Events' @())) {
        $fl = Get-WfxValue $e 'Fields' $null
        $keys = @('TargetUserName', 'SubjectUserName', 'IpAddress', 'LogonType', 'NewProcessName', 'Image', 'CommandLine', 'ServiceName', 'ImagePath', 'TaskName', 'Threat Name', 'QueryName', 'DestinationIp', 'TargetObject')
        $kv = @(foreach ($k in $keys) { $v = [string](Get-WfxValue $fl $k ''); if ($v -and $v -ne '-') { "$k=$v" } }) -join '; '
        $msg = [string](Get-WfxValue $e 'Message' ''); $first = ($msg -split "`r?`n")[0]
        & $add $e.TimeCreated "evt:$($e.Log)" "event-$($e.Id)" "$($e.Id) $first" $kv
    }
    foreach ($a in @(Get-WfxValue $b 'Activity' @())) { & $add $a.Time "activity:$($a.Category)" $a.Action $a.Target "$($a.Detail) $(if ($a.Actor) { "by $($a.Actor)" }) [$($a.Source)]" }
    foreach ($f in @(Get-WfxValue $b 'Files' @())) {
        & $add $f.LastWrite 'file' 'file-modified' $f.Path "sha256=$(Get-WfxValue $f 'SHA256' '') zone=$(Get-WfxValue $f 'Zone' '') $(Get-WfxValue $f 'HostUrl' '')"
        & $add (Get-WfxValue $f 'Created' '') 'file' 'file-created' $f.Path
    }
    $resultPath = Join-Path (Split-Path -Parent (Split-Path -Parent $bundlePath)) 'result.json'
    if (Test-Path -LiteralPath $resultPath) {
        $r = Get-Content -LiteralPath $resultPath -Raw -Encoding UTF8 | ConvertFrom-Json
        foreach ($f in @($r.Findings)) { & $add $f.Time 'finding' "finding-$($f.Severity)" "[$($f.Severity)] $($f.Title)" "$($f.Id) $($f.Entity)" }
    }
    $rows | Sort-Object _t | Select-Object TimeUtc, Host, Source, Type, Summary, Detail
}

function Export-WfxTimeline {
    <#
    .SYNOPSIS Writes the case timeline (see Get-WfxTimeline) to CSV or JSON for Excel, Timeline Explorer or a SIEM.
    By default the file is written NEXT TO the case folder (<case>-timeline.csv), so a completed, hashed case
    folder is never modified.
    .EXAMPLE
        Export-WfxTimeline -InputPath C:\cases\WFX_host_20260101-000000Z
    .EXAMPLE
        Export-WfxTimeline -InputPath .\case -Format Json -From '2026-11-01' -OutputPath .\tl.json
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)][string]$InputPath,
        [string]$OutputPath = '',
        [ValidateSet('Csv', 'Json')][string]$Format = 'Csv',
        [datetime]$From = [datetime]::MinValue,
        [datetime]$To = [datetime]::MaxValue,
        [switch]$PassThru
    )
    $rows = Get-WfxTimeline -InputPath $InputPath -From $From -To $To
    if (-not $OutputPath) {
        $bp = Resolve-WfxBundlePath -Path $InputPath
        $caseDir = Split-Path -Parent (Split-Path -Parent $bp)
        if ((Split-Path -Leaf (Split-Path -Parent $bp)) -ne 'raw') { $caseDir = Split-Path -Parent $bp }
        $OutputPath = Join-Path (Split-Path -Parent $caseDir) ("{0}-timeline.{1}" -f (Split-Path -Leaf $caseDir), $Format.ToLowerInvariant())
    }
    if ($Format -eq 'Csv') { @($rows) | Export-Csv -Path $OutputPath -NoTypeInformation -Encoding UTF8 }
    else { Save-WfxJson -InputObject @($rows) -Path $OutputPath -Depth 4 }
    Write-WfxConsole ("Timeline: {0} entries → {1}" -f @($rows).Count, $OutputPath) -Kind Info
    if ($PassThru) { return $rows }
}


# ===== Public/FileBaseline.ps1 =====
function New-WfxFileBaseline {
    <#
    .SYNOPSIS
        File-integrity baseline: records size, timestamps and SHA-256 of every file under the given folders,
        so a later Compare-WfxFileBaseline shows exactly what was added, deleted, or had its CONTENT changed.
    .DESCRIPTION
        Typical uses: snapshot C:\Windows\System32\drivers\etc, a web root, a startup folder or a CTF VM before
        running a sample, then compare afterwards. Read-only; the baseline is written to -OutputPath.
    .EXAMPLE
        New-WfxFileBaseline -Path C:\inetpub\wwwroot, C:\Windows\System32\drivers\etc -OutputPath E:\baselines\web.json
    #>
    [CmdletBinding()]
    param([Parameter(Mandatory)][string[]]$Path, [string]$OutputPath = '', [int]$MaxFiles = 200000, [int]$MaxFileMB = 256)
    $files = New-Object System.Collections.Generic.List[object]
    foreach ($root in $Path) {
        if (-not (Test-Path -LiteralPath $root)) { Write-Warning "Not found: $root"; continue }
        Write-WfxConsole "  Hashing $root ..." -Kind Dim
        foreach ($f in (Get-ChildItem -LiteralPath $root -File -Recurse -Force -ErrorAction SilentlyContinue)) {
            if ($files.Count -ge $MaxFiles) { Write-Warning "File cap ($MaxFiles) reached."; break }
            $h = if ($f.Length -le $MaxFileMB * 1MB) { try { (Get-FileHash -LiteralPath $f.FullName -Algorithm SHA256 -ErrorAction Stop).Hash } catch { 'unreadable' } } else { 'too-large' }
            $files.Add([pscustomobject]@{ Path = $f.FullName; Size = $f.Length; Modified = (ConvertTo-WfxUtcString $f.LastWriteTimeUtc); Created = (ConvertTo-WfxUtcString $f.CreationTimeUtc); SHA256 = $h })
        }
    }
    if (-not $OutputPath) {
        $root = Get-WfxDefaultOutputRoot; if (-not (Test-Path -LiteralPath $root)) { New-Item -ItemType Directory -Path $root -Force | Out-Null }
        $OutputPath = Join-Path $root ("baseline_{0}_{1}.json" -f [Environment]::MachineName, (Get-Date).ToUniversalTime().ToString('yyyyMMdd-HHmmss'))
    }
    Save-WfxJson -InputObject ([pscustomobject]@{ Schema = 'winforensicx.filebaseline/1'; Host = [Environment]::MachineName; Created = (Get-WfxUtcNow); Roots = @($Path); Files = $files.ToArray() }) -Path $OutputPath -Depth 4
    Write-WfxConsole ("Baseline of {0} files: {1}  (SHA-256 {2})" -f $files.Count, $OutputPath, (Get-FileHash -LiteralPath $OutputPath -Algorithm SHA256).Hash.ToLowerInvariant()) -Kind Ok
    $OutputPath
}

function Compare-WfxFileBaseline {
    <#
    .SYNOPSIS Re-scans the folders of a baseline and reports Added, Deleted, ContentChanged and
    TimestampOnly (same content, different timestamps — possible timestomping or a touch) files.
    .EXAMPLE
        Compare-WfxFileBaseline -Baseline E:\baselines\web.json | Format-Table
    #>
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$Baseline)
    $b = Get-Content -LiteralPath $Baseline -Raw -Encoding UTF8 | ConvertFrom-Json
    $old = @{}; foreach ($f in @($b.Files)) { $old[$f.Path.ToLowerInvariant()] = $f }
    $seen = @{}
    $out = New-Object System.Collections.Generic.List[object]
    foreach ($root in @($b.Roots)) {
        foreach ($f in (Get-ChildItem -LiteralPath $root -File -Recurse -Force -ErrorAction SilentlyContinue)) {
            $k = $f.FullName.ToLowerInvariant(); $seen[$k] = $true
            $o = $old[$k]
            $mod = ConvertTo-WfxUtcString $f.LastWriteTimeUtc
            if (-not $o) { $out.Add([pscustomobject]@{ Change = 'Added'; Path = $f.FullName; Modified = $mod; Detail = "$($f.Length) bytes" }); continue }
            if ([int64]$o.Size -ne $f.Length -or (ConvertTo-WfxUtcString $o.Modified) -ne $mod) {
                $h = try { (Get-FileHash -LiteralPath $f.FullName -Algorithm SHA256 -ErrorAction Stop).Hash } catch { 'unreadable' }
                if ($h -ne $o.SHA256) { $out.Add([pscustomobject]@{ Change = 'ContentChanged'; Path = $f.FullName; Modified = $mod; Detail = "size $($o.Size) → $($f.Length); sha256 $($o.SHA256.Substring(0, [Math]::Min(12, $o.SHA256.Length)))… → $($h.Substring(0, [Math]::Min(12, $h.Length)))…" }) }
                else { $out.Add([pscustomobject]@{ Change = 'TimestampOnly'; Path = $f.FullName; Modified = $mod; Detail = "modified $(ConvertTo-WfxUtcString $o.Modified) → $mod (content identical)" }) }
            }
        }
    }
    foreach ($k in $old.Keys) { if (-not $seen.ContainsKey($k)) { $out.Add([pscustomobject]@{ Change = 'Deleted'; Path = $old[$k].Path; Modified = $old[$k].Modified; Detail = "$($old[$k].Size) bytes" }) } }
    $res = @($out | Sort-Object Change, Path)
    Write-WfxSection 'File baseline comparison'
    Write-WfxConsole ("Baseline {0} ({1} files) · now: added {2}, deleted {3}, content changed {4}, timestamp-only {5}" -f $b.Created, @($b.Files).Count, @($res | Where-Object Change -eq 'Added').Count, @($res | Where-Object Change -eq 'Deleted').Count, @($res | Where-Object Change -eq 'ContentChanged').Count, @($res | Where-Object Change -eq 'TimestampOnly').Count) -Kind Info
    $res
}


# ===== Public/Get-WfxFileTriage.ps1 =====
$script:WfxMagic = @(
    @{ T = 'PE executable (MZ)'; O = 0; H = '4D5A'; E = @('.exe', '.dll', '.sys', '.scr', '.cpl', '.ocx', '.com', '.efi', '.mui', '.drv', '.ax', '.node') }
    @{ T = 'ELF executable'; O = 0; H = '7F454C46'; E = @('', '.so', '.elf', '.bin', '.o') }
    @{ T = 'Mach-O (64-bit)'; O = 0; H = 'CFFAEDFE'; E = @('', '.dylib', '.bundle') }
    @{ T = 'Java class / Mach-O fat'; O = 0; H = 'CAFEBABE'; E = @('.class', '') }
    @{ T = 'PDF document'; O = 0; H = '25504446'; E = @('.pdf') }
    @{ T = 'ZIP container (also OOXML / JAR / APK / VSIX)'; O = 0; H = '504B0304'; E = @('.zip', '.docx', '.xlsx', '.pptx', '.docm', '.xlsm', '.pptm', '.jar', '.apk', '.vsix', '.nupkg', '.odt', '.ods', '.epub', '.xpi', '.whl', '.appx', '.msix', '.kmz', '.ipa') }
    @{ T = 'OLE2 compound file (legacy Office / MSI / MSG)'; O = 0; H = 'D0CF11E0A1B11AE1'; E = @('.doc', '.xls', '.ppt', '.msi', '.msg', '.msp', '.pub', '.vsd', '.mst') }
    @{ T = 'RAR archive'; O = 0; H = '526172211A07'; E = @('.rar') }
    @{ T = '7-Zip archive'; O = 0; H = '377ABCAF271C'; E = @('.7z') }
    @{ T = 'gzip'; O = 0; H = '1F8B'; E = @('.gz', '.tgz') }
    @{ T = 'bzip2'; O = 0; H = '425A68'; E = @('.bz2', '.tbz2') }
    @{ T = 'xz'; O = 0; H = 'FD377A585A00'; E = @('.xz', '.txz') }
    @{ T = 'Microsoft Cabinet'; O = 0; H = '4D534346'; E = @('.cab', '.msu') }
    @{ T = 'Windows shortcut (LNK)'; O = 0; H = '4C0000000114020000000000C000000000000046'; E = @('.lnk') }
    @{ T = 'Windows Event Log (EVTX)'; O = 0; H = '456C6646696C6500'; E = @('.evtx') }
    @{ T = 'Windows registry hive'; O = 0; H = '72656766'; E = @('', '.dat', '.hiv', '.hve', '.log1', '.log2') }
    @{ T = 'SQLite database'; O = 0; H = '53514C69746520666F726D61742033'; E = @('.db', '.sqlite', '.sqlite3', '.db3', '') }
    @{ T = 'PNG image'; O = 0; H = '89504E470D0A1A0A'; E = @('.png') }
    @{ T = 'JPEG image'; O = 0; H = 'FFD8FF'; E = @('.jpg', '.jpeg', '.jfif') }
    @{ T = 'GIF image'; O = 0; H = '474946383'; E = @('.gif') }
    @{ T = 'BMP image'; O = 0; H = '424D'; E = @('.bmp', '.dib') }
    @{ T = 'RIFF container (WAV / AVI / WEBP)'; O = 0; H = '52494646'; E = @('.wav', '.avi', '.webp', '.ani') }
    @{ T = 'Ogg'; O = 0; H = '4F676753'; E = @('.ogg', '.oga', '.ogv', '.opus') }
    @{ T = 'MP3 (ID3)'; O = 0; H = '494433'; E = @('.mp3') }
    @{ T = 'pcap capture'; O = 0; H = 'D4C3B2A1'; E = @('.pcap', '.cap') }
    @{ T = 'pcap capture (big-endian)'; O = 0; H = 'A1B2C3D4'; E = @('.pcap', '.cap') }
    @{ T = 'pcapng capture'; O = 0; H = '0A0D0D0A'; E = @('.pcapng') }
    @{ T = 'RTF document'; O = 0; H = '7B5C727466'; E = @('.rtf', '.doc') }
    @{ T = 'Compiled HTML Help (CHM)'; O = 0; H = '49545346'; E = @('.chm') }
    @{ T = 'WebAssembly'; O = 0; H = '0061736D'; E = @('.wasm') }
    @{ T = 'Android DEX'; O = 0; H = '6465780A'; E = @('.dex') }
    @{ T = 'PostScript'; O = 0; H = '2521'; E = @('.ps', '.eps') }
    @{ T = 'Windows minidump'; O = 0; H = '4D444D5093A7'; E = @('.dmp', '.mdmp') }
    @{ T = 'Windows hibernation / page file'; O = 0; H = '48494245'; E = @('.sys', '') }
    @{ T = 'ISO 9660 disk image'; O = 32769; H = '4344303031'; E = @('.iso', '.img') }
    @{ T = 'VHDX disk image'; O = 0; H = '7668647866696C65'; E = @('.vhdx') }
    @{ T = 'OneNote section'; O = 0; H = 'E4525C7B8CD8A74D'; E = @('.one') }
)

function Get-WfxFileMagic {
    <# Identifies a file by its header bytes (magic number). Returns the type name or ''. #>
    param([byte[]]$Head, [byte[]]$IsoProbe = $null)
    $hex = -join ($Head | Select-Object -First 32 | ForEach-Object { $_.ToString('X2') })
    foreach ($m in $script:WfxMagic) {
        if ($m.O -eq 0 -and $hex.StartsWith($m.H)) { return $m }
        if ($m.O -gt 0 -and $IsoProbe) { $ph = -join ($IsoProbe | ForEach-Object { $_.ToString('X2') }); if ($ph.StartsWith($m.H)) { return $m } }
    }
    # Text-ish fallbacks
    $s = [Text.Encoding]::ASCII.GetString($Head, 0, [Math]::Min(64, $Head.Length))
    if ($s -match '^#!') { return @{ T = 'Script (shebang)'; E = @() } }
    if ($s -match '^(?i)<\?xml') { return @{ T = 'XML'; E = @('.xml', '.config', '.manifest', '.xaml', '.svg', '.plist', '.xsl') } }
    if ($s -match '^(?i)\s*<(?:!doctype html|html)') { return @{ T = 'HTML'; E = @('.html', '.htm', '.hta', '.mht') } }
    return $null
}

function Get-WfxPrintableString {
    <# ASCII and UTF-16LE printable strings from a byte buffer (like `strings`). #>
    param([byte[]]$Bytes, [int]$MinLength = 6, [int]$Max = 5000)
    $out = New-Object System.Collections.Generic.List[string]
    $ascii = [Text.Encoding]::ASCII.GetString($Bytes)
    foreach ($m in (Get-WfxRxMatches ("[\x20-\x7E]{$MinLength,}") $ascii)) { if ($out.Count -ge $Max) { break }; $out.Add($m.Value) }
    $u16 = [Text.Encoding]::Unicode.GetString($Bytes, 0, $Bytes.Length - ($Bytes.Length % 2))
    foreach ($m in (Get-WfxRxMatches ("[\x20-\x7E]{$MinLength,}") $u16)) { if ($out.Count -ge $Max) { break }; $out.Add($m.Value) }
    , $out.ToArray()
}

function Get-WfxIocFromText {
    <# Extracts URLs, IPv4 addresses, domains, e-mail addresses and registry paths from text. #>
    param([string[]]$Text)
    $joined = $Text -join "`n"
    $pick = { param($rx) @(Get-WfxRxMatches $rx $joined | ForEach-Object { $_.Value.TrimEnd('.', ',', ')', ']', "'", '"') } | Sort-Object -Unique | Select-Object -First 200) }
    $urls = & $pick '(?i)\b(?:https?|ftp|wss?)://[^\s"''<>{}|\\^`]{4,300}'
    $ips = @(& $pick '\b(?:(?:25[0-5]|2[0-4]\d|1?\d?\d)\.){3}(?:25[0-5]|2[0-4]\d|1?\d?\d)\b' | Where-Object { $_ -notmatch '^(?:0\.|255\.)' })
    $mails = & $pick '(?i)\b[A-Z0-9._%+\-]{1,64}@[A-Z0-9.\-]{1,190}\.[A-Z]{2,24}\b'
    $doms = @(& $pick '(?i)\b(?:[a-z0-9](?:[a-z0-9\-]{0,61}[a-z0-9])?\.)+(?:com|net|org|io|ru|cn|top|xyz|info|biz|online|site|club|app|dev|cloud|me|cc|tk|su|onion|in|co|uk|de|fr|br|ir|kp|pw|ws|live|shop|link|click)\b' |
            Where-Object { $_ -notmatch '(?i)^(?:microsoft|windows|w3|xmlsoap|openxmlformats|purl|schemas)\.' })
    $reg = & $pick '(?i)\b(?:HKEY_[A-Z_]+|HK(?:LM|CU|CR|U))\\[^\s"''<>]{3,200}'
    [pscustomobject]@{ Urls = $urls; IPv4 = $ips; Domains = $doms; Emails = $mails; RegistryPaths = $reg }
}

function Get-WfxPeInfo {
    <# Minimal, read-only PE header parse: machine, compile time (UTC), DLL/EXE, subsystem, section names. #>
    param([byte[]]$Bytes)
    try {
        if ($Bytes.Length -lt 0x40 -or $Bytes[0] -ne 0x4D -or $Bytes[1] -ne 0x5A) { return $null }
        $pe = [BitConverter]::ToInt32($Bytes, 0x3C)
        if ($pe -le 0 -or $pe + 24 -gt $Bytes.Length -or [BitConverter]::ToUInt32($Bytes, $pe) -ne 0x00004550) { return $null }
        $machine = [BitConverter]::ToUInt16($Bytes, $pe + 4)
        $nsec = [BitConverter]::ToUInt16($Bytes, $pe + 6)
        $ts = [BitConverter]::ToUInt32($Bytes, $pe + 8)
        $optSize = [BitConverter]::ToUInt16($Bytes, $pe + 20)
        $chars = [BitConverter]::ToUInt16($Bytes, $pe + 22)
        $opt = $pe + 24
        $magic = [BitConverter]::ToUInt16($Bytes, $opt)
        $subsys = if ($opt + 70 -le $Bytes.Length) { [BitConverter]::ToUInt16($Bytes, $opt + 68) } else { 0 }
        $secs = New-Object System.Collections.Generic.List[string]
        $so = $opt + $optSize
        for ($i = 0; $i -lt [Math]::Min($nsec, 40) -and ($so + 40 * $i + 8) -le $Bytes.Length; $i++) {
            $secs.Add(([Text.Encoding]::ASCII.GetString($Bytes, $so + 40 * $i, 8)).TrimEnd([char]0))
        }
        [pscustomobject]@{
            Machine      = switch ($machine) { 0x14c { 'x86' } 0x8664 { 'x64' } 0xaa64 { 'ARM64' } 0x1c4 { 'ARMNT' } default { '0x{0:X}' -f $machine } }
            Format       = switch ($magic) { 0x10b { 'PE32' } 0x20b { 'PE32+' } default { '?' } }
            IsDll        = [bool]($chars -band 0x2000)
            Subsystem    = switch ($subsys) { 1 { 'Native/driver' } 2 { 'GUI' } 3 { 'Console' } 10 { 'EFI app' } default { [string]$subsys } }
            CompiledUtc  = if ($ts) { ConvertTo-WfxUtcString ([DateTime]::new(1970, 1, 1, 0, 0, 0, [DateTimeKind]::Utc).AddSeconds($ts)) } else { '' }
            Sections     = @($secs)
            PackerHint   = (@($secs | Where-Object { $_ -match '(?i)^(?:UPX\d?|\.aspack|\.adata|\.themida|\.vmp\d|\.petite|\.nsp\d|MPRESS\d)$' }) -join ',')
        }
    } catch { return $null }
}

function Get-WfxFileTriage {
    <#
    .SYNOPSIS
        Read-only forensic profile of one or more files — the "what is this file?" Swiss-army knife for
        incident responders and CTF players. Nothing is ever executed or modified.
    .DESCRIPTION
        For each file: size and UTC timestamps; MD5 / SHA-1 / SHA-256; true type from magic bytes and whether
        the extension lies about it; entropy (packed/encrypted?); Mark-of-the-Web zone + download URL;
        alternate data streams; Authenticode status and signer; PE header facts (machine, compile time,
        sections, packer hints); and optionally printable strings with extracted IOCs (URLs, IPs, domains,
        e-mails, registry paths). Reads at most -MaxReadMB of each file.
    .PARAMETER Path        Files (wildcards allowed) or pipeline input from Get-ChildItem.
    .PARAMETER Strings     Also extract printable strings and IOCs.
    .PARAMETER MinStringLength Minimum string length (default 6).
    .PARAMETER MaxReadMB   Bytes read per file for entropy/strings/PE parsing (default 8).
    .EXAMPLE
        Get-WfxFileTriage .\suspicious.bin -Strings | Format-List
    .EXAMPLE
        Get-ChildItem $env:USERPROFILE\Downloads -File | Get-WfxFileTriage | Where-Object ExtensionMismatch
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory, ValueFromPipeline, ValueFromPipelineByPropertyName)][Alias('FullName')][string[]]$Path,
        [switch]$Strings,
        [ValidateRange(3, 64)][int]$MinStringLength = 6,
        [ValidateRange(1, 512)][int]$MaxReadMB = 8
    )
    process {
        foreach ($pp in $Path) {
            $items = @($(if (Test-Path -LiteralPath $pp) { Get-Item -LiteralPath $pp -Force -ErrorAction SilentlyContinue } else { Get-Item -Path $pp -Force -ErrorAction SilentlyContinue }) | Where-Object { -not $_.PSIsContainer })
            if (-not $items.Count) { Write-Warning "Not found or not a file: $pp"; continue }
            foreach ($it in $items) {
                $full = $it.FullName
                $bytes = [byte[]]@()
                $iso = $null
                try {
                    $fs = [IO.File]::Open($full, 'Open', 'Read', 'ReadWrite')
                    try {
                        $len = [int][Math]::Min([int64]$MaxReadMB * 1MB, $fs.Length)
                        $bytes = New-Object byte[] $len
                        $read = 0; while ($read -lt $len) { $n = $fs.Read($bytes, $read, $len - $read); if ($n -le 0) { break }; $read += $n }
                        if ($fs.Length -gt 32774) {
                            $iso = New-Object byte[] 5; [void]$fs.Seek(32769, 'Begin'); [void]$fs.Read($iso, 0, 5)
                        }
                    } finally { $fs.Dispose() }
                } catch { Write-Warning "Cannot read $full`: $($_.Exception.Message)"; continue }

                $hashes = @{}
                foreach ($alg in 'MD5', 'SHA1', 'SHA256') { try { $hashes[$alg] = (Get-FileHash -LiteralPath $full -Algorithm $alg -ErrorAction Stop).Hash } catch { $hashes[$alg] = '' } }
                $magic = if ($bytes.Length) { Get-WfxFileMagic -Head ($bytes[0..([Math]::Min(63, $bytes.Length - 1))]) -IsoProbe $iso } else { $null }
                $ext = $it.Extension.ToLowerInvariant()
                $mismatch = [bool]($magic -and @($magic.E).Count -and ($ext -notin @($magic.E)))
                $motw = Get-WfxZoneId $full
                $streams = @()
                if (Test-WfxWindows) { try { $streams = @(Get-Item -LiteralPath $full -Stream * -ErrorAction Stop | Where-Object { $_.Stream -ne ':$DATA' } | ForEach-Object { "$($_.Stream) ($($_.Length) B)" }) } catch {} }
                $sig = $null
                if ((Test-WfxWindows) -and ($magic.T -like 'PE*' -or $ext -in @('.ps1', '.psm1', '.msi', '.cab', '.cat', '.vbs', '.js'))) {
                    try { $a = Get-AuthenticodeSignature -LiteralPath $full -ErrorAction Stop; $sig = [pscustomobject]@{ Status = [string]$a.Status; Signer = if ($a.SignerCertificate) { $a.SignerCertificate.Subject } else { '' }; Thumbprint = if ($a.SignerCertificate) { $a.SignerCertificate.Thumbprint } else { '' } } } catch {}
                }
                $str = @(); $iocs = $null
                if ($Strings -and $bytes.Length) {
                    $str = Get-WfxPrintableString -Bytes $bytes -MinLength $MinStringLength
                    $iocs = Get-WfxIocFromText -Text $str
                }
                $ent = if ($bytes.Length) { Get-WfxEntropy ([byte[]]$bytes) } else { 0.0 }
                [pscustomobject]@{
                    PSTypeName        = 'WinForensicX.FileTriage'
                    Path              = $full
                    Size              = $it.Length
                    CreatedUtc        = ConvertTo-WfxUtcString $it.CreationTimeUtc
                    ModifiedUtc       = ConvertTo-WfxUtcString $it.LastWriteTimeUtc
                    AccessedUtc       = ConvertTo-WfxUtcString $it.LastAccessTimeUtc
                    MD5               = $hashes.MD5
                    SHA1              = $hashes.SHA1
                    SHA256            = $hashes.SHA256
                    FileType          = if ($magic) { $magic.T } else { 'unknown / data' }
                    Extension         = $ext
                    ExtensionMismatch = $mismatch
                    Entropy           = $ent
                    EntropyHint       = if ($ent -ge 7.5) { 'near-random: compressed, encrypted or packed' } elseif ($ent -ge 6.5) { 'high: compressed sections likely' } elseif ($ent -le 1) { 'very low: mostly constant / padding' } else { 'normal' }
                    Zone              = $motw.Zone
                    HostUrl           = $motw.HostUrl
                    ReferrerUrl       = $motw.ReferrerUrl
                    AlternateStreams  = @($streams)
                    Signature         = $sig
                    PE                = (Get-WfxPeInfo -Bytes $bytes)
                    BytesExamined     = $bytes.Length
                    StringCount       = @($str).Count
                    Strings           = if ($Strings) { @($str | Select-Object -First 300) } else { @() }
                    Iocs              = $iocs
                }
            }
        }
    }
}


# ===== Public/Get-WfxInsight.ps1 =====
# Live, read-only "insight" views of a Windows host — fast answers to "show me X" without running a full
# triage. Every topic returns plain objects (so they can be filtered, sorted, exported or piped), never
# changes anything, and degrades with a clear message when it needs administrator rights.

function Get-WfxShort { param([AllowEmptyString()][string]$Text, [int]$Max = 120) if (-not $Text) { return '' }; $t = ($Text -replace '\s+', ' ').Trim(); if ($t.Length -gt $Max) { $t.Substring(0, $Max - 1) + '…' } else { $t } }

function Get-WfxRegValueSafe { param([string]$Path, [string]$Name) try { (Get-ItemProperty -LiteralPath $Path -Name $Name -ErrorAction Stop).$Name } catch { $null } }

$script:WfxLogonTypes = @{ '2' = 'Interactive'; '3' = 'Network'; '4' = 'Batch'; '5' = 'Service'; '7' = 'Unlock'; '8' = 'NetworkCleartext'; '9' = 'NewCredentials'; '10' = 'RemoteInteractive (RDP)'; '11' = 'CachedInteractive' }

$script:WfxInsightTopics = [ordered]@{
    # ───────────── System ─────────────
    'system'      = @{ Group = 'System'; Title = 'System overview'; Desc = 'OS, build, uptime, domain, hardware, time zone, Secure Boot, PowerShell.'; Admin = $false; Script = {
            $os = Get-CimInstance Win32_OperatingSystem; $cs = Get-CimInstance Win32_ComputerSystem
            $bios = Get-CimInstance Win32_BIOS -ErrorAction SilentlyContinue
            $sb = try { [string](Confirm-SecureBootUEFI -ErrorAction Stop) } catch { 'unknown (needs admin / UEFI)' }
            $up = (Get-Date) - $os.LastBootUpTime
            $info = [ordered]@{
                'Computer' = $env:COMPUTERNAME; 'Domain / workgroup' = $cs.Domain; 'Part of domain' = $cs.PartOfDomain
                'OS' = $os.Caption; 'Version / build' = "$($os.Version) (build $($os.BuildNumber))"; 'Architecture' = $os.OSArchitecture
                'Installed' = $os.InstallDate; 'Last boot' = $os.LastBootUpTime; 'Uptime' = ('{0}d {1}h {2}m' -f $up.Days, $up.Hours, $up.Minutes)
                'Manufacturer / model' = "$($cs.Manufacturer) $($cs.Model)"; 'BIOS serial' = $(if ($bios) { $bios.SerialNumber } else { '' })
                'Memory (GB)' = [Math]::Round($cs.TotalPhysicalMemory / 1GB, 1); 'Logged-on user (console)' = $cs.UserName
                'Time zone' = (Get-TimeZone).Id; 'Secure Boot' = $sb; 'PowerShell' = $PSVersionTable.PSVersion.ToString()
                'Running elevated' = (Test-WfxAdmin)
            }
            $info.GetEnumerator() | ForEach-Object { [pscustomobject]@{ Property = $_.Key; Value = [string]$_.Value } }
        }
    }
    'hotfixes'    = @{ Group = 'System'; Title = 'Installed updates (hotfixes)'; Desc = 'Windows updates and when they were installed — shows patch level.'; Admin = $false; Script = {
            Get-CimInstance Win32_QuickFixEngineering | Sort-Object { try { [datetime]$_.InstalledOn } catch { [datetime]::MinValue } } -Descending |
                Select-Object HotFixID, Description, InstalledOn, InstalledBy
        }
    }
    'software'    = @{ Group = 'System'; Title = 'Installed software'; Desc = 'Programs from the Uninstall registry keys (machine + per-user), newest first.'; Admin = $false; Script = {
            $keys = @('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*', 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*')
            Get-ChildItem 'Registry::HKEY_USERS' -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -match '^S-1-5-21-|^S-1-12-1-' -and $_.PSChildName -notmatch '_Classes$' } |
                ForEach-Object { $keys += "Registry::HKEY_USERS\$($_.PSChildName)\Software\Microsoft\Windows\CurrentVersion\Uninstall\*" }
            $rows = foreach ($k in $keys) {
                Get-ItemProperty -Path $k -ErrorAction SilentlyContinue | Where-Object { $_.DisplayName -and -not $_.SystemComponent } | ForEach-Object {
                    $d = [string]$_.InstallDate; $dt = $null
                    if ($d -match '^\d{8}$') { try { $dt = [datetime]::ParseExact($d, 'yyyyMMdd', $null) } catch {} }
                    [pscustomobject]@{ Name = $_.DisplayName; Version = $_.DisplayVersion; Publisher = $_.Publisher; Installed = $dt; Scope = $(if ($k -like 'Registry::HKEY_USERS*') { 'User' } elseif ($k -like '*WOW6432Node*') { 'Machine (32-bit)' } else { 'Machine' }); Location = $_.InstallLocation }
                }
            }
            $rows | Sort-Object Name, Version -Unique | Sort-Object @{ e = { if ($_.Installed) { $_.Installed } else { [datetime]::MinValue } } } -Descending
        }
    }
    'users'       = @{ Group = 'System'; Title = 'Local user accounts'; Desc = 'Local accounts, enabled state, last logon, password age.'; Admin = $false; Script = {
            if (Get-Command Get-LocalUser -ErrorAction SilentlyContinue) {
                Get-LocalUser | Select-Object Name, Enabled, LastLogon, PasswordLastSet, PasswordRequired, @{ n = 'SID'; e = { $_.SID.Value } }, Description
            } else { Get-CimInstance Win32_UserAccount -Filter 'LocalAccount=True' | Select-Object Name, @{ n = 'Enabled'; e = { -not $_.Disabled } }, SID, Description }
        }
    }
    'groups'      = @{ Group = 'System'; Title = 'Privileged local groups'; Desc = 'Members of Administrators, Remote Desktop Users, Remote Management Users, Backup Operators and similar.'; Admin = $false; Script = {
            foreach ($g in 'Administrators', 'Remote Desktop Users', 'Remote Management Users', 'Backup Operators', 'Hyper-V Administrators', 'Event Log Readers', 'Distributed COM Users') {
                $members = @()
                try { $members = @(Get-LocalGroupMember -Group $g -ErrorAction Stop | ForEach-Object { [pscustomobject]@{ Group = $g; Member = $_.Name; Type = [string]$_.ObjectClass; Source = [string]$_.PrincipalSource } }) }
                catch {
                    # Get-LocalGroupMember fails on orphaned SIDs; fall back to `net localgroup` (English output).
                    $out = @(net localgroup "$g" 2>$null)
                    if ($LASTEXITCODE -eq 0) {
                        $in = $false
                        $members = foreach ($l in $out) { if ($l -match '^-{5,}') { $in = $true; continue }; if ($in -and $l -and $l -notmatch 'command completed') { [pscustomobject]@{ Group = $g; Member = $l.Trim(); Type = ''; Source = 'net localgroup' } } }
                    }
                }
                $members
            }
        }
    }
    'sessions'    = @{ Group = 'System'; Title = 'Logged-on sessions'; Desc = 'Interactive and RDP sessions right now (quser).'; Admin = $false; Script = {
            $q = @(quser 2>$null)
            if ($q.Count -lt 2) { return [pscustomobject]@{ User = (Get-CimInstance Win32_ComputerSystem).UserName; Session = 'console'; State = 'Active'; Idle = ''; LogonTime = '' } }
            foreach ($l in ($q | Select-Object -Skip 1)) {
                $t = ($l.Substring(1) -split '\s{2,}')
                if ($t.Count -ge 5) { [pscustomobject]@{ User = $t[0]; Session = $t[1]; Id = $t[2]; State = $t[3]; Idle = $t[4]; LogonTime = ($t[5..($t.Count - 1)] -join ' ') } }
                elseif ($t.Count -eq 4) { [pscustomobject]@{ User = $t[0]; Session = ''; Id = $t[1]; State = $t[2]; Idle = $t[3]; LogonTime = '' } }
            }
        }
    }
    'profiles'    = @{ Group = 'System'; Title = 'User profiles on disk'; Desc = 'Every profile folder, its SID, and when it was last used.'; Admin = $false; Script = {
            Get-CimInstance Win32_UserProfile | Where-Object { -not $_.Special } | ForEach-Object {
                $n = try { (New-Object Security.Principal.SecurityIdentifier($_.SID)).Translate([Security.Principal.NTAccount]).Value } catch { '(unresolved)' }
                [pscustomobject]@{ Account = $n; Path = $_.LocalPath; LastUsed = $_.LastUseTime; Loaded = $_.Loaded; SID = $_.SID }
            } | Sort-Object LastUsed -Descending
        }
    }
    'shares'      = @{ Group = 'System'; Title = 'Network shares'; Desc = 'Folders shared from this host (custom shares are worth checking).'; Admin = $false; Script = {
            Get-CimInstance Win32_Share | Select-Object Name, Path, Description, @{ n = 'Kind'; e = { if ($_.Name -match '\$$') { 'Admin/hidden' } else { 'Custom' } } }
        }
    }
    'usb'         = @{ Group = 'System'; Title = 'USB storage history'; Desc = 'USB mass-storage devices ever connected (USBSTOR registry).'; Admin = $false; Script = {
            $root = 'HKLM:\SYSTEM\CurrentControlSet\Enum\USBSTOR'
            if (-not (Test-Path $root)) { return }
            foreach ($dev in Get-ChildItem $root -ErrorAction SilentlyContinue) {
                foreach ($inst in Get-ChildItem $dev.PSPath -ErrorAction SilentlyContinue) {
                    $p = Get-ItemProperty $inst.PSPath -ErrorAction SilentlyContinue
                    [pscustomobject]@{ Device = $(if ($p.FriendlyName) { $p.FriendlyName } else { $dev.PSChildName }); Serial = ($inst.PSChildName -replace '&\d$', ''); Class = $dev.PSChildName; Manufacturer = $p.Mfg -replace '^@.*;', '' }
                }
            }
        }
    }
    'volumes'     = @{ Group = 'System'; Title = 'Drives & encryption'; Desc = 'Disks, free space, file system and BitLocker status (BitLocker needs admin).'; Admin = $false; Script = {
            $bl = @{}; try { Get-BitLockerVolume -ErrorAction Stop | ForEach-Object { $bl[$_.MountPoint] = "$($_.ProtectionStatus) / $($_.VolumeStatus)" } } catch {}
            Get-CimInstance Win32_LogicalDisk | ForEach-Object {
                [pscustomobject]@{ Drive = $_.DeviceID; Label = $_.VolumeName; Type = @{ 2 = 'Removable'; 3 = 'Fixed'; 4 = 'Network'; 5 = 'CD/DVD' }[[int]$_.DriveType]; FileSystem = $_.FileSystem
                    SizeGB = [Math]::Round($_.Size / 1GB, 1); FreeGB = [Math]::Round($_.FreeSpace / 1GB, 1); BitLocker = $(if ($bl.ContainsKey($_.DeviceID)) { $bl[$_.DeviceID] } else { 'unknown' }); Network = $_.ProviderName }
            }
        }
    }

    # ───────────── Processes ─────────────
    'processes'   = @{ Group = 'Processes'; Title = 'Running processes (signed / owner / parent)'; Desc = 'Every process with user, signature status, company, parent and command line.'; Admin = $false; Script = {
            Get-WfxProcessData | Expand-WfxRecord | Add-WfxFlag Process | Sort-Object Name | Select-Object Flag, Why, Technique, Rule, Pid, Name, User, @{ n = 'Signature'; e = { $_.SignatureStatus } }, Company, @{ n = 'Parent'; e = { "$($_.ParentName) ($($_.Ppid))" } }, @{ n = 'Started'; e = { $_.CreateTime } }, @{ n = 'CommandLine'; e = { Get-WfxShort $_.CommandLine 160 } }, Path
        }
    }
    'tree'        = @{ Group = 'Processes'; Title = 'Process tree'; Desc = 'Parent → child hierarchy, so unusual chains stand out (e.g. winword → powershell).'; Admin = $false; Script = {
            $all = @(Get-CimInstance Win32_Process)
            $byPid = @{}; foreach ($p in $all) { $byPid[[int]$p.ProcessId] = $p }
            $kids = @{}
            foreach ($p in $all) {
                $pp = [int]$p.ParentProcessId; $parent = $byPid[$pp]
                if ($pp -eq [int]$p.ProcessId -or -not $parent -or ($parent.CreationDate -and $p.CreationDate -and $parent.CreationDate -gt $p.CreationDate)) { $pp = -1 }
                if (-not $kids.ContainsKey($pp)) { $kids[$pp] = New-Object System.Collections.Generic.List[object] }
                $kids[$pp].Add($p)
            }
            $rows = New-Object System.Collections.Generic.List[object]
            $walk = $null
            $walk = { param($ppid, $depth)
                if (-not $kids.ContainsKey($ppid) -or $depth -gt 40) { return }
                foreach ($c in ($kids[$ppid] | Sort-Object CreationDate)) {
                    $rows.Add([pscustomobject]@{ Tree = (('  ' * $depth) + $(if ($depth) { '└ ' } else { '' }) + $c.Name); Pid = [int]$c.ProcessId; Started = $c.CreationDate; CommandLine = (Get-WfxShort (Protect-WfxText $c.CommandLine) 140) })
                    & $walk ([int]$c.ProcessId) ($depth + 1)
                }
            }
            & $walk -1 0
            $rows
        }
    }
    'unsigned'    = @{ Group = 'Processes'; Title = 'Processes that are unsigned or run from user folders'; Desc = 'The short list worth a second look.'; Admin = $false; Script = {
            Get-WfxProcessData | Expand-WfxRecord | Add-WfxFlag Process | Where-Object { $_.Path -and (-not (Test-WfxTrustedSignature $_.SignatureStatus) -or (Test-WfxUserWritablePath $_.Path)) } |
                Select-Object Flag, Why, Technique, Rule, Pid, Name, User, @{ n = 'Signature'; e = { $_.SignatureStatus } }, Company, Path, @{ n = 'CommandLine'; e = { Get-WfxShort $_.CommandLine 140 } }
        }
    }

    # ───────────── Network ─────────────
    'listeners'   = @{ Group = 'Network'; Title = 'Listening ports'; Desc = 'Which programs accept network connections (TCP listen + UDP bound).'; Admin = $false; Script = {
            $paths = @{}; Get-CimInstance Win32_Process | ForEach-Object { $paths[[int]$_.ProcessId] = $_.ExecutablePath }
            Get-WfxNetworkData | Expand-WfxRecord | Add-WfxFlag Network | Where-Object { $_.State -in 'Listen', 'Bound' } | Sort-Object Protocol, LocalPort |
                Select-Object Flag, Why, Technique, Rule, Protocol, LocalAddress, LocalPort, Pid, Process, @{ n = 'Exposure'; e = { if ($_.LocalAddress -in '0.0.0.0', '::') { 'all interfaces' } elseif ($_.LocalAddress -match '^(127\.|::1)') { 'loopback only' } else { 'one interface' } } }, @{ n = 'Path'; e = { $paths[[int]$_.Pid] } }
        }
    }
    'connections' = @{ Group = 'Network'; Title = 'Active connections'; Desc = 'Established connections with process and name (from the DNS cache — no lookups are sent).'; Admin = $false; Script = {
            $map = Get-WfxDnsAddressMap -DnsEntry @(Get-WfxDnsData | Expand-WfxRecord)
            Get-WfxNetworkData | Expand-WfxRecord | Add-WfxFlag Network -DnsMap $map | Where-Object { $_.State -match 'Established|SynSent|CloseWait' } | Sort-Object Process |
                Select-Object Flag, Why, Technique, Rule, Process, Pid, LocalPort, RemoteAddress, RemotePort, State, @{ n = 'RemoteName'; e = { if ($map.ContainsKey([string]$_.RemoteAddress)) { @($map[[string]$_.RemoteAddress]) -join ', ' } else { '' } } }, @{ n = 'Public'; e = { -not (Test-WfxPrivateIp $_.RemoteAddress) } }
        }
    }
    'dns'         = @{ Group = 'Network'; Title = 'DNS cache'; Desc = 'Names this host resolved recently — a quick look at where it has been talking.'; Admin = $false; Script = { Get-WfxDnsData | Expand-WfxRecord | Add-WfxFlag Dns | Sort-Object Name | Select-Object Flag, Why, Technique, Rule, Name, Type, Data, TTL } }
    'adapters'    = @{ Group = 'Network'; Title = 'Network adapters & IP configuration'; Desc = 'IP addresses, gateways, DNS servers, DHCP, MAC.'; Admin = $false; Script = {
            Get-CimInstance Win32_NetworkAdapterConfiguration -Filter 'IPEnabled=True' | Select-Object Description, MACAddress, @{ n = 'IP'; e = { $_.IPAddress -join ', ' } }, @{ n = 'Gateway'; e = { $_.DefaultIPGateway -join ', ' } }, @{ n = 'DNS servers'; e = { $_.DNSServerSearchOrder -join ', ' } }, DHCPEnabled, DHCPServer, DNSDomain
        }
    }
    'routes'      = @{ Group = 'Network'; Title = 'Routing table'; Desc = 'IPv4 routes (unexpected routes can indicate tunnelling or pivoting).'; Admin = $false; Script = { Get-NetRoute -AddressFamily IPv4 -ErrorAction Stop | Sort-Object RouteMetric | Select-Object DestinationPrefix, NextHop, InterfaceAlias, RouteMetric } }
    'arp'         = @{ Group = 'Network'; Title = 'Neighbours (ARP cache)'; Desc = 'Hosts on the local network this machine has talked to.'; Admin = $false; Script = { Get-NetNeighbor -AddressFamily IPv4 -ErrorAction Stop | Where-Object { $_.State -notin 'Unreachable', 'Permanent' -or $_.IPAddress -notmatch '^(22[4-9]|23\d|255)\.' } | Select-Object IPAddress, LinkLayerAddress, State, InterfaceAlias } }
    'hosts'       = @{ Group = 'Network'; Title = 'hosts file entries'; Desc = 'Static name overrides (malware sometimes redirects security sites here).'; Admin = $false; Script = {
            $f = Join-Path $env:SystemRoot 'System32\drivers\etc\hosts'
            Get-Content -LiteralPath $f -ErrorAction Stop | Where-Object { $_ -match '^\s*[^#\s]' } | ForEach-Object { $t = ($_ -replace '#.*$', '').Trim() -split '\s+'; [pscustomobject]@{ Address = $t[0]; Names = ($t[1..($t.Count - 1)] -join ' ') } }
        }
    }
    'proxy'       = @{ Group = 'Network'; Title = 'Proxy settings'; Desc = 'System (WinHTTP) and user proxy / PAC settings — a classic traffic-interception trick.'; Admin = $false; Script = {
            $is = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Internet Settings'
            [pscustomobject]@{ Scope = 'User (WinINet)'; Enabled = [bool](Get-WfxRegValueSafe $is 'ProxyEnable'); Server = (Get-WfxRegValueSafe $is 'ProxyServer'); PacUrl = (Get-WfxRegValueSafe $is 'AutoConfigURL'); Bypass = (Get-WfxRegValueSafe $is 'ProxyOverride') }
            $w = (@(netsh winhttp show proxy 2>$null) -join ' ') -replace '\s+', ' '
            [pscustomobject]@{ Scope = 'System (WinHTTP)'; Enabled = ($w -notmatch 'Direct access'); Server = $(if ($w -match 'Proxy Server\(s\)\s*:\s*(\S+)') { $Matches[1] } else { '' }); PacUrl = ''; Bypass = $(if ($w -match 'Bypass List\s*:\s*(\S+)') { $Matches[1] } else { '' }) }
        }
    }
    'wifi'        = @{ Group = 'Network'; Title = 'Saved Wi-Fi networks (names only)'; Desc = 'Networks this host has joined. Keys are never shown.'; Admin = $false; Script = {
            @(netsh wlan show profiles 2>$null) | Where-Object { $_ -match ':\s*(.+)$' -and $_ -match 'Profile' } | ForEach-Object { [pscustomobject]@{ Network = ($_ -split ':\s*', 2)[1].Trim() } }
        }
    }
    'firewall'    = @{ Group = 'Network'; Title = 'Custom inbound firewall allow rules'; Desc = 'Enabled inbound "allow" rules that were not part of a built-in Windows rule group.'; Admin = $false; Script = {
            $prof = Get-NetFirewallProfile -ErrorAction SilentlyContinue | ForEach-Object { "$($_.Name)=$(if ($_.Enabled) { 'on' } else { 'OFF' })" }
            [pscustomobject]@{ Rule = "Profiles: $($prof -join ', ')"; Program = ''; Ports = ''; Profile = ''; Created = '' }
            Get-NetFirewallRule -Enabled True -Direction Inbound -Action Allow -ErrorAction Stop | Where-Object { -not $_.Group } | ForEach-Object {
                $app = try { ($_ | Get-NetFirewallApplicationFilter -ErrorAction Stop).Program } catch { '' }
                $port = try { (($_ | Get-NetFirewallPortFilter -ErrorAction Stop) | ForEach-Object { "$($_.Protocol) $($_.LocalPort)" }) -join ', ' } catch { '' }
                [pscustomobject]@{ Rule = $_.DisplayName; Program = $app; Ports = $port; Profile = [string]$_.Profile; Created = '' }
            }
        }
    }
    'smb'         = @{ Group = 'Network'; Title = 'SMB sessions to this host'; Desc = 'Who is connected to this machine''s shares right now (needs admin).'; Admin = $true; Script = { Get-SmbSession -ErrorAction Stop | Select-Object ClientComputerName, ClientUserName, NumOpens, SecondsExists, Dialect } }

    # ───────────── Persistence ─────────────
    'autoruns'    = @{ Group = 'Persistence'; Title = 'Autostart entries (Run keys, Startup, tasks, WMI, Winlogon, IFEO, …)'; Desc = 'Everything set to start automatically, with signature status.'; Admin = $false; Script = {
            Get-WfxPersistenceData | Expand-WfxRecord | Add-WfxFlag Autostart | Where-Object { $_.Kind -ne 'RunMRU' } | Sort-Object Kind, Name | Select-Object Flag, Why, Technique, Rule, Kind, Name, @{ n = 'Signature'; e = { $_.SignatureStatus } }, @{ n = 'Command'; e = { Get-WfxShort $_.Command 150 } }, Location, User
        }
    }
    'services'    = @{ Group = 'Persistence'; Title = 'Services that are not standard Windows services'; Desc = 'Services whose binary is outside Windows folders or not validly signed.'; Admin = $false; Script = {
            Get-WfxServiceAndDriver | Expand-WfxRecord | Add-WfxFlag Autostart | Where-Object { $_.Kind -eq 'Service' -and $_.Path -and (-not (Test-WfxSystemPath $_.Path) -or -not (Test-WfxTrustedSignature $_.SignatureStatus)) } |
                Sort-Object Name | Select-Object Flag, Why, Technique, Rule, Name, DisplayName, State, @{ n = 'Start'; e = { $_.Location -replace '^Service:' } }, User, @{ n = 'Signature'; e = { $_.SignatureStatus } }, Path
        }
    }
    'drivers'     = @{ Group = 'Persistence'; Title = 'Drivers outside System32\drivers or unsigned'; Desc = 'Kernel drivers worth checking (also flags known-vulnerable drivers in triage).'; Admin = $false; Script = {
            Get-WfxServiceAndDriver | Expand-WfxRecord | Add-WfxFlag Autostart | Where-Object { $_.Kind -eq 'Driver' -and ($_.Path -notmatch '(?i)\\system32\\drivers\\' -or -not (Test-WfxTrustedSignature $_.SignatureStatus)) } |
                Select-Object Flag, Why, Technique, Rule, Name, DisplayName, State, @{ n = 'Signature'; e = { $_.SignatureStatus } }, Path
        }
    }
    'tasks'       = @{ Group = 'Persistence'; Title = 'Scheduled tasks (non-Microsoft)'; Desc = 'Tasks outside \Microsoft\, with what they run, as whom, and last run time.'; Admin = $false; Script = {
            Get-ScheduledTask -ErrorAction Stop | Where-Object { $_.TaskPath -notlike '\Microsoft\*' } | ForEach-Object {
                $i = try { $_ | Get-ScheduledTaskInfo -ErrorAction Stop } catch { $null }
                $act = @($_.Actions | ForEach-Object { if ($_.Execute) { "$($_.Execute) $($_.Arguments)".Trim() } elseif ($_.ClassId) { "COM $($_.ClassId)" } }) -join ' ; '
                [pscustomobject]@{ Task = "$($_.TaskPath)$($_.TaskName)"; State = [string]$_.State; RunAs = $_.Principal.UserId; Action = (Get-WfxShort (Protect-WfxText $act) 160); _Text = (Protect-WfxText $act); Author = $_.Author; LastRun = $(if ($i) { $i.LastRunTime } else { $null }); NextRun = $(if ($i) { $i.NextRunTime } else { $null }) }
            } | Sort-Object LastRun -Descending
        }
    }
    'wmi'         = @{ Group = 'Persistence'; Title = 'WMI event subscriptions'; Desc = 'Filters, consumers and bindings in root\subscription (a stealthy persistence method).'; Admin = $false; Script = {
            foreach ($c in 'CommandLineEventConsumer', 'ActiveScriptEventConsumer', '__EventFilter', '__FilterToConsumerBinding') {
                Get-CimInstance -Namespace root\subscription -ClassName $c -ErrorAction SilentlyContinue | ForEach-Object {
                    [pscustomobject]@{ Type = $c; Name = [string]$_.Name; Detail = (Get-WfxShort (Protect-WfxText ([string]($_.CommandLineTemplate, $_.ScriptText, $_.Query, "$($_.Filter) -> $($_.Consumer)" | Where-Object { $_ } | Select-Object -First 1))) 160); _Text = (Protect-WfxText ([string]($_.CommandLineTemplate, $_.ScriptText | Where-Object { $_ } | Select-Object -First 1))) }
                }
            }
        }
    }

    # ───────────── Event logs ─────────────
    'logons'      = @{ Group = 'Events'; Title = 'Successful logons (summary)'; Desc = 'Who logged on, how (type) and from where, with first/last time (4624, needs admin).'; Admin = $true; Days = 7; Script = {
            param($Days)
            Get-WfxEventQuick -Log Security -Id 4624 -Days $Days -Max 20000 | Where-Object { $_.Fields.TargetUserName -notmatch '\$$|^(SYSTEM|LOCAL SERVICE|NETWORK SERVICE|DWM-\d+|UMFD-\d+|ANONYMOUS LOGON)$' } |
                Group-Object { "$($_.Fields.TargetDomainName)\$($_.Fields.TargetUserName)|$($_.Fields.LogonType)|$($_.Fields.IpAddress)" } | ForEach-Object {
                    $f = $_.Group[0].Fields; $t = $_.Group | Sort-Object Time
                    [pscustomobject]@{ User = "$($f.TargetDomainName)\$($f.TargetUserName)"; LogonType = "$($f.LogonType) $($script:WfxLogonTypes[[string]$f.LogonType])"; Source = $(if ($f.IpAddress -and $f.IpAddress -ne '-') { $f.IpAddress } else { $f.WorkstationName }); Count = $_.Count; First = $t[0].Time; Last = $t[-1].Time }
                } | Sort-Object Last -Descending
        }
    }
    'failedlogons' = @{ Group = 'Events'; Title = 'Failed logons (summary)'; Desc = 'Failed logons grouped by account and source — password guessing shows up here (4625).'; Admin = $true; Days = 7; Script = {
            param($Days)
            $reason = @{ '0xc000006a' = 'wrong password'; '0xc0000064' = 'no such user'; '0xc0000234' = 'locked out'; '0xc0000072' = 'disabled'; '0xc000006f' = 'outside hours'; '0xc0000071' = 'password expired'; '0xc0000193' = 'account expired' }
            Get-WfxEventQuick -Log Security -Id 4625 -Days $Days -Max 20000 | Group-Object { "$($_.Fields.TargetUserName)|$($_.Fields.IpAddress)" } | ForEach-Object {
                $f = $_.Group[0].Fields; $t = $_.Group | Sort-Object Time
                [pscustomobject]@{ User = $f.TargetUserName; Source = $(if ($f.IpAddress -and $f.IpAddress -ne '-') { $f.IpAddress } else { $f.WorkstationName }); Count = $_.Count; Reason = $reason[([string]$f.SubStatus).ToLower()]; First = $t[0].Time; Last = $t[-1].Time }
            } | Sort-Object Count -Descending
        }
    }
    'rdp'         = @{ Group = 'Events'; Title = 'Remote Desktop activity'; Desc = 'RDP authentications (1149) and RDP logons (4624 type 10).'; Admin = $true; Days = 30; Script = {
            param($Days)
            Get-WfxEventQuick -Log 'Microsoft-Windows-TerminalServices-RemoteConnectionManager/Operational' -Id 1149 -Days $Days -Max 2000 | ForEach-Object { [pscustomobject]@{ Time = $_.Time; Event = 'RDP auth (1149)'; User = "$($_.Fields.Param2)\$($_.Fields.Param1)"; Source = $_.Fields.Param3 } }
            Get-WfxEventQuick -Log Security -Id 4624 -Days $Days -Max 20000 | Where-Object { $_.Fields.LogonType -eq '10' } | ForEach-Object { [pscustomobject]@{ Time = $_.Time; Event = 'RDP logon (4624/10)'; User = "$($_.Fields.TargetDomainName)\$($_.Fields.TargetUserName)"; Source = $_.Fields.IpAddress } }
        }
    }
    'accounts'    = @{ Group = 'Events'; Title = 'Account & group changes'; Desc = 'Users created/deleted/enabled, password resets, group additions, lockouts.'; Admin = $true; Days = 30; Script = {
            param($Days)
            $name = @{ 4720 = 'User created'; 4722 = 'User enabled'; 4724 = 'Password reset'; 4726 = 'User deleted'; 4728 = 'Added to global group'; 4732 = 'Added to local group'; 4756 = 'Added to universal group'; 4740 = 'Account locked out'; 4738 = 'User changed' }
            Get-WfxEventQuick -Log Security -Id @($name.Keys) -Days $Days -Max 5000 | ForEach-Object {
                [pscustomobject]@{ Time = $_.Time; Change = $name[[int]$_.Id]; Target = $(if ($_.Fields.MemberName -and $_.Fields.MemberName -ne '-') { $_.Fields.MemberName } else { $_.Fields.TargetUserName }); Group = $(if ($_.Id -in 4728, 4732, 4756) { $_.Fields.TargetUserName } else { '' }); By = $_.Fields.SubjectUserName }
            }
        }
    }
    'newservices' = @{ Group = 'Events'; Title = 'Services installed'; Desc = 'New services (7045) — PsExec, remote-admin tools and many attacks install one.'; Admin = $false; Days = 30; Script = {
            param($Days)
            Get-WfxEventQuick -Log System -Id 7045 -Days $Days -Max 2000 | ForEach-Object { [pscustomobject]@{ Time = $_.Time; Service = $_.Fields.ServiceName; Binary = (Get-WfxShort (Protect-WfxText $_.Fields.ImagePath) 160); _Text = (Protect-WfxText $_.Fields.ImagePath); StartType = $_.Fields.StartType; Account = $_.Fields.AccountName } }
        }
    }
    'logclears'   = @{ Group = 'Events'; Title = 'Event logs cleared'; Desc = 'Security (1102) and other logs (104) being cleared — almost always intentional.'; Admin = $true; Days = 90; Script = {
            param($Days)
            Get-WfxEventQuick -Log Security -Id 1102 -Days $Days -Max 500 | ForEach-Object { [pscustomobject]@{ Time = $_.Time; Log = 'Security'; By = "$($_.Fields.SubjectDomainName)\$($_.Fields.SubjectUserName)" } }
            Get-WfxEventQuick -Log System -Id 104 -Days $Days -Max 500 | ForEach-Object { [pscustomobject]@{ Time = $_.Time; Log = $_.Fields.Channel; By = "$($_.Fields.SubjectDomainName)\$($_.Fields.SubjectUserName)" } }
        }
    }
    'reboots'     = @{ Group = 'Events'; Title = 'Startups, shutdowns and crashes'; Desc = 'Boot/shutdown times, unexpected shutdowns and who restarted the machine.'; Admin = $false; Days = 30; Script = {
            param($Days)
            $name = @{ 6005 = 'Event log started (boot)'; 6006 = 'Clean shutdown'; 6008 = 'Unexpected shutdown'; 1074 = 'Restart/shutdown requested'; 41 = 'Kernel power loss / crash' }
            Get-WfxEventQuick -Log System -Id 6005, 6006, 6008, 1074, 41 -Days $Days -Max 2000 | ForEach-Object {
                [pscustomobject]@{ Time = $_.Time; Event = $name[[int]$_.Id]; By = $_.Fields.param7; Process = $_.Fields.param1; Reason = $_.Fields.param3 }
            }
        }
    }
    'powershell'  = @{ Group = 'Events'; Title = 'PowerShell script blocks flagged as suspicious'; Desc = 'Script blocks PowerShell itself marked Warning (4104), newest first.'; Admin = $false; Days = 14; Script = {
            param($Days)
            Get-WfxEventQuick -Log 'Microsoft-Windows-PowerShell/Operational' -Id 4104 -Days $Days -Max 5000 | Where-Object { $_.Level -match 'Warn' } |
                ForEach-Object { [pscustomobject]@{ Time = $_.Time; ScriptBlockId = $_.Fields.ScriptBlockId; Path = $_.Fields.Path; Script = (Get-WfxShort (Protect-WfxText $_.Fields.ScriptBlockText) 200); _Text = (Protect-WfxText $_.Fields.ScriptBlockText) } }
        }
    }
    'defender'    = @{ Group = 'Events'; Title = 'Microsoft Defender detections'; Desc = 'Malware Defender found, the file, and whether it was removed.'; Admin = $false; Days = 90; Script = {
            param($Days)
            $th = @{}; try { Get-MpThreat -ErrorAction Stop | ForEach-Object { $th[[string]$_.ThreatID] = $_.ThreatName } } catch {}
            try {
                Get-MpThreatDetection -ErrorAction Stop | Where-Object { $_.InitialDetectionTime -ge (Get-Date).AddDays(-$Days) } | Sort-Object InitialDetectionTime -Descending | ForEach-Object {
                    [pscustomobject]@{ Time = $_.InitialDetectionTime; Threat = $th[[string]$_.ThreatID]; Resources = (Get-WfxShort (@($_.Resources) -join '; ') 160); Action = [string]$_.ActionSuccess; Process = $_.ProcessName; User = $_.DomainUser }
                }
            } catch {
                Get-WfxEventQuick -Log 'Microsoft-Windows-Windows Defender/Operational' -Id 1116, 1117 -Days $Days -Max 1000 | ForEach-Object { [pscustomobject]@{ Time = $_.Time; Threat = $_.Fields.'Threat Name'; Resources = $_.Fields.Path; Action = $(if ($_.Id -eq 1117) { 'action taken' } else { 'detected' }); Process = $_.Fields.'Process Name'; User = $_.Fields.'Detection User' } }
            }
        }
    }

    # ───────────── Files & user activity ─────────────
    'downloads'   = @{ Group = 'Files'; Title = 'Recent downloads (with source URL)'; Desc = 'Files in users'' Downloads folders, newest first, with the Mark-of-the-Web download URL.'; Admin = $false; Days = 14; Script = {
            param($Days)
            $cut = (Get-Date).AddDays(-$Days)
            foreach ($prof in (Get-WfxUserProfilePath)) {
                $d = Join-Path $prof 'Downloads'
                if (-not (Test-Path -LiteralPath $d)) { continue }
                Get-ChildItem -LiteralPath $d -File -Recurse -Depth 2 -ErrorAction SilentlyContinue | Where-Object { $_.LastWriteTime -ge $cut } | ForEach-Object {
                    $z = Get-WfxZoneId $_.FullName
                    [pscustomobject]@{ Modified = $_.LastWriteTime; File = $_.Name; SizeKB = [Math]::Round($_.Length / 1KB); Zone = $z.Zone; Source = $(if ($z.HostUrl) { $z.HostUrl } else { $z.ReferrerUrl }); Path = $_.FullName }
                }
            }
        }
    }
    'recentexe'   = @{ Group = 'Files'; Title = 'Recently written programs & scripts in user folders'; Desc = 'New .exe/.dll/.ps1/.js/.hta/… in Downloads, Desktop, Temp, AppData, ProgramData, Public.'; Admin = $false; Days = 7; Script = {
            param($Days)
            $cut = (Get-Date).AddDays(-$Days)
            $ext = @('.exe', '.dll', '.scr', '.ps1', '.bat', '.cmd', '.vbs', '.js', '.jse', '.hta', '.lnk', '.msi', '.iso', '.img', '.jar', '.wsf', '.one', '.xll', '.cpl')
            $dirs = @("$env:ProgramData", "$env:PUBLIC", "$env:SystemRoot\Temp") + @(Get-WfxUserProfilePath | ForEach-Object { "$_\Downloads"; "$_\Desktop"; "$_\AppData\Local\Temp"; "$_\AppData\Roaming"; "$_\AppData\Local" })
            foreach ($d in $dirs) {
                if (-not (Test-Path -LiteralPath $d)) { continue }
                Get-ChildItem -LiteralPath $d -File -Recurse -Depth 3 -ErrorAction SilentlyContinue | Where-Object { $_.LastWriteTime -ge $cut -and $_.Extension.ToLowerInvariant() -in $ext } |
                    Select-Object -First 300 | ForEach-Object { [pscustomobject]@{ Modified = $_.LastWriteTime; File = $_.Name; SizeKB = [Math]::Round($_.Length / 1KB); Signature = $(if ($_.Extension -in '.exe', '.dll', '.scr', '.msi', '.ps1') { Get-WfxSignature $_.FullName } else { '' }); Path = $_.FullName } }
            }
        }
    }
    'prefetch'    = @{ Group = 'Files'; Title = 'Program execution history (Prefetch)'; Desc = 'Programs that ran recently, from C:\Windows\Prefetch (needs admin; may be disabled on servers/SSDs).'; Admin = $true; Script = {
            Get-ChildItem -LiteralPath (Join-Path $env:SystemRoot 'Prefetch') -Filter *.pf -ErrorAction Stop | Sort-Object LastWriteTime -Descending | ForEach-Object {
                [pscustomobject]@{ LastRun = $_.LastWriteTime; Program = ($_.BaseName -replace '-[0-9A-F]{8}$', ''); FirstSeen = $_.CreationTime; PrefetchFile = $_.Name }
            }
        }
    }
    'recentfiles' = @{ Group = 'Files'; Title = 'Recently opened files (Recent items)'; Desc = 'Files and folders users opened, from their Recent shortcuts.'; Admin = $false; Days = 30; Script = {
            param($Days)
            $cut = (Get-Date).AddDays(-$Days)
            $(foreach ($prof in (Get-WfxUserProfilePath)) {
                $r = Join-Path $prof 'AppData\Roaming\Microsoft\Windows\Recent'
                Get-ChildItem -LiteralPath $r -Filter *.lnk -File -ErrorAction SilentlyContinue | Where-Object { $_.LastWriteTime -ge $cut } | ForEach-Object {
                    $lnk = Get-WfxLnkInfo -Path $_.FullName   # byte-level parse; nothing is resolved or run
                    [pscustomobject]@{ Opened = $_.LastWriteTime; Item = $_.BaseName; Target = $(if ($lnk) { $lnk.Target } else { '' }); TargetModifiedUtc = $(if ($lnk -and $lnk.Written) { ConvertTo-WfxUtcString $lnk.Written } else { '' }); User = (Split-Path -Leaf $prof) }
                }
            }) | Sort-Object Opened -Descending
        }
    }
    'pshistory'   = @{ Group = 'Files'; Title = 'PowerShell command history (redacted)'; Desc = 'Last commands typed in PowerShell per user (PSReadLine), with secrets redacted.'; Admin = $false; Script = {
            foreach ($prof in (Get-WfxUserProfilePath)) {
                $f = Join-Path $prof 'AppData\Roaming\Microsoft\Windows\PowerShell\PSReadLine\ConsoleHost_history.txt'
                if (-not (Test-Path -LiteralPath $f)) { continue }
                $lines = @(Get-Content -LiteralPath $f -Tail 50 -ErrorAction SilentlyContinue)
                $n = $lines.Count
                for ($i = 0; $i -lt $n; $i++) { [pscustomobject]@{ User = (Split-Path -Leaf $prof); Line = "-$($n - $i)"; Command = (Get-WfxShort (Protect-WfxText $lines[$i]) 200); _Text = (Protect-WfxText $lines[$i]) } }
            }
        }
    }
    'runmru'      = @{ Group = 'Files'; Title = 'Run-dialog history (Win+R)'; Desc = 'Commands typed into the Run box — where ClickFix / fake-CAPTCHA lures leave their command.'; Admin = $false; Script = {
            Get-WfxPersistenceData | Expand-WfxRecord | Add-WfxFlag Autostart | Where-Object Kind -eq 'RunMRU' | Select-Object Flag, Why, Technique, Rule, @{ n = 'Command'; e = { Get-WfxShort $_.Command 200 } }, Location
        }
    }

    # ───────────── Security posture ─────────────
    'posture'     = @{ Group = 'Security'; Title = 'Security posture checklist'; Desc = 'AV, firewall, UAC, LSA protection, Credential Guard, SMBv1, WDigest, LLMNR, logging, BitLocker, RDP — pass/fail with advice.'; Admin = $false; Script = {
            $s = Get-WfxSecurityData
            $row = { param($Check, $Ok, $Value, $Advice) [pscustomobject]@{ Check = $Check; Status = $(if ($null -eq $Ok) { 'UNKNOWN' } elseif ($Ok) { 'OK' } else { 'FIX' }); Value = [string]$Value; Advice = $(if ($Ok) { '' } else { $Advice }) } }
            $d = $s.Defender
            & $row 'Antivirus real-time protection' $(if ($d) { [bool]$d.RealTimeProtectionEnabled } elseif (@($s.ThirdPartyAV).Count) { $true } else { $null }) $(if ($d) { "Defender RTP=$($d.RealTimeProtectionEnabled)" } else { (@($s.ThirdPartyAV) -join ', ') }) 'Turn on real-time protection.'
            if ($d) {
                & $row 'Defender tamper protection' ([bool]$d.TamperProtectionEnabled) $d.TamperProtectionEnabled 'Enable Tamper Protection (Windows Security > Virus & threat protection settings).'
                & $row 'Defender signatures up to date' ($null -ne $d.SignatureAgeDays -and $d.SignatureAgeDays -le 3) "$($d.SignatureAgeDays) day(s) old" 'Update signatures.'
            }
            $fw = $s.Firewall
            if ($fw) { foreach ($p in 'Domain', 'Private', 'Public') { & $row "Firewall ($p profile)" ([bool](Get-WfxValue $fw $p $false)) (Get-WfxValue $fw $p '') "Enable the $p firewall profile." } }
            $lua = Get-WfxRegValueSafe 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System' 'EnableLUA'
            & $row 'User Account Control (UAC)' ($lua -ne 0) "EnableLUA=$lua" 'Re-enable UAC.'
            & $row 'LSASS protection (RunAsPPL)' ([bool]$s.Lsa.RunAsPPL) $s.Lsa.RunAsPPL 'Enable LSA protection to make credential dumping harder.'
            & $row 'Credential Guard running' ([bool]$s.Lsa.CredentialGuard) $s.Lsa.CredentialGuard 'Enable Credential Guard where supported.'
            $wd = Get-WfxRegValueSafe 'HKLM:\SYSTEM\CurrentControlSet\Control\SecurityProviders\WDigest' 'UseLogonCredential'
            & $row 'WDigest clear-text credentials off' ($wd -ne 1) "UseLogonCredential=$wd" 'Set UseLogonCredential to 0 (attackers enable it to harvest passwords).'
            $smb1 = try { [bool](Get-SmbServerConfiguration -ErrorAction Stop).EnableSMB1Protocol } catch { $null }
            & $row 'SMBv1 server disabled' $(if ($null -eq $smb1) { $null } else { -not $smb1 }) "EnableSMB1Protocol=$smb1" 'Disable SMBv1.'
            $llmnr = Get-WfxRegValueSafe 'HKLM:\SOFTWARE\Policies\Microsoft\Windows NT\DNSClient' 'EnableMulticast'
            & $row 'LLMNR disabled (blocks poisoning)' ($llmnr -eq 0) "EnableMulticast=$(if ($null -eq $llmnr) { 'not set (on)' } else { $llmnr })" 'Disable LLMNR by policy.'
            & $row 'Process-creation auditing (4688)' $s.Audit.ProcessCreation $s.Audit.ProcessCreation 'Enable "Audit Process Creation" (success).'
            & $row 'Command line in 4688' ([bool]$s.Audit.CommandLineInProcessCreation) $s.Audit.CommandLineInProcessCreation 'Enable "Include command line in process creation events".'
            & $row 'PowerShell script-block logging' ([bool]$s.Audit.ScriptBlockLogging) $s.Audit.ScriptBlockLogging 'Enable script-block logging.'
            & $row 'Sysmon installed' ([bool]$s.Audit.SysmonInstalled) $s.Audit.SysmonInstalled 'Consider deploying Sysmon for richer telemetry.'
            if ($s.Rdp) { & $row 'RDP requires NLA (if RDP on)' ((-not $s.Rdp.Enabled) -or $s.Rdp.NlaEnabled) "Enabled=$($s.Rdp.Enabled) NLA=$($s.Rdp.NlaEnabled)" 'Require Network Level Authentication.' }
            $al = Get-WfxRegValueSafe 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon' 'AutoAdminLogon'
            & $row 'Automatic logon disabled' ($al -ne '1') "AutoAdminLogon=$al" 'Disable auto-logon (it stores a password in the registry).'
            $sys = Get-WfxRegValueSafe 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System' 'LocalAccountTokenFilterPolicy'
            & $row 'Remote UAC for local admins on' ($sys -ne 1) "LocalAccountTokenFilterPolicy=$sys" 'Set to 0 to limit pass-the-hash with local accounts.'
            $last = Get-CimInstance Win32_QuickFixEngineering -ErrorAction SilentlyContinue | ForEach-Object { try { [datetime]$_.InstalledOn } catch {} } | Sort-Object -Descending | Select-Object -First 1
            & $row 'Updates installed in last 45 days' $(if ($last) { $last -ge (Get-Date).AddDays(-45) } else { $null }) $last 'Install the latest cumulative update.'
        }
    }
}

# ── Suspicious-activity checks for views that have no triage analyzer ───────────────────────────────
# Each check receives one row and calls Add-WfxVerdict / Add-WfxCommandVerdict. Properties starting with "_"
# carry the full (unshortened, redacted) text for checks and are removed before display.
# Value: 'first' = flagged rows are listed first (inventory views); 'keep' = keep the view's own order (time lines).
$script:WfxFlagTopic = [ordered]@{
    processes = 'first'; unsigned = 'first'; listeners = 'first'; connections = 'first'; dns = 'first'
    autoruns = 'first'; services = 'first'; drivers = 'first'; tasks = 'first'; wmi = 'first'; runmru = 'first'
    software = 'first'; users = 'first'; shares = 'first'; hosts = 'first'; firewall = 'first'; prefetch = 'first'
    downloads = 'first'; recentexe = 'first'; failedlogons = 'first'
    pshistory = 'keep'; powershell = 'keep'; newservices = 'keep'; logclears = 'keep'; accounts = 'keep'; rdp = 'keep'; defender = 'keep'
    changes = 'keep'; regchanges = 'keep'; filechanges = 'keep'; deleted = 'keep'; installs = 'keep'; executions = 'keep'; connhistory = 'keep'; configchanges = 'keep'
}
$script:WfxRiskyExt = '(?i)\.(?:iso|img|vhdx?|lnk|hta|js|jse|vbs|vbe|wsf|wsh|one|xll|cpl|scr|pif|bat|cmd|ps1|msc|jar|appref-ms|library-ms|search-ms|url)$'
$script:WfxDoubleExt = '(?i)\.(?:pdf|docx?|xlsx?|pptx?|jpe?g|png|gif|txt|rtf|zip|rar|mp4|mp3)\.(?:exe|scr|com|pif|js|jse|vbs|vbe|wsf|hta|bat|cmd|lnk|ps1)$'
$script:WfxProxyExec = @('mshta.exe', 'hh.exe', 'cmstp.exe', 'installutil.exe', 'regasm.exe', 'regsvcs.exe', 'msbuild.exe', 'odbcconf.exe', 'certutil.exe', 'bitsadmin.exe', 'msxsl.exe', 'wmic.exe', 'forfiles.exe', 'pcalua.exe', 'mavinject.exe', 'presentationhost.exe')
$script:WfxSecurityDomains = '(?i)(?:^|\.)(?:microsoft|windowsupdate|msftncsi|msftconnecttest|smartscreen|wdcp|virustotal|kaspersky|eset|sophos|symantec|norton|crowdstrike|sentinelone|malwarebytes|avast|avg|bitdefender|mcafee|trendmicro|f-secure|webroot|carbonblack|cylance|paloaltonetworks|fortinet|clamav|elastic|cisco|zscaler|withsecure|emsisoft|gdata|drweb|comodo)\.[a-z.]+$'

function Get-WfxThreatList {
    param([ValidateSet('offensiveProcesses', 'rmmProcesses')][string]$Name)
    if (-not $script:WfxThreatCache) { $script:WfxThreatCache = @{} }
    if (-not $script:WfxThreatCache.ContainsKey($Name)) {
        $script:WfxThreatCache[$Name] = try { @((Get-WfxRulePack -Name 'threats').$Name) } catch { @() }
    }
    , $script:WfxThreatCache[$Name]
}

function Test-WfxProductName {
    <# Does an installed-program display name contain one of the tool names (e.g. "AnyDesk" ~ anydesk.exe)? #>
    param([string]$DisplayName, [object[]]$List)
    $d = ($DisplayName -replace '[^A-Za-z0-9]', '').ToLowerInvariant()
    if (-not $d) { return '' }
    foreach ($x in $List) {
        $n = (([string]$x).Trim() -replace '\.exe$', '' -replace '[^A-Za-z0-9]', '').ToLowerInvariant()
        if ($n.Length -ge 5 -and $d.Contains($n)) { return ([string]$x).Trim() }
    }
    ''
}

$script:WfxInsightChecks = @{
    tasks = { param($r) Add-WfxCommandVerdict -InputObject $r -Text $r._Text -Context 'scheduled task' -CheckImagePath }
    wmi = {
        param($r)
        if ($r.Type -in 'CommandLineEventConsumer', 'ActiveScriptEventConsumer') { Add-WfxVerdict $r 'High' 'Permanent WMI consumer that runs a command or script on an event trigger' @('T1546.003') }
        Add-WfxCommandVerdict -InputObject $r -Text $r._Text -Context 'WMI consumer'
    }
    pshistory = { param($r) Add-WfxCommandVerdict -InputObject $r -Text $r._Text -Context 'PowerShell history' }
    powershell = {
        param($r)
        Add-WfxVerdict $r 'Medium' 'PowerShell itself marked this script block as suspicious (logged as a warning)' @('T1059.001')
        Add-WfxCommandVerdict -InputObject $r -Text $r._Text -Context 'script block'
    }
    newservices = {
        param($r)
        if ([string]$r.Service -match '(?i)^(?:PSEXESVC|PAExec\S*|RemComSvc|csexecsvc|winexesvc|BTOBTO|SMBExec\S*)$') { Add-WfxVerdict $r 'High' 'Service name used by remote-execution tools (PsExec, PAExec, Impacket …)' @('T1569.002', 'T1021.002') }
        if ([string]$r._Text -match '(?i)\\\\[^\\]+\\(?:admin|c)\$|^\s*"?(?:%COMSPEC%|cmd(?:\.exe)?)\b.*/c|powershell') { Add-WfxVerdict $r 'High' 'Service runs a shell command or a binary from an admin share' @('T1543.003', 'T1569.002') }
        Add-WfxCommandVerdict -InputObject $r -Text $r._Text -Context 'new service' -CheckImagePath
    }
    logclears = { param($r) Add-WfxVerdict $r 'High' 'The Security event log was cleared (evidence destroyed)' @('T1070.001') }
    failedlogons = {
        param($r)
        $n = [int]$r.Count
        $what = if ([string]$r.Reason -eq 'no such user') { 'non-existent account (enumeration / spraying)' } else { 'repeated failures (password guessing)' }
        if ($n -ge 50) { Add-WfxVerdict $r 'High' "$n failed logons: $what" @('T1110') } elseif ($n -ge 10) { Add-WfxVerdict $r 'Medium' "$n failed logons: $what" @('T1110') }
    }
    accounts = {
        param($r)
        if ($r.Change -eq 'User created') { Add-WfxVerdict $r 'Medium' 'New local account created' @('T1136.001') }
        if ([string]$r.Change -like 'Added to*' -and [string]$r.Group -match '(?i)^(?:Administrators|Domain Admins|Enterprise Admins|Backup Operators)$') { Add-WfxVerdict $r 'High' "Account added to $($r.Group)" @('T1098') }
        elseif ([string]$r.Change -like 'Added to*' -and [string]$r.Group -match '(?i)^(?:Remote Desktop Users|Remote Management Users)$') { Add-WfxVerdict $r 'Medium' "Account given remote access ($($r.Group))" @('T1098') }
        if ($r.Change -eq 'User enabled' -and [string]$r.Target -match '(?i)(?:^|\\)(?:Guest|Administrator|DefaultAccount)$') { Add-WfxVerdict $r 'Medium' "Built-in account enabled: $($r.Target)" @('T1078') }
    }
    rdp = { param($r) if ($r.Source -and -not (Test-WfxPrivateIp ([string]$r.Source))) { Add-WfxVerdict $r 'Medium' "RDP logon from a public address ($($r.Source))" @('T1021.001', 'T1133') } }
    defender = {
        param($r)
        if ([string]$r.Action -eq 'True') { Add-WfxVerdict $r 'Medium' "Defender detection (remediated): $($r.Threat)" }
        else { Add-WfxVerdict $r 'High' "Defender detection NOT confirmed remediated: $($r.Threat)" }
    }
    hosts = {
        param($r)
        $names = @(([string]$r.Names) -split '\s+' | Where-Object { $_ })
        $sec = @($names | Where-Object { $_ -match $script:WfxSecurityDomains })
        if ($sec.Count) { Add-WfxVerdict $r 'High' "Security / update site overridden in the hosts file: $($sec -join ', ')" @('T1562.001') }
        elseif ([string]$r.Address -notmatch '^(?:127\.|0\.0\.0\.0$|::1?$)') { Add-WfxVerdict $r 'Low' 'Static name-to-address mapping — confirm it is intended (can redirect traffic)' @('T1565.001') }
    }
    firewall = {
        param($r)
        if ([string]$r.Rule -like 'Profiles:*' -and [string]$r.Rule -match '=OFF') { Add-WfxVerdict $r 'Medium' 'Windows Firewall is turned off for at least one profile' @('T1562.004') }
        if ($r.Program -and (Test-WfxUserWritablePath ([string]$r.Program))) { Add-WfxVerdict $r 'Medium' 'Inbound allow rule for a program in a user-writable folder' @('T1562.004') }
    }
    prefetch = {
        param($r)
        $p = [string]$r.Program
        if (Test-WfxNameInList $p (Get-WfxThreatList offensiveProcesses)) { Add-WfxVerdict $r 'High' "Known offensive / credential-theft tool ran: $p" @('T1588.002') }
        elseif (Test-WfxNameInList $p (Get-WfxThreatList rmmProcesses)) { Add-WfxVerdict $r 'Medium' "Remote-access tool ran: $p" @('T1219') }
        elseif (Test-WfxNameInList $p $script:WfxProxyExec) { Add-WfxVerdict $r 'Low' "Proxy-execution capable Windows binary ran (review the context): $p" @('T1218') }
    }
    downloads = {
        param($r)
        $f = [string]$r.File
        if ($f -match $script:WfxDoubleExt) { Add-WfxVerdict $r 'High' 'Disguised double extension (e.g. invoice.pdf.exe)' @('T1036.007') }
        if (Test-WfxNameInList $f (Get-WfxThreatList offensiveProcesses)) { Add-WfxVerdict $r 'High' "Known offensive tool downloaded: $f" @('T1588.002') }
        if ($f -match $script:WfxRiskyExt) { Add-WfxVerdict $r 'Medium' 'File type commonly used to deliver malware (disk image, shortcut, script, OneNote, HTA …)' @('T1204.002') }
        elseif ($f -match '(?i)\.(?:exe|msi|dll|msix|appx)$') { Add-WfxVerdict $r 'Low' 'Executable downloaded — confirm its origin (Source) and signature' @('T1204.002') }
    }
    recentexe = {
        param($r)
        $f = [string]$r.File; $path = [string]$r.Path
        if ($f -match $script:WfxDoubleExt) { Add-WfxVerdict $r 'High' 'Disguised double extension (e.g. invoice.pdf.exe)' @('T1036.007') }
        if ($path -match '(?i)\\Start Menu\\Programs\\Startup\\') { Add-WfxVerdict $r 'High' 'In a Startup folder — runs at every logon' @('T1547.001') }
        if (Test-WfxNameInList $f (Get-WfxThreatList offensiveProcesses)) { Add-WfxVerdict $r 'High' "Known offensive tool on disk: $f" @('T1588.002') }
        if ($f -match '(?i)\.(?:exe|dll|scr|msi)$' -and $r.Signature -and -not (Test-WfxTrustedSignature ([string]$r.Signature)) -and (Test-WfxUserWritablePath $path)) { Add-WfxVerdict $r 'Medium' "Unsigned binary in a user-writable folder (signature: $($r.Signature))" @('T1204.002') }
        if ($f -match '(?i)\.scr$') { Add-WfxVerdict $r 'Medium' 'Screen-saver executable (.scr) — rarely legitimate outside System32' @('T1546.002') }
    }
    software = {
        param($r)
        $rmm = Test-WfxProductName ([string]$r.Name) (Get-WfxThreatList rmmProcesses)
        if ($rmm) { Add-WfxVerdict $r 'Medium' "Remote-access software installed (matches $rmm) — confirm it is sanctioned" @('T1219') }
        $off = Test-WfxProductName ([string]$r.Name) (Get-WfxThreatList offensiveProcesses)
        if ($off) { Add-WfxVerdict $r 'Low' "Dual-use / offensive tool installed (matches $off)" @('T1588.002') }
    }
    users = {
        param($r)
        if ($r.Enabled -eq $true -and [string]$r.Name -eq 'Guest') { Add-WfxVerdict $r 'Medium' 'Guest account is enabled' @('T1078') }
        if ($r.Enabled -eq $true -and $r.PSObject.Properties['PasswordRequired'] -and $r.PasswordRequired -eq $false) { Add-WfxVerdict $r 'Medium' 'Enabled account that does not require a password' @('T1078') }
        if ($r.Enabled -eq $true -and [string]$r.SID -match '-500$') { Add-WfxVerdict $r 'Low' 'Built-in Administrator account is enabled' @('T1078') }
    }
    shares = {
        param($r)
        if ($r.Kind -eq 'Custom' -and [string]$r.Path -match '^[A-Za-z]:\\?$') { Add-WfxVerdict $r 'Medium' "Entire drive shared ($($r.Path))" @('T1039') }
        elseif ($r.Kind -eq 'Custom' -and [string]$r.Path -match '(?i)\\Users(?:\\|$)') { Add-WfxVerdict $r 'Low' 'User profile folder shared' @('T1039') }
    }
}

function Get-WfxInsight {
    <#
    .SYNOPSIS
        Live, read-only views of this Windows host: system, users, software, processes, network, autostarts,
        event-log summaries, recent files and security posture. Returns objects you can sort, filter and export.
    .PARAMETER Topic  A topic key (run Get-WfxInsight -List to see them all).
    .PARAMETER Days   Look-back for time-based topics (each topic has a sensible default).
    .PARAMETER List   List available topics.
    .EXAMPLE
        Get-WfxInsight -List
    .EXAMPLE
        Get-WfxInsight logons -Days 3 | Format-Table
    .EXAMPLE
        Get-WfxInsight listeners | Where-Object Exposure -eq 'all interfaces'
    #>
    [CmdletBinding(DefaultParameterSetName = 'Topic')]
    param(
        [Parameter(ParameterSetName = 'Topic', Mandatory, Position = 0)][string]$Topic,
        [Parameter(ParameterSetName = 'Topic')][ValidateRange(1, 3650)][int]$Days = 0,
        [Parameter(ParameterSetName = 'List')][switch]$List
    )
    if ($List) {
        return $script:WfxInsightTopics.GetEnumerator() | ForEach-Object { [pscustomobject]@{ Topic = $_.Key; Group = $_.Value.Group; Title = $_.Value.Title; NeedsAdmin = [bool]$_.Value.Admin; Description = $_.Value.Desc } }
    }
    $t = $script:WfxInsightTopics[$Topic]
    if (-not $t) { throw "Unknown topic '$Topic'. Run Get-WfxInsight -List." }
    if (-not (Test-WfxWindows)) { throw 'Live views need Windows.' }
    if ($t.Admin -and -not (Test-WfxAdmin)) { Write-Warning "'$($t.Title)' needs administrator rights — results will be empty or partial. Re-run elevated." }
    $d = if ($Days) { $Days } elseif ($t.Days) { [int]$t.Days } else { 7 }
    $gapsBefore = $script:WfxGaps.Count
    Clear-WfxViewPattern
    $rows = @(if ($t.Days) { & $t.Script $d | Expand-WfxRecord } else { & $t.Script | Expand-WfxRecord })
    $mode = $script:WfxFlagTopic[$Topic]
    if ($mode) {
        $check = $script:WfxInsightChecks[$Topic]
        if ($check) {
            foreach ($r in $rows) {
                if ($r -is [string] -or $r -is [System.ValueType]) { continue }
                try { & $check $r } catch { Add-WfxGap -Source "flags:$Topic" -Reason "A suspicious-activity check failed on one row: $($_.Exception.Message)" }
            }
        }
        $rows = @($rows | Complete-WfxFlagRow)
        if ($mode -eq 'first') {
            # Stable: flagged rows by severity, each group keeping the view's own order.
            $i = 0
            $rows = @($rows | ForEach-Object { [pscustomobject]@{ R = $_; K = -$script:WfxFlagRank[[string]$_.Flag]; N = $i++ } } | Sort-Object K, N | ForEach-Object { $_.R })
        }
    }
    $rows
    foreach ($p in (Get-WfxViewPattern)) { Write-Warning ("PATTERN [{0}] {1} {2}" -f $p.Severity, $p.Text, $(if ($p.Technique) { "($($p.Technique))" })) }
    # Say why results may be incomplete (missing rights, disabled logs, journal window ...).
    for ($g = $gapsBefore; $g -lt $script:WfxGaps.Count; $g++) { Write-Warning ("{0}: {1} {2}" -f $script:WfxGaps[$g].Source, $script:WfxGaps[$g].Reason, $script:WfxGaps[$g].Fix) }
}

function Save-WfxInsight {
    <#
    .SYNOPSIS Exports insight topics (default: all) to a case folder: one CSV per topic, an HTML inventory
    page and a SHA-256 manifest. A full "what does this machine look like" snapshot for a ticket or baseline.
    .EXAMPLE
        Save-WfxInsight -OutputPath E:\cases
    .EXAMPLE
        Save-WfxInsight -Topic system, software, users, groups, listeners
    #>
    [CmdletBinding()]
    param([string[]]$Topic = @(), [string]$OutputPath = '', [switch]$NoOpen)
    if (-not (Test-WfxWindows)) { throw 'Live views need Windows.' }
    $keys = if ($Topic.Count) { $Topic } else { @($script:WfxInsightTopics.Keys) }
    $case = New-WfxCase -OutputPath $OutputPath -Name 'inventory' -HostName ([Environment]::MachineName) -Mode 'inventory' -Parameters @{ Topics = $keys }
    $dir = Join-Path $case.Path 'insights'; New-Item -ItemType Directory -Path $dir -Force | Out-Null
    $sections = New-Object System.Text.StringBuilder
    $toc = New-Object System.Text.StringBuilder
    $flagged = New-Object System.Collections.Generic.List[object]
    $i = 0
    foreach ($k in $keys) {
        $i++
        $t = $script:WfxInsightTopics[$k]; if (-not $t) { continue }
        Write-WfxConsole ("  [{0}/{1}] {2,-52}" -f $i, $keys.Count, $t.Title) -NoNewline
        $sw = [Diagnostics.Stopwatch]::StartNew()
        $rows = @(); $err = ''
        try { $rows = @(Get-WfxInsight -Topic $k -WarningAction SilentlyContinue) } catch { $err = $_.Exception.Message; Add-WfxGap -Source "insight:$k" -Reason $err }
        Write-WfxConsole ("{0,6:N1}s  {1}" -f $sw.Elapsed.TotalSeconds, $(if ($err) { 'unavailable' } else { "$($rows.Count) rows" })) -Kind $(if ($err) { 'Warn' } else { 'Dim' })
        if ($rows.Count) { $rows | Export-Csv -Path (Join-Path $dir "$k.csv") -NoTypeInformation -Encoding UTF8 }
        $enc = [System.Net.WebUtility]
        $hits = @($rows | Where-Object { $_.PSObject.Properties['Flag'] -and $_.Flag -and $_.Flag -ne 'INFO' })
        foreach ($h in $hits) { $flagged.Add([pscustomobject]@{ Flag = $h.Flag; View = $t.Title; Why = $h.Why; Technique = $h.Technique; Key = $k }) }
        $badge = if ($hits.Count) { " <em>$($hits.Count) flagged</em>" } else { '' }
        [void]$toc.Append("<li><a href=""#$k"">$($enc::HtmlEncode($t.Title))</a> <span>$($rows.Count)$badge</span></li>")
        # ConvertTo-Html encodes every value; the severity cell is then turned into a badge.
        $body = if ($err) { "<p class=""err"">Unavailable: $($enc::HtmlEncode($err))</p>" } elseif (-not $rows.Count) { '<p class="none">Nothing found.</p>' } else { (($rows | Select-Object -First 1000 | ConvertTo-Html -Fragment) -join "`n") -replace '<tr><td>(CRITICAL|HIGH|MEDIUM|LOW)</td>', '<tr class="f-$1"><td><b class="b-$1">$1</b></td>' }
        [void]$sections.Append("<section id=""$k""><h2>$($enc::HtmlEncode($t.Group)) · $($enc::HtmlEncode($t.Title))</h2><p class=""d"">$($enc::HtmlEncode($t.Desc))</p>$body</section>")
    }
    $hn = [System.Net.WebUtility]::HtmlEncode([Environment]::MachineName)
    $enc = [System.Net.WebUtility]
    $rank = $script:WfxFlagRank
    $top = @($flagged | Sort-Object @{ e = { -$rank[[string]$_.Flag] } }, View | Select-Object -First 300)
    $summary = if ($top.Count) {
        $li = foreach ($f in $top) { "<tr class=""f-$($f.Flag)""><td><b class=""b-$($f.Flag)"">$($f.Flag)</b></td><td><a href=""#$($f.Key)"">$($enc::HtmlEncode($f.View))</a></td><td>$($enc::HtmlEncode($f.Why))</td><td>$($enc::HtmlEncode($f.Technique))</td></tr>" }
        "<section id=""flagged""><h2>Suspicious items across all views ($(Get-WfxFlagSummary $flagged))</h2><p class=""d"">Rows that matched a suspicious-activity rule. Each is a lead to verify, not a verdict; the absence of flags is not proof that the host is clean.</p><table><tr><th>Flag</th><th>View</th><th>Why</th><th>ATT&amp;CK</th></tr>$($li -join '')</table></section>"
    } else { "<section id=""flagged""><h2>Suspicious items across all views</h2><p class=""none"">No row matched a suspicious-activity rule. This is not proof that the host is clean — run a full triage for event-log, file and memory-resident analysis.</p></section>" }
    $html = @"
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Inventory · $hn</title>
<style>html{font-variant-ligatures:none;font-feature-settings:"calt" 0,"liga" 0,"clig" 0}body{font:14px system-ui,Segoe UI,sans-serif;margin:0;color:#1b1f24;background:#f6f7f9}header{background:#14181f;color:#fff;padding:18px 24px}header small{color:#9aa4b2}
main{display:grid;grid-template-columns:260px 1fr;gap:20px;padding:20px}nav ul{list-style:none;padding:0;margin:0;position:sticky;top:12px}nav li{display:flex;justify-content:space-between;padding:3px 0}nav a{color:#2457c5;text-decoration:none}nav span{color:#8a93a0}
section{background:#fff;border:1px solid #e3e6ea;border-radius:10px;padding:14px 16px;margin-bottom:16px;overflow-x:auto}h2{font-size:16px;margin:0 0 4px}.d{color:#5b6470;margin:0 0 10px}.err{color:#b42318}.none{color:#8a93a0}
table{border-collapse:collapse;font-size:12.5px;min-width:100%}th{text-align:left;background:#f0f2f5;position:sticky;top:0;white-space:nowrap}td,th{border-bottom:1px solid #eceef1;padding:5px 8px;vertical-align:top}td{max-width:460px;overflow-wrap:anywhere}td:first-child{white-space:nowrap}
nav em{color:#b42318;font-style:normal;font-weight:600;margin-left:4px}tr.f-CRITICAL td,tr.f-HIGH td{background:#fdf1f0}tr.f-MEDIUM td{background:#fdf7ec}
b[class^=b-]{display:inline-block;white-space:nowrap;font-size:11px;letter-spacing:.04em;padding:2px 6px;border-radius:3px}.b-CRITICAL{background:#7a0e0e;color:#fff}.b-HIGH{background:#c0362c;color:#fff}.b-MEDIUM{background:#e8a33d;color:#1b1300}.b-LOW{background:#d5e3f2;color:#123}
@media(max-width:800px){main{grid-template-columns:1fr}}*,*::before,*::after{font-variant-ligatures:none!important;font-feature-settings:"calt" 0,"liga" 0,"clig" 0!important}
</style></head><body>
<header><b>WinForensicX · system inventory</b> — $hn<br><small>Collected $(Get-WfxUtcNow) UTC · read-only snapshot · WinForensicX $script:WfxVersion</small></header>
<main><nav><ul><li><a href="#flagged"><b>Suspicious items</b></a> <span>$(if ($flagged.Count) { "<em>$($flagged.Count)</em>" } else { '0' })</span></li>$($toc.ToString())</ul></nav><div>$summary$($sections.ToString())</div></main></body></html>
"@
    [IO.File]::WriteAllText((Join-Path $case.Path 'inventory.html'), $html, (New-Object Text.UTF8Encoding($false)))
    $null = Complete-WfxCase
    Write-WfxConsole ''
    Write-WfxConsole "Inventory: $(Join-Path $case.Path 'inventory.html')" -Kind Info
    if (-not $NoOpen) { try { Start-Process (Join-Path $case.Path 'inventory.html') } catch {} }
    return $case.Path
}

# ───────────── Recent changes (listed first in the menu) ─────────────
$script:WfxActivityTopics = [ordered]@{
    'changes'       = @{ Group = 'Recent changes'; Title = 'Everything that changed recently (combined timeline)'; Desc = 'Registry, installs, services, tasks, accounts, firewall, Defender, executions, connections, deletions — newest first.'; Admin = $false; Days = 7; Script = { param($Days) Get-WfxActivityData -Days $Days | Expand-WfxRecord | Add-WfxFlag Activity | Select-Object Flag, Why, Technique, Rule, Time, Category, Action, Target, Actor, Detail, Source } }
    'regchanges'    = @{ Group = 'Recent changes'; Title = 'Registry changes in persistence & security locations'; Desc = 'Run keys, Winlogon, IFEO, UAC-bypass handlers, LSA/WDigest, Defender exclusions, firewall rules, services, tasks, uninstall keys — by last-write time.'; Admin = $false; Days = 7; Script = { param($Days) Get-WfxRegistryActivity -Days $Days | Expand-WfxRecord | Add-WfxFlag Activity | Select-Object Flag, Why, Technique, Rule, Time, Action, Target, Detail } }
    'filechanges'   = @{ Group = 'Recent changes'; Title = 'File system changes (NTFS change journal)'; Desc = 'Files created, deleted, content changed, renamed, alternate streams and timestamp changes on the system drive (needs admin).'; Admin = $true; Days = 2; Script = { param($Days) Get-WfxUsnActivity -Days $Days | Expand-WfxRecord | Add-WfxFlag Activity | Select-Object Flag, Why, Technique, Rule, Time, Action, Target } }
    'deleted'       = @{ Group = 'Recent changes'; Title = 'Deleted files (Recycle Bin + Sysmon)'; Desc = 'What users deleted, from where, when, and whether it can still be recovered.'; Admin = $false; Days = 30; Script = { param($Days) @(Get-WfxRecycleBinActivity -Days $Days | Expand-WfxRecord) + @(Get-WfxEventActivity -Days $Days | Expand-WfxRecord | Where-Object { $_.Action -eq 'File deleted' }) | Sort-Object Time -Descending | Add-WfxFlag Activity | Select-Object Flag, Why, Technique, Rule, Time, Action, Target, Detail, Actor, Source } }
    'installs'      = @{ Group = 'Recent changes'; Title = 'Software & driver installs / removals'; Desc = 'MSI installs and removals, new drivers and services, and newly written uninstall entries.'; Admin = $false; Days = 30; Script = { param($Days) @(Get-WfxEventActivity -Days $Days | Expand-WfxRecord | Where-Object { $_.Category -in 'Software', 'Service' }) + @(Get-WfxRegistryActivity -Days $Days | Expand-WfxRecord | Where-Object { $_.Action -like 'Software*' }) | Sort-Object Time -Descending | Add-WfxFlag Activity | Select-Object Flag, Why, Technique, Rule, Time, Action, Target, Detail, Source } }
    'executions'    = @{ Group = 'Recent changes'; Title = 'Programs that ran (Prefetch, BAM, UserAssist)'; Desc = 'Execution evidence with full paths where available — including programs that are no longer running.'; Admin = $false; Days = 7; Script = { param($Days) Get-WfxExecutionActivity -Days $Days | Expand-WfxRecord | Sort-Object Time -Descending | Add-WfxFlag Activity | Select-Object Flag, Why, Technique, Rule, Time, Action, Target, Actor, Detail } }
    'connhistory'   = @{ Group = 'Recent changes'; Title = 'Connection history'; Desc = 'Outbound connections recorded by Sysmon, Windows Filtering Platform (5156), the firewall log, the live table and saved RDP targets.'; Admin = $false; Days = 3; Script = { param($Days) Get-WfxConnectionActivity -Days $Days | Expand-WfxRecord | Sort-Object Time -Descending | Add-WfxFlag Activity | Select-Object Flag, Why, Technique, Rule, Time, Action, Target, Actor, Detail, Source } }
    'configchanges' = @{ Group = 'Recent changes'; Title = 'Security-relevant configuration changes'; Desc = 'Accounts, groups, scheduled tasks, audit policy, firewall rules, Defender settings, time changes, log clearing, BITS, WMI.'; Admin = $false; Days = 14; Script = { param($Days) Get-WfxEventActivity -Days $Days | Expand-WfxRecord | Where-Object { $_.Category -notin 'Software', 'File' } | Sort-Object Time -Descending | Add-WfxFlag Activity | Select-Object Flag, Why, Technique, Rule, Time, Category, Action, Target, Actor, Detail } }
}
$i = 0
foreach ($k in $script:WfxActivityTopics.Keys) { $script:WfxInsightTopics.Insert($i, $k, $script:WfxActivityTopics[$k]); $i++ }

function Get-WfxActivity {
    <#
    .SYNOPSIS "What changed recently?" — registry writes in persistence/security locations, software and driver
    installs, services, tasks, accounts, firewall and Defender changes, program executions, connection history,
    deletions, and (with -Journal, admin) the NTFS change journal. Newest first.
    .EXAMPLE
        Get-WfxActivity -Days 2 | Where-Object Category -eq 'Registry'
    .EXAMPLE
        Get-WfxActivity -Days 1 -Journal | Export-Csv changes.csv -NoTypeInformation
    #>
    [CmdletBinding()]
    param([ValidateRange(1, 365)][int]$Days = 7, [switch]$Journal)
    if (-not (Test-WfxWindows)) { throw 'Live views need Windows.' }
    Get-WfxActivityData -Days $Days -Journal:$Journal | Expand-WfxRecord
}


# ===== Public/Invoke-WfxAnalyze.ps1 =====
function Invoke-WfxAnalyze {
    <#
    .SYNOPSIS
        Runs every analyzer over a collection bundle and returns a scored result. Pure and OS-neutral:
        it works on any machine, so an analyst can re-analyze evidence collected elsewhere.
    .DESCRIPTION
        Each analyzer is isolated: if one fails (e.g. a rule pack is missing or a record is malformed) the
        failure is recorded as an analysis gap and the remaining analyzers still run.
        Two scores are produced:
          • Risk    — evidence of compromise / attacker activity (what an incident responder acts on first).
          • Posture — hardening and visibility gaps (what an administrator should fix).
    .PARAMETER Bundle
        A bundle object from Get-WfxCollectionBundle, OR a path to a bundle JSON file (raw/bundle.json),
        OR a directory that contains one.
    .PARAMETER HostName
        Override the host label (defaults to the bundle's HostName).
    .PARAMETER AllowlistPath
        JSON allowlist of known-good findings to suppress (see Read-WfxAllowlist). Defaults to $env:WFX_ALLOWLIST.
    .OUTPUTS
        [pscustomobject] winforensicx.result/2
    .EXAMPLE
        Invoke-WfxAnalyze -Bundle 'D:\cases\WFX_host_20260101\raw\bundle.json'
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory, ValueFromPipeline)]$Bundle,
        [string]$HostName = '',
        [string]$AllowlistPath = $env:WFX_ALLOWLIST
    )

    process {
        if ($Bundle -is [string]) { $Bundle = Read-WfxBundle -Path $Bundle }
        if (-not $HostName) { $HostName = [string](Get-WfxValue $Bundle 'HostName' ([Environment]::MachineName)) }
        $gaps = New-Object System.Collections.Generic.List[object]
        foreach ($g in @(Get-WfxValue $Bundle 'Gaps' @())) { if ($g) { $gaps.Add($g) } }

        $all = New-Object System.Collections.Generic.List[object]
        $run = {
            param([string]$Name, [scriptblock]$Body)
            try { foreach ($f in @(& $Body | ForEach-Object { $_ } | Where-Object { $_ })) { $all.Add($f) } }
            catch { $gaps.Add([pscustomobject]@{ Source = "analyzer:$Name"; Reason = $_.Exception.Message; Fix = 'Restore the missing/invalid rule pack or report the malformed record.' }) }
        }

        $events = @(Get-WfxValue $Bundle 'Events' @())
        # DNS evidence: the DNS cache plus Sysmon 22 (DNS query) events, when present.
        $dns = @(Get-WfxValue $Bundle 'Dns' @()) + @($events | Where-Object { (ConvertTo-WfxInt (Get-WfxValue $_ 'Id' 0)) -eq 22 -and [string](Get-WfxValue $_ 'Log' '') -match 'Sysmon' } | ForEach-Object {
                $q = [string](Get-WfxValue (Get-WfxValue $_ 'Fields' @{}) 'QueryName' '')
                if ($q) { [pscustomobject]@{ Name = $q; Type = 'Sysmon22'; Data = '' } } })
        $dnsMap = Get-WfxDnsAddressMap -DnsEntry $dns

        & $run 'process'     { Invoke-WfxProcessAnalyzer     -Process    @(Get-WfxValue $Bundle 'Process' @())     -HostName $HostName }
        & $run 'network'     { Invoke-WfxNetworkAnalyzer     -Connection @(Get-WfxValue $Bundle 'Network' @())     -HostName $HostName -DnsMap $dnsMap }
        & $run 'dns'         { Invoke-WfxDnsAnalyzer         -DnsEntry   $dns                                      -HostName $HostName }
        & $run 'persistence' { Invoke-WfxPersistenceAnalyzer -Autostart  @(Get-WfxValue $Bundle 'Persistence' @()) -HostName $HostName }
        & $run 'events'      { Invoke-WfxEventAnalyzer       -Event      $events                                   -HostName $HostName }
        $activity = @(Get-WfxValue $Bundle 'Activity' @())
        & $run 'activity'    { Invoke-WfxActivityAnalyzer    -Activity   $activity                                 -HostName $HostName }
        & $run 'files'       { Invoke-WfxFileAnalyzer        -File       @(Get-WfxValue $Bundle 'Files' @())       -HostName $HostName }
        & $run 'exposure'    { Invoke-WfxExposureAnalyzer    -Exposure   @(Get-WfxValue $Bundle 'Exposure' @())    -HostName $HostName }
        & $run 'posture'     { Invoke-WfxPostureAnalyzer     -Posture    (Get-WfxValue $Bundle 'Security' $null)   -HostName $HostName }
        $ransom = Get-WfxValue $Bundle 'Ransom' $null
        if ($ransom) {
            & $run 'ransomware' { Invoke-WfxRansomwareAnalyzer -Note @(Get-WfxValue $ransom 'Note' @()) -RecentFile @(Get-WfxValue $ransom 'RecentFile' @()) -HostName $HostName }
        }

        # Gaps raised while loading rules / analyzing (custom-pack parse errors, rejected rules) belong to this result.
        foreach ($g in @(Get-WfxGap)) { if ($g -and -not ($gaps | Where-Object { $_.Source -eq $g.Source -and $_.Reason -eq $g.Reason })) { $gaps.Add($g) } }

        $merged = Merge-WfxFinding -Finding $all.ToArray()
        $allow = @()
        if ($AllowlistPath) {
            try { $allow = Read-WfxAllowlist -Path $AllowlistPath }
            catch { $gaps.Add([pscustomobject]@{ Source = 'allowlist'; Reason = $_.Exception.Message; Fix = 'Fix the allowlist path / JSON.' }) }
        }
        $split = Split-WfxAllowlisted -Finding $merged -Allowlist $allow
        $findings = @($split.Kept)

        $compromise = @($findings | Where-Object { -not (Test-WfxPostureFinding $_) })
        $postureF = @($findings | Where-Object { Test-WfxPostureFinding $_ })
        $risk = Get-WfxRiskScore -Finding $compromise
        $posture = Get-WfxRiskScore -Finding $postureF
        $summary = Get-WfxSeveritySummary -Finding $findings

        # ATT&CK coverage: distinct techniques observed, resolved to tactic/name.
        $techIds = @($findings | ForEach-Object { $_.Technique } | Where-Object { $_ } | Sort-Object -Unique)
        $coverage = foreach ($t in $techIds) { Get-WfxAttackTechnique $t }

        [pscustomobject]@{
            Schema         = 'winforensicx.result/2'
            HostName       = $HostName
            Analyzed       = (Get-WfxUtcNow)
            Collected      = (ConvertTo-WfxUtcString (Get-WfxValue $Bundle 'Collected' ''))
            ToolVersion    = $script:WfxVersion
            Host           = (Get-WfxValue $Bundle 'Host' $null)
            Risk           = $risk
            Posture        = $posture
            Summary        = $summary
            Findings       = @($findings)
            Suppressed     = @($split.Suppressed)
            Activity       = @($activity | Sort-Object { [string]$_.Time } -Descending | Select-Object -First 3000)
            ActivityTotal  = $activity.Count
            AttackCoverage = @($coverage)
            Gaps           = @($gaps.ToArray())
            Meta           = (Get-WfxValue $Bundle 'Meta' $null)
        }
    }
}

function Read-WfxBundle {
    <# Loads a bundle from a bundle.json path or a case folder (looks for bundle.json and raw/bundle.json). #>
    param([Parameter(Mandatory)][string]$Path)
    $p = Resolve-WfxBundlePath -Path $Path
    Get-Content -LiteralPath $p -Raw -Encoding UTF8 | ConvertFrom-Json
}

function Resolve-WfxBundlePath {
    param([Parameter(Mandatory)][string]$Path)
    if (Test-Path -LiteralPath $Path -PathType Container) {
        $cand = @((Join-Path $Path 'bundle.json'), (Join-Path (Join-Path $Path 'raw') 'bundle.json'))
        $p = @($cand | Where-Object { Test-Path -LiteralPath $_ }) | Select-Object -First 1
        if (-not $p) { throw "No bundle.json found under '$Path'." }
        return (Resolve-Path -LiteralPath $p).Path
    }
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { throw "Bundle path not found: $Path" }
    return (Resolve-Path -LiteralPath $Path).Path
}

function Get-WfxDnsAddressMap {
    <# IP -> resolved names, built from DNS-cache A/AAAA records. Used to name connection endpoints offline,
       so the tool never has to send its own reverse-DNS queries from the host under investigation. #>
    param([object[]]$DnsEntry)
    $map = @{}
    foreach ($d in @($DnsEntry | Where-Object { $_ })) {
        $data = [string](Get-WfxValue $d 'Data' '')
        $name = [string](Get-WfxValue $d 'Name' '')
        if (-not $data -or -not $name) { continue }
        $ip = $null
        if ([System.Net.IPAddress]::TryParse($data, [ref]$ip)) {
            if (-not $map.ContainsKey($data)) { $map[$data] = New-Object System.Collections.Generic.List[string] }
            if (-not $map[$data].Contains($name.ToLowerInvariant())) { $map[$data].Add($name.ToLowerInvariant()) }
        }
    }
    $map
}


# ===== Public/Invoke-WfxHunt.ps1 =====
function Invoke-WfxHunt {
    <#
    .SYNOPSIS
        Sweeps a host (or a saved bundle) for specific indicators of compromise — file hashes, IP
        addresses, domains, file names or arbitrary strings — and reports every place each one appears.
    .DESCRIPTION
        Matching is type-aware so results are precise:
          • Hashes (MD5/SHA-1/SHA-256) — exact match against file hashes in the bundle. Live hunts with
            -FileScan compute all three for scanned files; -HashProcesses also hashes running/autostart binaries.
          • IPv4/IPv6 — exact address match (1.2.3.4 does NOT match 11.2.3.45).
          • Domains — the name itself or any subdomain (evil.com matches a.evil.com, not notevil.com).
          • Anything else — case-insensitive substring.
        Searched: processes, network, DNS cache, persistence, event logs (message + fields), files, exposure paths.
        Results are written to a hunt case folder (hunt.json / hunt.csv / manifest) unless -NoCase.
    .PARAMETER Ioc          One or more indicators.
    .PARAMETER IocFile      Text file with one indicator per line ('#' comments and blank lines ignored).
    .PARAMETER InputPath    Hunt inside a previously saved case/bundle instead of collecting live.
    .PARAMETER Hours        Event look-back when collecting live (default 72).
    .PARAMETER FileScan     Include the file scan when collecting live (lets hash/name IOCs match files).
    .PARAMETER HashProcesses Hash the binaries of running processes, services and autostarts (slower).
    .EXAMPLE
        Invoke-WfxHunt -Ioc 'evil.com','1.2.3.4','44d88612fea8a8f36de82e1278abb02f' -FileScan
    .EXAMPLE
        Invoke-WfxHunt -IocFile .\advisory-iocs.txt -InputPath C:\cases\WFX_host_20260101-000000Z
    #>
    [CmdletBinding()]
    param(
        [string[]]$Ioc = @(),
        [string]$IocFile = '',
        [string]$InputPath = '',
        [ValidateRange(1, 8760)][int]$Hours = 72,
        [switch]$FileScan,
        [switch]$HashProcesses,
        [string]$OutputPath = '',
        [switch]$NoCase,
        [switch]$PassThru
    )
    $list = @($Ioc)
    if ($IocFile) {
        if (-not (Test-Path -LiteralPath $IocFile -PathType Leaf)) { throw "IOC file not found: $IocFile" }
        $list += @(Get-Content -LiteralPath $IocFile | ForEach-Object { ($_ -replace '#.*$', '').Trim() })
    }
    # Accept defanged indicators from advisories: hxxp, [.] and (.)
    $iocs = @($list | Where-Object { $_ } | ForEach-Object { ($_.Trim() -replace '\[\.\]|\(\.\)', '.' -replace '^hxxp', 'http') } | Where-Object { $_ } | Sort-Object -Unique)
    if (-not $iocs.Count) { Write-WfxConsole 'No IOCs supplied.' -Kind Warn; return }

    if ($InputPath) {
        $bundle = Read-WfxBundle -Path $InputPath
    } else {
        if (-not (Test-WfxWindows)) { Write-WfxConsole 'Live hunt requires Windows (or pass -InputPath).' -Kind Bad; return }
        $bundle = Get-WfxCollectionBundle -Hours $Hours -FileScan:$FileScan
    }
    $hn = [string](Get-WfxValue $bundle 'HostName' ([Environment]::MachineName))

    # Build a flat, searchable index of (where, text, context) rows from the bundle.
    $rows = New-Object System.Collections.Generic.List[object]
    $push = { param($Where, $Text, $Ctx) if ($Text) { $rows.Add([pscustomobject]@{ Where = $Where; Text = [string]$Text; Ctx = $Ctx }) } }
    $hashCache = @{}
    $hashFile = {
        param($Path, $Ctx)
        if (-not $Path -or -not (Test-WfxWindows) -or -not (Test-Path -LiteralPath $Path -PathType Leaf)) { return }
        if (-not $hashCache.ContainsKey($Path)) {
            $h = @{}
            foreach ($alg in 'MD5', 'SHA1', 'SHA256') { try { $h[$alg] = (Get-FileHash -LiteralPath $Path -Algorithm $alg -ErrorAction Stop).Hash } catch {} }
            $hashCache[$Path] = $h
        }
        foreach ($v in $hashCache[$Path].Values) { & $push 'hash' $v "$Ctx ($Path)" }
    }
    foreach ($p in @(Get-WfxValue $bundle 'Process' @())) {
        $ctx = "pid $($p.Pid) $($p.Name)"
        & $push 'process' $p.Name $ctx; & $push 'process' $p.Path $ctx; & $push 'process' $p.CommandLine $ctx
        if ($HashProcesses -and -not $InputPath) { & $hashFile $p.Path $ctx }
    }
    foreach ($c in @(Get-WfxValue $bundle 'Network' @())) {
        $ctx = "$($c.Process) $($c.LocalAddress):$($c.LocalPort) → $($c.RemoteAddress):$($c.RemotePort) $($c.State)"
        & $push 'network' $c.RemoteAddress $ctx; & $push 'network' $c.LocalAddress $ctx; & $push 'network' $c.RemoteHost $ctx
    }
    foreach ($d in @(Get-WfxValue $bundle 'Dns' @())) { & $push 'dns' $d.Name "dns cache → $($d.Data)"; & $push 'dns' (Get-WfxValue $d 'Data' '') "dns cache: $($d.Name)" }
    foreach ($a in @(Get-WfxValue $bundle 'Persistence' @())) {
        $ctx = "$($a.Kind): $($a.Name)"
        & $push 'persistence' $a.Command $ctx; & $push 'persistence' $a.Path $ctx
        if ($HashProcesses -and -not $InputPath) { & $hashFile $a.Path $ctx }
    }
    foreach ($e in @(Get-WfxValue $bundle 'Events' @())) {
        $ctx = "event $($e.Id) $($e.Log) @ $($e.TimeCreated)"
        & $push 'event' (Get-WfxValue $e 'Message' '') $ctx
        $fl = Get-WfxValue $e 'Fields' $null
        if ($fl) {
            $pairs = if ($fl -is [System.Collections.IDictionary]) { $fl.GetEnumerator() } else { $fl.PSObject.Properties }
            foreach ($kv in $pairs) { & $push 'event' ([string]$kv.Value) "$ctx [$($kv.Name)]" }
        }
    }
    foreach ($f in @(Get-WfxValue $bundle 'Files' @())) {
        & $push 'file' $f.Path 'file'
        foreach ($hk in 'SHA256', 'SHA1', 'MD5') { & $push 'hash' (Get-WfxValue $f $hk '') "$hk of $($f.Path)" }
        & $push 'file' (Get-WfxValue $f 'HostUrl' '') "download source of $($f.Path)"
        if (-not $InputPath -and (Test-WfxWindows)) { & $hashFile $f.Path 'file' }
    }
    foreach ($a in @(Get-WfxValue $bundle 'Activity' @())) { $ctx = "$($a.Category): $($a.Action) @ $($a.Time)"; & $push 'activity' $a.Target $ctx; & $push 'activity' $a.Detail $ctx; & $push 'activity' $a.Actor $ctx }
    foreach ($x in @(Get-WfxValue $bundle 'Exposure' @())) { & $push 'exposure' $x.Path "$($x.Kind)" }

    $findings = New-Object System.Collections.Generic.List[object]
    foreach ($i in $iocs) {
        $kind = Get-WfxIocKind $i
        $rx = switch ($kind) {
            'ip' { if ($i.Contains(':')) { '(?i)(?<![\d.:A-Fa-f])' + [regex]::Escape($i) + '(?![\d.:A-Fa-f])' } else { '(?<![\d.])' + [regex]::Escape($i) + '(?![\d]|\.\d)' } }
            'domain' { '(?i)(?<![A-Za-z0-9\-.])(?:[A-Za-z0-9\-]+\.)*' + [regex]::Escape($i) + '(?![A-Za-z0-9\-])' }
            default { $null }
        }
        foreach ($row in $rows) {
            $match = switch ($kind) {
                'hash' { $row.Where -eq 'hash' -and $row.Text -eq $i }
                { $_ -in 'ip', 'domain' } { Test-WfxRxMatch $rx $row.Text }
                default { $row.Text.IndexOf($i, [StringComparison]::OrdinalIgnoreCase) -ge 0 }
            }
            if ($match) {
                $val = Protect-WfxText $row.Text
                if ($val.Length -gt 500) { $val = $val.Substring(0, 500) + ' …' }
                $findings.Add((New-WfxFinding -Id 'HUNT-IOC-MATCH' -Title "IOC '$i' ($kind) found in $($row.Where): $($row.Ctx)" `
                            -Severity 'High' -Confidence $(if ($kind -eq 'text') { 'Medium' } else { 'High' }) -Category 'Hunt' -Technique @() `
                            -Description "The indicator '$i' was located in $($row.Where) data on this host." `
                            -Recommendation "Correlate with the surrounding activity (process tree, connections, timing) and contain the host if confirmed malicious." `
                            -Entity "hunt:$i`:$($row.Where):$($row.Ctx)" -HostName $hn -Source 'hunt' `
                            -Evidence ([ordered]@{ Ioc = $i; Type = $kind; Where = $row.Where; Context = $row.Ctx; Value = $val })))
            }
        }
    }
    $merged = Merge-WfxFinding -Finding $findings.ToArray()
    Write-WfxSection 'Hunt'
    Write-WfxConsole ("Searched {0} data points for {1} IOC(s) on {2}." -f $rows.Count, $iocs.Count, $hn) -Kind Dim
    if (@($merged).Count -eq 0) { Write-WfxConsole 'No matches.' -Kind Ok }
    else {
        Write-WfxConsole ("{0} IOC hit(s):" -f @($merged).Count) -Kind Bad
        foreach ($f in $merged) { Write-WfxConsole "  $($f.Title)" -Kind Bad }
    }
    if (-not $NoCase) {
        $case = New-WfxCase -OutputPath $OutputPath -Name 'hunt' -HostName $hn -Mode 'hunt' -Parameters @{ Iocs = $iocs; InputPath = $InputPath; Hours = $Hours; FileScan = [bool]$FileScan }
        if ($InputPath) { try { Add-WfxCaseSource -Path (Resolve-WfxBundlePath -Path $InputPath) -Role 'source-bundle' } catch {} }
        Save-WfxJson -InputObject ([pscustomobject]@{ Schema = 'winforensicx.hunt/1'; Host = $hn; Iocs = $iocs; DataPoints = $rows.Count; Hits = @($merged) }) -Path (Join-Path $case.Path 'hunt.json') -Depth 8
        @($merged | ForEach-Object { [pscustomobject]@{ Ioc = $_.Evidence.Ioc; Type = $_.Evidence.Type; Where = $_.Evidence.Where; Context = $_.Evidence.Context; Value = $_.Evidence.Value; Host = $_.Host } }) |
            Export-Csv -Path (Join-Path $case.Path 'hunt.csv') -NoTypeInformation -Encoding UTF8
        $null = Complete-WfxCase
        Write-WfxConsole ("Results: {0}" -f $case.Path) -Kind Info
    }
    if ($PassThru) { return $merged }
}

function Get-WfxIocKind {
    <# Classifies an indicator: hash / ip / domain / text. #>
    param([string]$Value)
    if ($Value -match '^(?:[0-9a-fA-F]{32}|[0-9a-fA-F]{40}|[0-9a-fA-F]{64})$') { return 'hash' }
    $ip = $null
    if ($Value -match '^[0-9.]+$|:' -and [System.Net.IPAddress]::TryParse($Value, [ref]$ip)) { return 'ip' }
    if ($Value -match '^(?=.{4,253}$)(?:[A-Za-z0-9](?:[A-Za-z0-9\-]{0,61}[A-Za-z0-9])?\.)+[A-Za-z]{2,63}$' -and $Value -notmatch '\.(?:exe|dll|ps1|bat|cmd|vbs|js|hta|lnk|zip|txt|doc|docx|xls|xlsx|pdf|sys|msi|iso)$') { return 'domain' }
    return 'text'
}


# ===== Public/Invoke-WfxTriage.ps1 =====
function Get-WfxPortableSource {
    <# Returns ONLY the collection code (Private + Collectors layers) as one string, so it can be sent to a
       remote WinRM session. Works whether WinForensicX is loaded as a module or from the single-file build
       (where layers are delimited by "# ===== <Layer>/<File> =====" markers). The single-file entry point,
       menus, analyzers and report code are never sent. #>
    $wanted = '^(?:Private|Collectors)/'
    if ($script:WfxSingleFilePath -and (Test-Path -LiteralPath $script:WfxSingleFilePath)) {
        $text = Get-Content -LiteralPath $script:WfxSingleFilePath -Raw
        $parts = [regex]::Split($text, '(?m)^# ===== ')
        $sel = foreach ($p in $parts) {
            if ($p -match "$wanted\S+ =====") { $p.Substring($p.IndexOf("`n") + 1) }
        }
        return ($sel -join "`n`n")
    }
    if (-not $script:WfxModuleRoot) { throw 'Cannot locate WinForensicX source for remote collection.' }
    $files = foreach ($layer in 'Private', 'Collectors') {
        Get-ChildItem -LiteralPath (Join-Path $script:WfxModuleRoot $layer) -Filter *.ps1 | Sort-Object Name
    }
    ($files | ForEach-Object { Get-Content -LiteralPath $_.FullName -Raw }) -join "`n`n"
}

function Invoke-WfxTriage {
    <#
    .SYNOPSIS
        One-shot incident triage for a Windows host: collect → analyze → score → report, with a full
        chain-of-custody case folder. The main entry point.
    .DESCRIPTION
        Four modes, chosen by parameters:
          • Local   (default)        — collect and analyze this host.
          • Remote  (-ComputerName)  — collect over WinRM on one or more hosts, analyze locally.
          • Offline (-EvtxPath)      — analyze exported event logs ONLY. Nothing is collected from the machine
                                       running the tool, so the analyst's workstation never contaminates the case.
          • Re-analyze (-InputPath)  — re-run analysis over a previously saved case/bundle (no collection).
        Everything is read-only. Credential exposure is audited and REDACTED, never extracted.
    .PARAMETER OutputPath    Where the case folder is created (default: Desktop\WinForensicX). Prefer external media.
    .PARAMETER CaseName      Optional label folded into the case folder name.
    .PARAMETER Hours         Event look-back window in hours (default 72, max 8760).
    .PARAMETER FileScan      Also scan web roots / user drop folders for web shells, droppers, ransom notes.
    .PARAMETER ExposureScan  Also scan common config files (and the domain SYSVOL) for clear-text secrets (redacted).
    .PARAMETER ComputerName  One or more remote hosts to triage over WinRM.
    .PARAMETER Credential    Credential for the remote session.
    .PARAMETER EvtxPath      Folder or .evtx file to analyze offline.
    .PARAMETER InputPath     A previous case folder or bundle.json to re-analyze.
    .PARAMETER AllowlistPath JSON allowlist of known-good findings (default $env:WFX_ALLOWLIST).
    .PARAMETER Quiet         Suppress console output (results still written).
    .PARAMETER NoReport      Skip the HTML report (JSON/CSV still written).
    .PARAMETER PassThru      Return the result object(s).
    .EXAMPLE
        Invoke-WfxTriage -FileScan -OutputPath E:\cases
    .EXAMPLE
        Invoke-WfxTriage -ComputerName srv01,srv02 -Credential (Get-Credential)
    .EXAMPLE
        Invoke-WfxTriage -EvtxPath D:\evidence\logs -CaseName acme-ir
    .EXAMPLE
        Invoke-WfxTriage -InputPath 'C:\cases\WFX_host_20260101-000000Z' -AllowlistPath .\allow.json
    #>
    [CmdletBinding(DefaultParameterSetName = 'Local')]
    param(
        [string]$OutputPath = '',
        [string]$CaseName = '',
        [ValidateRange(1, 8760)][int]$Hours = 72,
        [Parameter(ParameterSetName = 'Local')][Parameter(ParameterSetName = 'Remote')][switch]$FileScan,
        [Parameter(ParameterSetName = 'Local')][Parameter(ParameterSetName = 'Remote')][switch]$ExposureScan,
        [Parameter(ParameterSetName = 'Remote', Mandatory)][ValidateNotNullOrEmpty()][string[]]$ComputerName,
        [Parameter(ParameterSetName = 'Remote')][System.Management.Automation.PSCredential]$Credential,
        [Parameter(ParameterSetName = 'Offline', Mandatory)][ValidateNotNullOrEmpty()][string]$EvtxPath,
        [Parameter(ParameterSetName = 'Reanalyze', Mandatory)][ValidateNotNullOrEmpty()][string]$InputPath,
        [string]$AllowlistPath = $env:WFX_ALLOWLIST,
        [switch]$Quiet,
        [switch]$NoReport,
        [switch]$PassThru
    )

    $script:WfxQuiet = [bool]$Quiet
    Write-WfxBanner
    $params = @{ Hours = $Hours; FileScan = [bool]$FileScan; ExposureScan = [bool]$ExposureScan; Mode = $PSCmdlet.ParameterSetName; Allowlist = [string]$AllowlistPath }

    # ── Re-analyze: no collection, just re-run analyzers over saved evidence ──
    if ($PSCmdlet.ParameterSetName -eq 'Reanalyze') {
        $src = Resolve-WfxBundlePath -Path $InputPath
        Write-WfxConsole "Re-analyzing saved evidence: $src" -Kind Info
        $bundle = Get-Content -LiteralPath $src -Raw -Encoding UTF8 | ConvertFrom-Json
        $hn = [string](Get-WfxValue $bundle 'HostName' 'unknown')
        $params.InputPath = $src
        $case = New-WfxCase -OutputPath $OutputPath -Name ($(if ($CaseName) { $CaseName } else { 'reanalysis' })) -HostName $hn -Mode 'reanalyze' -Parameters $params
        Add-WfxCaseSource -Path $src -Role 'source-bundle'
        $srcManifest = Join-Path (Split-Path -Parent (Split-Path -Parent $src)) 'manifest.json'
        if (-not (Test-Path -LiteralPath $srcManifest)) { $srcManifest = Join-Path (Split-Path -Parent $src) 'manifest.json' }
        if (Test-Path -LiteralPath $srcManifest) { Add-WfxCaseSource -Path $srcManifest -Role 'source-manifest' }
        Copy-Item -LiteralPath $src -Destination (Join-Path (Join-Path $case.Path 'raw') 'bundle.json')
        $result = Invoke-WfxAnalyze -Bundle $bundle -HostName $hn -AllowlistPath $AllowlistPath
        Save-WfxResult -Result $result -Case $case -NoReport:$NoReport
        $null = Complete-WfxCase
        Write-WfxResultSummary -Result $result -Case $case
        if ($PassThru) { return $result }
        return
    }

    # ── Remote: collect each host over WinRM, analyze locally ──
    if ($PSCmdlet.ParameterSetName -eq 'Remote') {
        $results = New-Object System.Collections.Generic.List[object]
        $src = Get-WfxPortableSource
        $srcHash = -join ([Security.Cryptography.SHA256]::Create().ComputeHash([Text.Encoding]::UTF8.GetBytes($src)) | ForEach-Object { $_.ToString('x2') })
        $sb = {
            param($Source, $Hours, $FileScan, $ExposureScan)
            $ErrorActionPreference = 'Stop'
            . ([scriptblock]::Create($Source))
            $b = Get-WfxCollectionBundle -Hours $Hours -FileScan:$FileScan -ExposureScan:$ExposureScan
            # Return JSON (not live objects) so deep nesting survives remoting serialization intact.
            $b | ConvertTo-Json -Depth 12 -Compress
        }
        foreach ($cn in $ComputerName) {
            Write-WfxConsole "Collecting from $cn over WinRM..." -Kind Info
            $rname = if ($CaseName) { $CaseName } else { 'remote' }
            $case = New-WfxCase -OutputPath $OutputPath -Name $rname -HostName $cn -Mode 'remote' -Parameters ($params + @{ ComputerName = $cn; CollectorSha256 = $srcHash })
            Write-WfxLog -Event 'remote-collector' -Data @{ sha256 = $srcHash; bytes = $src.Length }
            try {
                $icmArgs = @{ ComputerName = $cn; ScriptBlock = $sb; ArgumentList = @($src, $Hours, [bool]$FileScan, [bool]$ExposureScan); ErrorAction = 'Stop' }
                if ($Credential) { $icmArgs.Credential = $Credential }
                $json = Invoke-Command @icmArgs
                $rawPath = Join-Path (Join-Path $case.Path 'raw') 'bundle.json'
                [IO.File]::WriteAllText($rawPath, [string]$json, (New-Object Text.UTF8Encoding($false)))
                $bundle = [string]$json | ConvertFrom-Json
                $result = Invoke-WfxAnalyze -Bundle $bundle -HostName $cn -AllowlistPath $AllowlistPath
                Save-WfxResult -Result $result -Case $case -NoReport:$NoReport
                $null = Complete-WfxCase
                Write-WfxResultSummary -Result $result -Case $case
                $results.Add($result)
            } catch {
                Write-WfxConsole "  Failed on $cn`: $($_.Exception.Message)" -Kind Bad
                Add-WfxGap -Source "remote:$cn" -Reason $_.Exception.Message -Fix 'Confirm WinRM is enabled (Enable-PSRemoting) and the account has access.'
                Save-WfxJson -InputObject ([pscustomobject]@{ Host = $cn; Error = $_.Exception.Message; Gaps = @(Get-WfxGap) }) -Path (Join-Path $case.Path 'error.json')
                $null = Complete-WfxCase
            }
        }
        if ($PassThru) { return $results.ToArray() }
        return
    }

    # ── Offline: exported event logs only ──
    if ($PSCmdlet.ParameterSetName -eq 'Offline') {
        if (-not (Test-Path -LiteralPath $EvtxPath)) { throw "EvtxPath not found: $EvtxPath" }
        $params.EvtxPath = $EvtxPath
        $case = New-WfxCase -OutputPath $OutputPath -Name ($(if ($CaseName) { $CaseName } else { 'offline' })) -HostName 'offline' -Mode 'offline' -Parameters $params
        Write-WfxSection 'Reading exported event logs'
        $bundle = Get-WfxOfflineBundle -EvtxPath $EvtxPath
        foreach ($f in @($bundle.Meta.EvtxFiles)) { Add-WfxCaseSource -Path $f -Role 'evtx' }
        $case.Host = $bundle.HostName
        Save-WfxJson -InputObject $bundle -Path (Join-Path (Join-Path $case.Path 'raw') 'bundle.json') -Depth 12
        Write-WfxSection 'Analyzing'
        $result = Invoke-WfxAnalyze -Bundle $bundle -HostName $bundle.HostName -AllowlistPath $AllowlistPath
        Save-WfxResult -Result $result -Case $case -NoReport:$NoReport
        $null = Complete-WfxCase
        Write-WfxResultSummary -Result $result -Case $case
        if ($PassThru) { return $result }
        return
    }

    # ── Local ──
    if (-not (Test-WfxWindows)) { throw 'Live triage requires Windows. On other systems use -InputPath (re-analyze) or Invoke-WfxAnalyze.' }
    $hn = [Environment]::MachineName
    $case = New-WfxCase -OutputPath $OutputPath -Name $CaseName -HostName $hn -Mode 'local' -Parameters $params
    Write-WfxConsole "Case: $($case.Path)" -Kind Dim
    if (-not $case.Admin) { Write-WfxConsole 'Running without administrator rights — some data will be limited (recorded as gaps).' -Kind Warn }
    $missing = Test-WfxRulePackSet
    if ($missing.Count) { Write-WfxConsole ("Rule pack(s) missing or invalid: {0} — dependent detections will be skipped and recorded as gaps." -f ($missing -join ', ')) -Kind Bad }

    Write-WfxSection 'Collecting'
    $bundle = Get-WfxCollectionBundle -Hours $Hours -FileScan:$FileScan -ExposureScan:$ExposureScan
    Save-WfxJson -InputObject $bundle -Path (Join-Path (Join-Path $case.Path 'raw') 'bundle.json') -Depth 12

    Write-WfxSection 'Analyzing'
    $result = Invoke-WfxAnalyze -Bundle $bundle -HostName $hn -AllowlistPath $AllowlistPath

    Save-WfxResult -Result $result -Case $case -NoReport:$NoReport
    $null = Complete-WfxCase
    Write-WfxResultSummary -Result $result -Case $case
    if ($PassThru) { return $result }
}

function Write-WfxBanner {
    if ($script:WfxQuiet) { return }
    Write-WfxConsole ''
    Write-WfxConsole '  WinForensicX' -Kind Head -NoNewline
    Write-WfxConsole "  v$script:WfxVersion  —  read-only DFIR triage" -Kind Dim
    Write-WfxConsole ''
}

function Save-WfxResult {
    <# Writes findings.json, findings.csv, result.json and the HTML report into the case. #>
    param($Result, $Case, [switch]$NoReport)
    $root = $Case.Path
    $Result | Add-Member -NotePropertyName Case -NotePropertyValue ([pscustomobject]@{
            Id = $Case.Id; Name = $Case.Name; Mode = $Case.Mode; Started = $Case.StartedUtc; Operator = $Case.Operator
            OperatorHost = $Case.OperatorHost; Admin = $Case.Admin; PowerShell = "$($Case.PSVersion) $($Case.PSEdition)"
            Parameters = $Case.Parameters; Sources = @($Case.Sources); OutputOnSystemDrive = $Case.OutputOnSystemDrive
        }) -Force
    Save-WfxJson -InputObject $Result -Path (Join-Path $root 'result.json') -Depth 10
    Save-WfxJson -InputObject @($Result.Findings) -Path (Join-Path $root 'findings.json') -Depth 10
    # Flat CSV for triage in a spreadsheet / SIEM import.
    $rows = foreach ($f in @($Result.Findings)) {
        [pscustomobject]@{
            Severity = $f.Severity; Confidence = $f.Confidence; Score = $f.Score; Id = $f.Id
            Title = $f.Title; Category = $f.Category; Technique = (@($f.Technique) -join '; ')
            Entity = $f.Entity; Host = $f.Host; TimeUtc = $f.Time; Occurrences = (Get-WfxValue $f 'Occurrences' 1); Recommendation = $f.Recommendation
        }
    }
    try { @($rows) | Export-Csv -Path (Join-Path $root 'findings.csv') -NoTypeInformation -Encoding UTF8 }
    catch { Add-WfxGap -Source 'output:csv' -Reason $_.Exception.Message }
    if (-not $NoReport -and (Get-Command New-WfxReport -ErrorAction SilentlyContinue)) {
        try { New-WfxReport -Result $Result -Path (Join-Path $root 'report.html') | Out-Null }
        catch { Add-WfxGap -Source 'report' -Reason $_.Exception.Message }
    }
}

function Write-WfxResultSummary {
    param($Result, $Case)
    if ($script:WfxQuiet) { return }
    $r = $Result.Risk
    $kind = switch ($r.Level) { 'Critical' { 'Bad' } 'High' { 'Bad' } 'Elevated' { 'Warn' } default { 'Ok' } }
    Write-WfxSection 'Result'
    Write-WfxConsole ("Host {0}   Compromise risk {1}/100 ({2})   Posture gaps {3}/100 ({4})" -f $Result.HostName, $r.Score, $r.Level, $Result.Posture.Score, $Result.Posture.Level) -Kind $kind
    $s = $Result.Summary
    Write-WfxConsole ("Findings  Critical {0}  High {1}  Medium {2}  Low {3}  Info {4}" -f $s.Critical, $s.High, $s.Medium, $s.Low, $s.Info) -Kind Plain
    if (@($Result.Suppressed).Count) { Write-WfxConsole ("{0} finding(s) suppressed by the allowlist (listed in the report)." -f @($Result.Suppressed).Count) -Kind Dim }
    $top = @($Result.Findings | Where-Object { -not (Test-WfxPostureFinding $_) } | Select-Object -First 8)
    if ($top.Count) {
        Write-WfxConsole ''
        foreach ($f in $top) {
            $fk = switch ($f.Severity) { 'Critical' { 'Bad' } 'High' { 'Bad' } 'Medium' { 'Warn' } default { 'Dim' } }
            Write-WfxConsole ("  [{0,-8}] {1}" -f $f.Severity, $f.Title) -Kind $fk
        }
    }
    $gaps = @($Result.Gaps)
    if ($gaps.Count) { Write-WfxConsole ''; Write-WfxConsole ("{0} collection/analysis gap(s) recorded — see the report so 'nothing found' is read correctly." -f $gaps.Count) -Kind Warn }
    Write-WfxConsole ''
    Write-WfxConsole ("Outputs:  {0}" -f $Case.Path) -Kind Info
    $reportPath = Join-Path $Case.Path 'report.html'
    if (Test-Path -LiteralPath $reportPath) {
        Write-WfxConsole ("Report:   {0}" -f (ConvertTo-WfxFileUri $reportPath)) -Kind Info
    }
    $mp = Join-Path $Case.Path 'manifest.json'
    if (Test-Path -LiteralPath $mp) { Write-WfxConsole ("Manifest SHA-256 (record this out-of-band): {0}" -f (Get-FileHash -LiteralPath $mp -Algorithm SHA256).Hash.ToLowerInvariant()) -Kind Dim }
    Write-WfxConsole ''
    Write-WfxConsole 'Reminder: findings are leads, not verdicts — read them next to the collection gaps.' -Kind Dim
}


# ===== Public/Save-WfxEvidence.ps1 =====
function Save-WfxEvidence {
    <#
    .SYNOPSIS
        Collects a full read-only evidence bundle and writes it to a chain-of-custody case folder WITHOUT
        running analysis — for when the priority is to preserve state quickly and analyze later (possibly
        on another machine with Invoke-WfxTriage -InputPath). Every output is hashed in manifest.json.
    .PARAMETER OutputPath   Case folder location (default: Desktop\WinForensicX).
    .PARAMETER CaseName     Optional case label.
    .PARAMETER Hours        Event look-back window (default 72).
    .PARAMETER FileScan     Include the web-root / drop-folder file scan.
    .PARAMETER ExposureScan Include the config-file secret scan (redacted).
    .PARAMETER Quiet        Suppress console output.
    .OUTPUTS The case folder path.
    .EXAMPLE
        Save-WfxEvidence -FileScan -ExposureScan -CaseName acme-ir
    #>
    [CmdletBinding()]
    param(
        [string]$OutputPath = '',
        [string]$CaseName = '',
        [ValidateRange(1, 8760)][int]$Hours = 72,
        [switch]$FileScan,
        [switch]$ExposureScan,
        [switch]$Quiet
    )
    if (-not (Test-WfxWindows)) { Write-WfxConsole 'Evidence collection requires Windows.' -Kind Bad; return }
    $script:WfxQuiet = [bool]$Quiet
    Write-WfxBanner
    $hn = [Environment]::MachineName
    $case = New-WfxCase -OutputPath $OutputPath -Name ($(if ($CaseName) { $CaseName } else { 'evidence' })) -HostName $hn -Mode 'evidence' -Parameters @{ Hours = $Hours; FileScan = [bool]$FileScan; ExposureScan = [bool]$ExposureScan }
    if (-not $case.Admin) { Write-WfxConsole 'Running without administrator rights — some data will be limited (recorded as gaps).' -Kind Warn }
    Write-WfxSection 'Collecting evidence'
    $bundle = Get-WfxCollectionBundle -Hours $Hours -FileScan:$FileScan -ExposureScan:$ExposureScan
    $raw = Join-Path $case.Path 'raw'
    Save-WfxJson -InputObject $bundle -Path (Join-Path $raw 'bundle.json') -Depth 12
    # A human-readable host summary alongside the machine-readable bundle.
    $h = $bundle.Host
    $txt = @(
        "WinForensicX evidence — $hn",
        "Collection started (UTC): $($bundle.Started)",
        "Collection finished (UTC): $($bundle.Collected)",
        "Host time zone: $(Get-WfxValue $h 'TimeZone' '')  (all timestamps in the bundle are UTC)",
        "OS: $(Get-WfxValue $h 'Os' '')",
        "Operator: $(Get-WfxValue $h 'Operator' '')  Admin: $(Get-WfxValue $h 'Admin' '')",
        "Processes: $(@($bundle.Process).Count)  Connections: $(@($bundle.Network).Count)  Autostarts: $(@($bundle.Persistence).Count)  Events: $(@($bundle.Events).Count)",
        "Collection gaps: $(@($bundle.Gaps).Count)"
    ) -join "`r`n"
    [IO.File]::WriteAllText((Join-Path $raw 'host-summary.txt'), $txt, (New-Object Text.UTF8Encoding($false)))
    $mp = Complete-WfxCase
    Write-WfxSection 'Done'
    Write-WfxConsole ("Evidence bundle written and hashed: {0}" -f $case.Path) -Kind Info
    Write-WfxConsole ("Manifest SHA-256 (record this out-of-band): {0}" -f (Get-FileHash -LiteralPath $mp -Algorithm SHA256).Hash.ToLowerInvariant()) -Kind Dim
    Write-WfxConsole ("Re-analyze later with:  Invoke-WfxTriage -InputPath '{0}'" -f $case.Path) -Kind Dim
    return $case.Path
}


# ===== Public/Show-WfxHelp.ps1 =====
function ConvertTo-WfxFileUri {
    <# Turns a local path into a file:// URI that most modern terminals render as a clickable link. #>
    param([string]$Path)
    $full = $Path
    try { $full = (Resolve-Path -LiteralPath $Path -ErrorAction Stop).Path } catch {}
    $p = ($full -replace '\\', '/')
    if ($p -notmatch '^/') { $p = '/' + $p }   # Windows "C:/..." -> "/C:/..." so we get file:///C:/...
    return 'file://' + ($p -replace ' ', '%20')
}

function Show-WfxHelp {
    <#
    .SYNOPSIS
        Prints how to use WinForensicX — commands, examples, limitations and the defensive posture — to the
        terminal, and writes a matching HTML guide you can open in a browser.
    .PARAMETER Html      Open the HTML guide in the default browser after printing.
    .PARAMETER GuidePath Where to write the HTML guide (default: a temp file).
    .PARAMETER NoGuide   Don't write the HTML guide (terminal only).
    .EXAMPLE
        Show-WfxHelp
    .EXAMPLE
        Show-WfxHelp -Html
    #>
    [CmdletBinding()]
    param([switch]$Html, [string]$GuidePath = (Join-Path ([IO.Path]::GetTempPath()) 'WinForensicX-guide.html'), [switch]$NoGuide)
    $wasQuiet = $script:WfxQuiet; $script:WfxQuiet = $false
    $h = Get-WfxHelpModel

    Write-WfxConsole ''
    Write-WfxConsole '  WinForensicX' -Kind Head -NoNewline
    Write-WfxConsole "  v$($h.Version)  —  read-only DFIR triage" -Kind Dim
    Write-WfxConsole "  $($h.Tagline)" -Kind Plain
    Write-WfxConsole "  $($h.Requires)" -Kind Dim

    Write-WfxSection 'Commands'
    foreach ($c in $h.Commands) {
        Write-WfxConsole ("  {0}" -f $c.Name) -Kind Info -NoNewline
        Write-WfxConsole ("  $($c.Summary)") -Kind Dim
        foreach ($p in @($c.Params)) { Write-WfxConsole "      $p" -Kind Plain }
        if (@($c.Examples).Count) { Write-WfxConsole ("      e.g.  {0}" -f $c.Examples[0]) -Kind Dim }
    }

    Write-WfxSection 'What a run produces'
    foreach ($o in $h.Outputs) { Write-WfxConsole "  $o" -Kind Plain }

    Write-WfxSection 'Safety'
    foreach ($s in $h.Safety) { Write-WfxConsole "  + $s" -Kind Ok }

    Write-WfxSection 'Limitations'
    foreach ($l in $h.Limits) { Write-WfxConsole "  ! $l" -Kind Warn }

    if (-not $NoGuide -and (Get-Command New-WfxGuide -ErrorAction SilentlyContinue)) {
        try {
            # Prefer the field guide shipped with the release (docs\guide.html: scenarios, flags, every view);
            # fall back to generating the reference guide (single-file use, or a stripped copy).
            $shipped = @(
                $(if ($script:WfxModuleRoot) { Join-Path (Split-Path -Parent $script:WfxModuleRoot) 'docs\guide.html' })
                $(if ($script:WfxSingleFilePath) { Join-Path (Split-Path -Parent (Split-Path -Parent $script:WfxSingleFilePath)) 'docs\guide.html' })
            ) | Where-Object { $_ -and (Test-Path -LiteralPath $_) } | Select-Object -First 1
            $gp = if ($shipped) { (Resolve-Path -LiteralPath $shipped).Path } else { New-WfxGuide -Path $GuidePath }
            $uri = ConvertTo-WfxFileUri $gp
            Write-WfxSection 'Full guide'
            Write-WfxConsole '  Open the full illustrated guide in a browser (Ctrl/Cmd-click the link):' -Kind Plain
            Write-WfxConsole "  $uri" -Kind Info
            if ($Html) { try { Start-Process $gp -ErrorAction Stop } catch { Write-WfxConsole "  (could not auto-open; copy the link above)" -Kind Dim } }
        } catch { Write-WfxConsole "  (HTML guide unavailable: $($_.Exception.Message))" -Kind Dim }
    }
    Write-WfxConsole ''
    $script:WfxQuiet = $wasQuiet
}


# ===== Public/Show-WfxMenu.ps1 =====
# Interactive menu: the main way to use WinForensicX without memorising parameters.
# Structure: main menu → section submenus → actions. Every screen says what each option does, inputs are
# validated, B goes back, Q quits from anywhere. Everything it runs is read-only.

$script:WfxMenu = @{ OutputPath = ''; Hours = 72; Days = 0; Allowlist = ''; RulesPath = ''; LastCase = '' }

function Read-WfxMenuChoice {
    <# Reads one menu choice; repeats until it is one of $Valid (case-insensitive). Returns it upper-cased. #>
    param([string[]]$Valid, [string]$Prompt = 'Choose')
    while ($true) {
        $c = ([string](Read-Host "  $Prompt")).Trim().ToUpperInvariant()
        if ($Valid -contains $c) { return $c }
        if ($c -eq '') { continue }
        Write-WfxConsole "  '$c' is not an option here. Type one of: $($Valid -join ', ')" -Kind Warn
    }
}

function Read-WfxMenuText {
    param([string]$Prompt, [string]$Default = '')
    $hint = if ($Default) { " [$Default]" } else { '' }
    $v = ([string](Read-Host "  $Prompt$hint")).Trim()
    if (-not $v) { return $Default }
    return $v
}

function Read-WfxMenuPath {
    <# Asks for a path; strips quotes, expands ~ and %VARS%, checks it exists. Empty input = cancel ($null). #>
    param([string]$Prompt, [ValidateSet('File', 'Folder', 'Any')][string]$Kind = 'Any', [switch]$AllowMissing, [string]$Default = '')
    while ($true) {
        $v = Read-WfxMenuText -Prompt "$Prompt (Enter = cancel)" -Default $Default
        if (-not $v) { return $null }
        $v = [Environment]::ExpandEnvironmentVariables($v.Trim('"', "'", ' '))
        if ($v -like '~*') { $v = Join-Path $HOME $v.Substring(1).TrimStart('\', '/') }
        if ($AllowMissing) { return $v }
        $type = switch ($Kind) { 'File' { 'Leaf' } 'Folder' { 'Container' } default { 'Any' } }
        if (Test-Path -LiteralPath $v -PathType $type) { return (Resolve-Path -LiteralPath $v).Path }
        Write-WfxConsole "  Not found$(if ($Kind -ne 'Any') { " (expected a $($Kind.ToLower()))" }): $v" -Kind Warn
    }
}

function Wait-WfxMenu { Write-WfxConsole ''; [void](Read-Host '  Press Enter to continue') }

function Get-WfxCaseRoot { if ($script:WfxMenu.OutputPath) { $script:WfxMenu.OutputPath } else { Get-WfxDefaultOutputRoot } }

function Get-WfxRecentCase {
    param([int]$Max = 15)
    $root = Get-WfxCaseRoot
    if (-not (Test-Path -LiteralPath $root)) { return @() }
    @(Get-ChildItem -LiteralPath $root -Directory -ErrorAction SilentlyContinue | Where-Object { Test-Path -LiteralPath (Join-Path $_.FullName 'manifest.json') } | Sort-Object LastWriteTime -Descending | Select-Object -First $Max)
}

function Write-WfxMenuHeader {
    param([string]$Crumb = 'Main menu')
    try { Clear-Host } catch {}
    $admin = Test-WfxAdmin
    Write-WfxConsole ''
    Write-WfxConsole '  WinForensicX' -Kind Head -NoNewline
    Write-WfxConsole "  v$script:WfxVersion · read-only DFIR toolkit" -Kind Dim
    Write-WfxConsole ("  Host {0} · {1} · output {2}" -f [Environment]::MachineName, $(if ($admin) { 'elevated' } else { 'NOT elevated (some views limited)' }), (Get-WfxCaseRoot)) -Kind $(if ($admin) { 'Dim' } else { 'Warn' })
    if ($script:WfxMenu.LastCase) { Write-WfxConsole "  Last case: $($script:WfxMenu.LastCase)" -Kind Dim }
    Write-WfxConsole ''
    Write-WfxConsole "  ── $Crumb $('─' * [Math]::Max(3, 60 - $Crumb.Length))" -Kind Head
    Write-WfxConsole ''
}

function Write-WfxMenuItem {
    param([string]$Key, [string]$Label, [string]$Hint = '')
    Write-WfxConsole ("   {0,-3}" -f $Key) -Kind Info -NoNewline
    Write-WfxConsole ("{0,-44}" -f $Label) -Kind Plain -NoNewline
    Write-WfxConsole $Hint -Kind Dim
}

function Write-WfxMenuFooter { param([switch]$NoBack) Write-WfxConsole ''; if (-not $NoBack) { Write-WfxMenuItem 'B' 'Back' }; Write-WfxMenuItem 'Q' 'Quit'; Write-WfxConsole '' }

function Invoke-WfxMenuAction {
    <# Runs one action, catches errors so the menu never dies, and remembers the newest case. #>
    param([scriptblock]$Action, [switch]$NoPause)
    $before = @(Get-WfxRecentCase -Max 1) | Select-Object -First 1
    try { & $Action }
    catch { Write-WfxConsole ''; Write-WfxConsole "  Error: $($_.Exception.Message)" -Kind Bad; Write-WfxConsole '  (Nothing was changed on this computer.)' -Kind Dim }
    $after = @(Get-WfxRecentCase -Max 1) | Select-Object -First 1
    if ($after -and (-not $before -or $after.FullName -ne $before.FullName)) { $script:WfxMenu.LastCase = $after.FullName }
    if (-not $NoPause) { Wait-WfxMenu }
}

function Get-WfxTriageArgs {
    $a = @{ OutputPath = $script:WfxMenu.OutputPath; Hours = $script:WfxMenu.Hours }
    if ($script:WfxMenu.Allowlist) { $a.AllowlistPath = $script:WfxMenu.Allowlist }
    $a
}

function Open-WfxPath { param([string]$Path) if ((Test-WfxWindows) -and $Path) { try { Start-Process -FilePath $Path } catch { Write-WfxConsole "  Could not open: $Path" -Kind Warn } } else { Write-WfxConsole "  $Path" -Kind Info } }

# ─────────────────────────── sections ───────────────────────────
function Show-WfxMenuTriage {
    while ($true) {
        Write-WfxMenuHeader 'Investigate this computer'
        Write-WfxMenuItem '1' 'Quick triage' 'processes, network, autostarts, events, posture (~1-5 min)'
        Write-WfxMenuItem '2' 'Full triage' '+ web shells, dropped files, ransomware, config secrets (slower)'
        Write-WfxMenuItem '3' 'Collect evidence only' 'hashed snapshot to analyze later or elsewhere'
        Write-WfxConsole ''
        Write-WfxMenuItem '4' 'Remote computer(s) over WinRM' 'collect from other machines, analyze here'
        Write-WfxMenuItem '5' 'Offline event logs (.evtx)' 'analyze exported logs from another machine'
        Write-WfxMenuItem '6' 'Re-analyze a saved case' 're-run detections over old evidence'
        Write-WfxMenuFooter
        $c = Read-WfxMenuChoice -Valid '1', '2', '3', '4', '5', '6', 'B', 'Q'
        switch ($c) {
            'B' { return }
            'Q' { return 'Q' }
            '1' { $a = Get-WfxTriageArgs; Invoke-WfxMenuAction { Invoke-WfxTriage @a | Out-Null; Write-WfxMenuOpenReport } }
            '2' { $a = Get-WfxTriageArgs; Invoke-WfxMenuAction { Invoke-WfxTriage @a -FileScan -ExposureScan | Out-Null; Write-WfxMenuOpenReport } }
            '3' { Invoke-WfxMenuAction { Save-WfxEvidence -OutputPath $script:WfxMenu.OutputPath -Hours $script:WfxMenu.Hours -FileScan -ExposureScan | Out-Null } }
            '4' {
                $cn = Read-WfxMenuText 'Computer name(s), comma-separated (Enter = cancel)'
                if ($cn) {
                    $cred = $null
                    if ((Read-WfxMenuText 'Use different credentials? (y/N)') -match '^(?i)y') { $cred = Get-Credential }
                    $a = Get-WfxTriageArgs; $a.ComputerName = @($cn -split '\s*,\s*' | Where-Object { $_ }); if ($cred) { $a.Credential = $cred }
                    Invoke-WfxMenuAction { Invoke-WfxTriage @a | Out-Null }
                }
            }
            '5' { $p = Read-WfxMenuPath 'Folder or .evtx file'; if ($p) { $a = Get-WfxTriageArgs; Invoke-WfxMenuAction { Invoke-WfxTriage @a -EvtxPath $p | Out-Null; Write-WfxMenuOpenReport } } }
            '6' { $p = Select-WfxMenuCase; if ($p) { $a = Get-WfxTriageArgs; $a.Remove('Hours'); Invoke-WfxMenuAction { Invoke-WfxTriage @a -InputPath $p | Out-Null; Write-WfxMenuOpenReport } } }
        }
    }
}

function Write-WfxMenuOpenReport {
    $c = @(Get-WfxRecentCase -Max 1) | Select-Object -First 1
    if (-not $c) { return }
    $r = Join-Path $c.FullName 'report.html'
    if ((Test-Path -LiteralPath $r) -and (Test-WfxWindows)) {
        if ((Read-WfxMenuText 'Open the HTML report now? (Y/n)') -notmatch '^(?i)n') { Open-WfxPath $r }
    }
}

function Write-WfxMenuNote {
    <# Shows why a view is empty or partial (collection gaps), so absence of rows is never mistaken for absence of activity. #>
    param([object[]]$Note)
    $n = @($Note | Expand-WfxRecord | Sort-Object Source, Reason -Unique)
    if (-not $n.Count) { return }
    Write-WfxConsole ''
    Write-WfxConsole '  Notes (coverage and limits):' -Kind Warn
    foreach ($x in ($n | Select-Object -First 8)) {
        Write-WfxConsole ("   - {0}" -f $x.Reason) -Kind Warn
        if ($x.Fix) { Write-WfxConsole ("     {0}" -f $x.Fix) -Kind Dim }
    }
    if ($n.Count -gt 8) { Write-WfxConsole ("   … and {0} more." -f ($n.Count - 8)) -Kind Dim }
}

function Test-WfxGridView {
    <# Out-GridView needs Microsoft.PowerShell.GraphicalHost (Windows PowerShell with the ISE feature) or the
       Microsoft.PowerShell.GraphicalTools module (PowerShell 7). Windows Sandbox / Server Core / PS7 often have neither. #>
    if ($null -ne $script:WfxGridOk) { return $script:WfxGridOk }
    $ok = $false
    if ((Test-WfxWindows) -and (Get-Command Out-GridView -ErrorAction SilentlyContinue)) {
        if ($PSVersionTable.PSVersion.Major -le 5) { try { Add-Type -AssemblyName 'Microsoft.PowerShell.GraphicalHost' -ErrorAction Stop; $ok = $true } catch { $ok = $false } }
        else { $ok = $true }
    }
    $script:WfxGridOk = $ok
    $ok
}

function Write-WfxMenuTable {
    <# Prints rows as a table; rows flagged CRITICAL/HIGH are red, MEDIUM yellow, LOW cyan. Unflagged rows show "-"
       in the Flag column so wrapped continuation lines (which start with spaces) keep the colour of their row. #>
    param([object[]]$Rows)
    # Console only: short reason, no technique column (full text: L = list view, G = browser, E = CSV).
    $disp = foreach ($r in $Rows) {
        if (-not $r.PSObject.Properties['Flag']) { $r; continue }
        $c = $r.PSObject.Copy()
        if (-not $c.Flag) { $c.Flag = '-' }
        $whys = @(([string]$c.Why) -split ' \| ' | Where-Object { $_ })
        $c.Why = if ($whys.Count -gt 1) { (Get-WfxShortText $whys[0] 56) + " (+$($whys.Count - 1))" } elseif ($whys.Count) { Get-WfxShortText $whys[0] 64 } else { '' }
        $c | Select-Object -Property * -ExcludeProperty Technique, Rule
    }
    $text = $disp | Format-Table -AutoSize -Wrap | Out-String -Width 220
    $color = $null
    foreach ($line in ($text -split "\r?\n")) {
        if ($line -match '^(CRITICAL|HIGH)\b') { $color = 'Red' }
        elseif ($line -match '^MEDIUM\b') { $color = 'Yellow' }
        elseif ($line -match '^LOW\b') { $color = 'Cyan' }
        elseif ($line -match '^\S') { $color = $null }
        if ($color) { Write-Host $line -ForegroundColor $color } else { Write-Host $line }
    }
}

function Show-WfxMenuInsightTable {
    <# Shows a result set page-friendly, then offers export / grid / filter. #>
    param([object[]]$Rows, [string]$Title, [string]$Key, [object[]]$Note = @(), [object[]]$Pattern = @())
    $Rows = @($Rows | Expand-WfxRecord)
    $flaggable = [bool]($Rows.Count -and $Rows[0].PSObject.Properties['Flag'])
    $view = $Rows; $page = 40; $q = ''; $suspOnly = $false
    $apply = {
        $v = $Rows
        if ($suspOnly) { $v = @($v | Where-Object { $_.Flag -and $_.Flag -ne 'INFO' }) }
        if ($q) { $v = @($v | Where-Object { ($_.PSObject.Properties.Value -join ' ') -like "*$q*" }) }
        $v
    }
    while ($true) {
        Write-WfxMenuHeader "Explore › $Title"
        if ($flaggable) {
            $sum = Get-WfxFlagSummary $Rows
            if ($sum) { Write-WfxConsole ("  Suspicious: {0}   (S = show only these)" -f $sum) -Kind $(if ($sum -match 'CRITICAL|HIGH') { 'Bad' } else { 'Warn' }) }
            else { Write-WfxConsole '  No row matched a suspicious-activity rule. (Absence of a flag is not proof of absence of compromise.)' -Kind Dim }
        }
        foreach ($p in $Pattern) { Write-WfxConsole ("  PATTERN [{0}] {1} {2}" -f $p.Severity, $p.Text, $(if ($p.Technique) { "($($p.Technique))" })) -Kind Bad }
        if (-not $view.Count) { Write-WfxConsole $(if ($suspOnly) { '  No flagged rows.' } elseif ($Note.Count) { '  No records - see the notes below for why.' } else { '  No records in the selected time window.' }) -Kind Dim }
        else {
            Write-WfxMenuTable -Rows @($view | Select-Object -First $page)
            if ($view.Count -gt $page) { Write-WfxConsole ("  … showing {0} of {1} rows." -f $page, $view.Count) -Kind Dim }
            else { Write-WfxConsole ("  {0} row(s){1}." -f $view.Count, $(if ($view.Count -ne $Rows.Count) { " of $($Rows.Count)" } else { '' })) -Kind Dim }
        }
        Write-WfxMenuNote $Note
        Write-WfxConsole ''
        $opts = New-Object System.Collections.Generic.List[string]
        if ($view.Count -gt $page) { Write-WfxMenuItem 'M' 'Show more rows'; $opts.Add('M') }
        if ($flaggable) { Write-WfxMenuItem 'S' $(if ($suspOnly) { 'Show all rows' } else { 'Show suspicious rows only' }) $(Get-WfxFlagSummary $Rows); $opts.Add('S') }
        Write-WfxMenuItem 'F' 'Filter (text search)' $(if ($q) { "current: '$q'" } else { '' }); $opts.Add('F')
        Write-WfxMenuItem 'L' 'List view (all columns, one row at a time)'; $opts.Add('L')
        if ($view.Count) { Write-WfxMenuItem 'G' 'Open in browser (sort, filter, copy)' 'self-contained page, works everywhere'; $opts.Add('G') }
        if ($view.Count -and (Test-WfxGridView)) { Write-WfxMenuItem 'W' 'Open in Out-GridView window'; $opts.Add('W') }
        Write-WfxMenuItem 'E' 'Export to CSV'; $opts.Add('E')
        Write-WfxMenuItem 'R' 'Refresh'; $opts.Add('R')
        Write-WfxMenuFooter
        $opts.Add('B'); $opts.Add('Q')
        $c = Read-WfxMenuChoice -Valid $opts.ToArray()
        switch ($c) {
            'B' { return }
            'Q' { return 'Q' }
            'M' { $page += 80 }
            'R' { return 'R' }
            'S' { $suspOnly = -not $suspOnly; $view = @(& $apply) }
            'F' {
                $q = Read-WfxMenuText 'Text to find (Enter = clear filter)'
                $view = @(& $apply)
            }
            'L' { $view | Select-Object -First $page | Format-List | Out-String -Width 220 | Write-Host; Wait-WfxMenu }
            'G' {
                try {
                    $pn = @($Pattern | ForEach-Object { [pscustomobject]@{ Reason = "PATTERN [$($_.Severity)] $($_.Text) $(if ($_.Technique) { "($($_.Technique))" })"; Fix = '' } })
                    $f = Save-WfxViewHtml -Rows $view -Title $Title -Key $Key -Note (@($pn) + @($Note))
                    Write-WfxConsole "  Saved: $f" -Kind Ok
                    Open-WfxPath $f
                } catch { Write-WfxConsole "  Could not create the page: $($_.Exception.Message)" -Kind Bad }
                Wait-WfxMenu
            }
            'W' { try { $view | Out-GridView -Title "WinForensicX · $Title" -ErrorAction Stop } catch { Write-WfxConsole "  Out-GridView failed: $($_.Exception.Message) - use G (browser) instead." -Kind Warn; Wait-WfxMenu } }
            'E' {
                $root = Get-WfxCaseRoot
                if (-not (Test-Path -LiteralPath $root)) { New-Item -ItemType Directory -Path $root -Force | Out-Null }
                $f = Join-Path $root ("{0}_{1}_{2}.csv" -f [Environment]::MachineName, $Key, (Get-Date).ToUniversalTime().ToString('yyyyMMdd-HHmmss'))
                $view | Export-Csv -Path $f -NoTypeInformation -Encoding UTF8
                Write-WfxConsole "  Saved: $f" -Kind Ok; Wait-WfxMenu
            }
        }
    }
}

function Show-WfxMenuExplore {
    $groups = @($script:WfxInsightTopics.Values | ForEach-Object { $_.Group } | Select-Object -Unique)
    $gdesc = @{ 'Recent changes' = 'what attackers change: registry, files, installs, executions, connections, config'; System = 'OS, updates, software, users, groups, sessions, shares, USB, drives'; Processes = 'running programs, process tree, unsigned programs'
        Network = 'listening ports, connections, DNS, adapters, routes, ARP, hosts, proxy, Wi-Fi, firewall, SMB'; Persistence = 'autostarts, services, drivers, scheduled tasks, WMI'
        Events = 'logons, failed logons, RDP, account changes, new services, log clears, reboots, PowerShell, Defender'; Files = 'downloads, new programs, Prefetch, recent files, PS history, Run box'
        Security = 'security posture checklist with fixes' }
    while ($true) {
        Write-WfxMenuHeader 'Explore this computer (live, read-only views)'
        $i = 0; $keys = @()
        foreach ($g in $groups) { $i++; $keys += [string]$i; Write-WfxMenuItem ([string]$i) $g $gdesc[$g] }
        Write-WfxConsole ''
        Write-WfxMenuItem 'A' 'Export EVERYTHING to an inventory report' 'HTML + CSV per view, hashed (1-5 min)'
        Write-WfxMenuFooter
        $c = Read-WfxMenuChoice -Valid ($keys + 'A', 'B', 'Q')
        if ($c -eq 'B') { return }
        if ($c -eq 'Q') { return 'Q' }
        if ($c -eq 'A') { Invoke-WfxMenuAction { Save-WfxInsight -OutputPath $script:WfxMenu.OutputPath | Out-Null }; continue }
        $grp = $groups[[int]$c - 1]
        $r = Show-WfxMenuTopicList -Group $grp
        if ($r -eq 'Q') { return 'Q' }
    }
}

function Show-WfxMenuTopicList {
    param([string]$Group)
    $topics = @($script:WfxInsightTopics.GetEnumerator() | Where-Object { $_.Value.Group -eq $Group })
    $admin = Test-WfxAdmin
    while ($true) {
        Write-WfxMenuHeader "Explore › $Group"
        $i = 0; $keys = @()
        foreach ($t in $topics) {
            $i++; $keys += [string]$i
            $tag = if ($t.Value.Admin -and -not $admin) { ' [needs admin]' } else { '' }
            Write-WfxMenuItem ([string]$i) ($t.Value.Title + $tag) ''
            Write-WfxConsole ("        {0}" -f $t.Value.Desc) -Kind Dim
        }
        Write-WfxMenuFooter
        $c = Read-WfxMenuChoice -Valid ($keys + 'B', 'Q')
        if ($c -eq 'B') { return }
        if ($c -eq 'Q') { return 'Q' }
        $t = $topics[[int]$c - 1]
        do {
            Write-WfxConsole ''
            Write-WfxConsole "  Collecting: $($t.Value.Title) ..." -Kind Info
            $sw = [Diagnostics.Stopwatch]::StartNew()
            $rows = @(); $err = $null
            Clear-WfxGap
            try { $rows = @(Get-WfxInsight -Topic $t.Key -Days $(if ($script:WfxMenu.Days) { $script:WfxMenu.Days } else { [int]$(if ($t.Value.Days) { $t.Value.Days } else { 7 }) }) -WarningAction SilentlyContinue) } catch { $err = $_.Exception.Message }
            $notes = @(Get-WfxGap | Expand-WfxRecord)
            if ($t.Value.Admin -and -not $admin) { $notes = @([pscustomobject]@{ Source = 'privileges'; Reason = 'This view needs administrator rights; results are empty or partial.'; Fix = 'Reopen PowerShell with "Run as administrator".' }) + $notes }
            if ($err) { Write-WfxConsole "  Could not read this view: $err" -Kind Bad; Write-WfxMenuNote $notes; Wait-WfxMenu; $r = 'B' }
            else { Write-WfxConsole ("  done in {0:N1}s" -f $sw.Elapsed.TotalSeconds) -Kind Dim; $r = Show-WfxMenuInsightTable -Rows $rows -Title $t.Value.Title -Key $t.Key -Note $notes -Pattern @(Get-WfxViewPattern) }
        } while ($r -eq 'R')
        if ($r -eq 'Q') { return 'Q' }
    }
}

function Show-WfxMenuHunt {
    while ($true) {
        Write-WfxMenuHeader 'Hunt & analyze'
        Write-WfxMenuItem '1' 'Hunt IOCs on this computer' 'hashes, IPs, domains, names, strings'
        Write-WfxMenuItem '2' 'Hunt IOCs in a saved case' 'no live collection'
        Write-WfxMenuItem '3' 'What is this file? (file triage)' 'hashes, real type, signer, download URL, PE, strings, IOCs'
        Write-WfxMenuItem '4' 'Triage every file in a folder' 'quick table: type mismatch, entropy, signature'
        Write-WfxMenuItem '5' 'Decode a command / Base64 payload' '-EncodedCommand, gzip, nested layers (never executed)'
        Write-WfxConsole ''
        Write-WfxMenuItem '6' 'Take a file-integrity baseline' 'hash folders now, to detect changes later'
        Write-WfxMenuItem '7' 'Compare with a baseline' 'added / deleted / content-changed / timestamp-only files'
        Write-WfxMenuFooter
        $c = Read-WfxMenuChoice -Valid '1', '2', '3', '4', '5', '6', '7', 'B', 'Q'
        switch ($c) {
            'B' { return }
            'Q' { return 'Q' }
            { $_ -in '1', '2' } {
                Write-WfxConsole '  Enter IOCs separated by commas (defanged like evil[.]com is fine), or the path of a text file with one per line.' -Kind Dim
                $i = Read-WfxMenuText 'IOCs or IOC file (Enter = cancel)'
                if (-not $i) { break }
                $hp = @{ OutputPath = $script:WfxMenu.OutputPath }
                $iv = $i.Trim('"')
                if (Test-Path -LiteralPath $iv -PathType Leaf) { $hp.IocFile = $iv } else { $hp.Ioc = @($i -split '\s*,\s*' | Where-Object { $_ }) }
                if ($c -eq '2') { $p = Select-WfxMenuCase; if (-not $p) { break }; $hp.InputPath = $p }
                else { $hp.Hours = $script:WfxMenu.Hours; if ((Read-WfxMenuText 'Also scan files and hash running programs? Slower. (y/N)') -match '^(?i)y') { $hp.FileScan = $true; $hp.HashProcesses = $true } }
                Invoke-WfxMenuAction { Invoke-WfxHunt @hp | Out-Null }
            }
            '3' {
                $p = Read-WfxMenuPath 'File to examine' -Kind File
                if ($p) { Invoke-WfxMenuAction {
                        $t = Get-WfxFileTriage -Path $p -Strings
                        $t | Format-List Path, Size, FileType, Extension, ExtensionMismatch, MD5, SHA1, SHA256, Entropy, EntropyHint, CreatedUtc, ModifiedUtc, Zone, HostUrl, ReferrerUrl, AlternateStreams | Out-String -Width 200 | Write-Host
                        if ($t.Signature) { Write-WfxConsole '  Signature' -Kind Head; $t.Signature | Format-List | Out-String | Write-Host }
                        if ($t.PE) { Write-WfxConsole '  PE header' -Kind Head; $t.PE | Format-List | Out-String | Write-Host }
                        if ($t.Iocs) {
                            Write-WfxConsole '  Indicators found in strings' -Kind Head
                            foreach ($n in 'Urls', 'IPv4', 'Domains', 'Emails', 'RegistryPaths') { $v = @($t.Iocs.$n); if ($v.Count) { Write-WfxConsole ("   {0,-14} {1}" -f $n, (($v | Select-Object -First 15) -join '  ')) } }
                        }
                        if ((Read-WfxMenuText "Show the first 100 of $($t.StringCount) strings? (y/N)") -match '^(?i)y') { $t.Strings | Select-Object -First 100 | ForEach-Object { Write-WfxConsole "   $_" -Kind Dim } }
                    } }
            }
            '4' {
                $p = Read-WfxMenuPath 'Folder' -Kind Folder
                if ($p) { Invoke-WfxMenuAction -NoPause {
                        $rows = @(Get-ChildItem -LiteralPath $p -File -ErrorAction SilentlyContinue | Select-Object -First 500 | Get-WfxFileTriage | Select-Object @{ n = 'File'; e = { Split-Path -Leaf $_.Path } }, FileType, ExtensionMismatch, Entropy, Zone, @{ n = 'Signed'; e = { if ($_.Signature) { $_.Signature.Status } else { '' } } }, SHA256)
                        $null = Show-WfxMenuInsightTable -Rows $rows -Title "Files in $p" -Key 'filetriage'
                    } }
            }
            '6' {
                Write-WfxConsole '  Folders to baseline, comma-separated (e.g. C:\inetpub\wwwroot, C:\Windows\System32\drivers\etc).' -Kind Dim
                $t = Read-WfxMenuText 'Folders (Enter = cancel)'
                if ($t) { $paths = @($t -split '\s*,\s*' | ForEach-Object { $_.Trim('"') } | Where-Object { $_ }); Invoke-WfxMenuAction { New-WfxFileBaseline -Path $paths | Out-Null } }
            }
            '7' {
                $p = Read-WfxMenuPath 'Baseline .json file' -Kind File
                if ($p) { Invoke-WfxMenuAction -NoPause { $d = @(Compare-WfxFileBaseline -Baseline $p); $null = Show-WfxMenuInsightTable -Rows $d -Title 'File baseline comparison' -Key 'baseline' } }
            }
            '5' {
                $p = Read-WfxMenuText 'Paste the command line or Base64 (Enter = cancel)'
                if ($p) { Invoke-WfxMenuAction {
                        $d = ConvertFrom-WfxEncodedCommand -InputObject $p
                        if ($d) {
                            foreach ($l in $d.Layers) { Write-WfxConsole "  Layer $($l.Layer) ($($l.Source))" -Kind Head; Write-WfxConsole "  $($l.Text)" }
                            if ($d.Rules) { Write-WfxConsole ''; Write-WfxConsole ('  Matched detections: ' + ($d.Rules -join '; ')) -Kind Warn }
                            Write-WfxConsole ''; Write-WfxConsole '  Decoded only — nothing was executed.' -Kind Dim
                        }
                    } }
            }
        }
    }
}

function Select-WfxMenuCase {
    <# Lets the user pick a recent case by number or type a path. Returns the case path or $null. #>
    $cases = Get-WfxRecentCase -Max 12
    if ($cases.Count) {
        Write-WfxConsole '  Recent cases:' -Kind Head
        for ($i = 0; $i -lt $cases.Count; $i++) { Write-WfxConsole ("   {0,-3} {1}   ({2:yyyy-MM-dd HH:mm})" -f ($i + 1), $cases[$i].Name, $cases[$i].LastWriteTime) }
        Write-WfxConsole '   P   type a path instead' -Kind Dim
        $c = Read-WfxMenuChoice -Valid (@(1..$cases.Count | ForEach-Object { [string]$_ }) + 'P', 'B') -Prompt 'Case number, P or B'
        if ($c -eq 'B') { return $null }
        if ($c -ne 'P') { return $cases[[int]$c - 1].FullName }
    }
    Read-WfxMenuPath 'Case folder or bundle.json'
}

function Show-WfxMenuCases {
    while ($true) {
        Write-WfxMenuHeader 'Cases & evidence'
        Write-WfxMenuItem '1' 'Open a case report' 'pick from recent cases'
        Write-WfxMenuItem '2' 'Open the case folder'
        Write-WfxMenuItem '3' 'Verify a case (chain of custody)' 're-hash every file against its manifest'
        Write-WfxMenuItem '4' 'Export a case timeline (CSV)' 'one UTC-sorted list of everything with a time'
        Write-WfxMenuItem '5' 'Compare two cases' 'what is new or gone since a baseline'
        Write-WfxMenuFooter
        $c = Read-WfxMenuChoice -Valid '1', '2', '3', '4', '5', 'B', 'Q'
        switch ($c) {
            'B' { return }
            'Q' { return 'Q' }
            '1' { $p = Select-WfxMenuCase; if ($p) { $r = Join-Path $p 'report.html'; if (Test-Path -LiteralPath $r) { Open-WfxPath $r } else { Write-WfxConsole '  This case has no HTML report (evidence-only or hunt case).' -Kind Warn; Wait-WfxMenu } } }
            '2' { $p = Select-WfxMenuCase; if ($p) { Open-WfxPath $(if (Test-Path -LiteralPath $p -PathType Leaf) { Split-Path -Parent $p } else { $p }) } }
            '3' { $p = Select-WfxMenuCase; if ($p) { Invoke-WfxMenuAction { Test-WfxCase -Path $p | Out-Null } } }
            '4' { $p = Select-WfxMenuCase; if ($p) { Invoke-WfxMenuAction { Export-WfxTimeline -InputPath $p } } }
            '5' {
                Write-WfxConsole '  First the BASELINE (older / known-good) case:' -Kind Dim; $a = Select-WfxMenuCase
                if (-not $a) { break }
                Write-WfxConsole '  Now the CURRENT case:' -Kind Dim; $b = Select-WfxMenuCase
                if ($b) { Invoke-WfxMenuAction -NoPause { $d = @(Compare-WfxCase -Baseline $a -Current $b); $null = Show-WfxMenuInsightTable -Rows $d -Title 'Case comparison' -Key 'compare' } }
            }
        }
    }
}

function Show-WfxMenuSettings {
    while ($true) {
        Write-WfxMenuHeader 'Settings (this session)'
        Write-WfxMenuItem '1' 'Output folder' (Get-WfxCaseRoot)
        Write-WfxMenuItem '2' 'Event look-back for triage (hours)' ([string]$script:WfxMenu.Hours)
        Write-WfxMenuItem '3' 'Look-back for live views (days)' $(if ($script:WfxMenu.Days) { [string]$script:WfxMenu.Days } else { 'per view default' })
        Write-WfxMenuItem '4' 'Allowlist file' $(if ($script:WfxMenu.Allowlist) { $script:WfxMenu.Allowlist } else { '(none)' })
        Write-WfxMenuItem '5' 'Custom rules folder' $(if ($script:WfxMenu.RulesPath) { $script:WfxMenu.RulesPath } else { '(built-in only)' })
        Write-WfxMenuFooter
        $c = Read-WfxMenuChoice -Valid '1', '2', '3', '4', '5', 'B', 'Q'
        switch ($c) {
            'B' { return }
            'Q' { return 'Q' }
            '1' {
                $p = Read-WfxMenuPath 'Folder for cases (created if missing; external drive recommended)' -AllowMissing
                if ($p) { try { New-Item -ItemType Directory -Path $p -Force -ErrorAction Stop | Out-Null; $script:WfxMenu.OutputPath = (Resolve-Path -LiteralPath $p).Path } catch { Write-WfxConsole "  Cannot use that folder: $($_.Exception.Message)" -Kind Bad; Wait-WfxMenu } }
            }
            '2' { $v = 0; if ([int]::TryParse((Read-WfxMenuText 'Hours (1-8760)' ([string]$script:WfxMenu.Hours)), [ref]$v) -and $v -ge 1 -and $v -le 8760) { $script:WfxMenu.Hours = $v } else { Write-WfxConsole '  Enter a number from 1 to 8760.' -Kind Warn; Wait-WfxMenu } }
            '3' { $v = 0; $t = Read-WfxMenuText 'Days (1-3650, 0 = per view default)' ([string]$script:WfxMenu.Days); if ([int]::TryParse($t, [ref]$v) -and $v -ge 0 -and $v -le 3650) { $script:WfxMenu.Days = $v } else { Write-WfxConsole '  Enter a number from 0 to 3650.' -Kind Warn; Wait-WfxMenu } }
            '4' { $p = Read-WfxMenuPath 'Allowlist JSON (see examples\allowlist.example.json)' -Kind File; $script:WfxMenu.Allowlist = [string]$p }
            '5' { $p = Read-WfxMenuPath 'Folder with <pack>.<name>.json rule files' -Kind Folder; $script:WfxMenu.RulesPath = [string]$p; Set-WfxRulePath ([string]$p) }
        }
    }
}

function Show-WfxMenu {
    <#
    .SYNOPSIS
        Interactive menu for WinForensicX — the easiest way to use the toolkit. Sections:
        Investigate (triage), Explore (live views of the system), Hunt & analyze, Cases & evidence,
        Live monitor, Settings and Help. Everything it runs is read-only.
    .EXAMPLE
        Show-WfxMenu
    .EXAMPLE
        Show-WfxMenu -OutputPath E:\cases
    #>
    [CmdletBinding()]
    param([string]$OutputPath = '')
    $script:WfxQuiet = $false
    if ($OutputPath) { $script:WfxMenu.OutputPath = $OutputPath }
    $missing = @(Test-WfxRulePackSet)
    while ($true) {
        Write-WfxMenuHeader 'Main menu'
        if ($missing.Count) { Write-WfxConsole "  ! Rule pack(s) missing: $($missing -join ', ') — restore them from the release (antivirus may have quarantined them)." -Kind Bad; Write-WfxConsole '' }
        Write-WfxMenuItem '1' 'Investigate this computer' 'triage: find signs of compromise and get a report'
        Write-WfxMenuItem '2' 'Explore this computer' '53 live views: what changed recently, users, software, network, USB...'
        Write-WfxMenuItem '3' 'Hunt & analyze' 'IOC hunting, file triage, decode payloads'
        Write-WfxMenuItem '4' 'Cases & evidence' 'open reports, verify, timeline, compare'
        Write-WfxMenuItem '5' 'Live monitor' 'watch new processes / connections as they happen'
        Write-WfxMenuItem '6' 'Settings' 'output folder, look-back, allowlist, custom rules'
        Write-WfxMenuItem 'H' 'Help & guide' 'what everything does, in a browser page'
        Write-WfxMenuFooter -NoBack
        $c = Read-WfxMenuChoice -Valid '1', '2', '3', '4', '5', '6', 'H', 'Q'
        $r = switch ($c) {
            '1' { Show-WfxMenuTriage }
            '2' { Show-WfxMenuExplore }
            '3' { Show-WfxMenuHunt }
            '4' { Show-WfxMenuCases }
            '5' {
                Write-WfxMenuHeader 'Live monitor'
                Write-WfxConsole '  Watches for NEW processes and connections and alerts on suspicious ones. Press Ctrl+C to stop.' -Kind Dim
                $d = 0; [void][int]::TryParse((Read-WfxMenuText 'Run for how many seconds? (Enter = until Ctrl+C)' '0'), [ref]$d)
                Invoke-WfxMenuAction { Start-WfxMonitor -Duration $d -OutputPath $script:WfxMenu.OutputPath }
            }
            '6' { Show-WfxMenuSettings }
            'H' { Invoke-WfxMenuAction -NoPause { Show-WfxHelp -Html } }
            'Q' { 'Q' }
        }
        if (@($r) -contains 'Q') { Write-WfxConsole ''; Write-WfxConsole '  Bye. Cases are in: ' -Kind Dim -NoNewline; Write-WfxConsole (Get-WfxCaseRoot) -Kind Info; return }
    }
}


# ===== Public/Start-WfxMonitor.ps1 =====
function Start-WfxMonitor {
    <#
    .SYNOPSIS
        Live monitoring: takes a baseline of processes and network connections, then watches for NEW
        ones and runs the process / network / beacon analyzers over just the changes, alerting as they
        happen. Read-only. Stop with Ctrl+C or a time limit.
    .PARAMETER Interval     Seconds between polls (default 5).
    .PARAMETER Duration     Total seconds to run; 0 = until Ctrl+C (default 0).
    .PARAMETER MinSeverity  Only alert at or above this severity (default Medium).
    .PARAMETER OutputPath   Case folder location (an alerts.jsonl is appended there).
    .PARAMETER CaseName     Optional case label.
    .PARAMETER Quiet        Suppress console output (alerts still written to the case).
    .EXAMPLE
        Start-WfxMonitor -Interval 5 -Duration 300
    #>
    [CmdletBinding()]
    param(
        [ValidateRange(2, 3600)][int]$Interval = 5,
        [ValidateRange(0, 2592000)][int]$Duration = 0,
        [ValidateSet('Info', 'Low', 'Medium', 'High', 'Critical')][string]$MinSeverity = 'Medium',
        [string]$OutputPath = '',
        [string]$CaseName = '',
        [switch]$Quiet
    )
    if (-not (Test-WfxWindows)) { Write-WfxConsole 'Live monitor requires Windows.' -Kind Bad; return }
    $script:WfxQuiet = [bool]$Quiet
    Write-WfxBanner
    $rank = @{ Info = 4; Low = 3; Medium = 2; High = 1; Critical = 0 }
    $minRank = $rank[$MinSeverity]
    $hn = [Environment]::MachineName
    $case = New-WfxCase -OutputPath $OutputPath -Name ($(if ($CaseName) { $CaseName } else { 'monitor' })) -HostName $hn -Mode 'monitor' -Parameters @{ Interval = $Interval; Duration = $Duration; MinSeverity = $MinSeverity }
    $alertPath = Join-Path $case.Path 'alerts.jsonl'

    Write-WfxConsole "Monitoring $hn — baseline..." -Kind Info
    $seenPid = @{}
    $seenConn = @{}
    $beacon = @{}                      # remote -> [List[datetime]] of NEW-connection times (not poll times)
    $alerted = @{}                     # Id|Entity already alerted (no repeats)
    foreach ($p in @(Get-WfxProcessData)) { $seenPid["$($p.Pid):$($p.Name)"] = $true }
    foreach ($c in @(Get-WfxNetworkData)) { $seenConn[(ConnKey $c)] = $true }
    Write-WfxConsole ("Baseline: {0} processes, {1} connections. Polling every {2}s. Ctrl+C to stop." -f $seenPid.Count, $seenConn.Count, $Interval) -Kind Dim
    Write-WfxConsole ''

    $deadline = if ($Duration -gt 0) { (Get-Date).AddSeconds($Duration) } else { [datetime]::MaxValue }
    $alertCount = 0; $iter = 0
    try {
        while ((Get-Date) -lt $deadline) {
            Start-Sleep -Seconds $Interval
            $iter++
            $newProcs = @(); $newConns = @()
            # Only processes not seen before are enriched (signature/owner lookups are the expensive part).
            foreach ($p in @(Get-WfxProcessData -Skip $seenPid)) {
                $k = "$($p.Pid):$($p.Name)"
                if (-not $seenPid.ContainsKey($k)) { $seenPid[$k] = $true; $newProcs += $p }
            }
            foreach ($c in @(Get-WfxNetworkData)) {
                $k = ConnKey $c
                if ($seenConn.ContainsKey($k)) { continue }
                $seenConn[$k] = $true; $newConns += $c
                # Beaconing = repeated NEW connections (new source port) to the same destination. A single
                # long-lived connection observed on every poll is not a beacon.
                if ($c.State -match 'Establish' -and $c.RemoteAddress -and -not (Test-WfxPrivateIp $c.RemoteAddress)) {
                    $rk = "$($c.RemoteAddress):$($c.RemotePort)"
                    if (-not $beacon.ContainsKey($rk)) { $beacon[$rk] = New-Object System.Collections.Generic.List[datetime] }
                    $t = ConvertTo-WfxDateTime (Get-WfxValue $c 'CreatedUtc' '')
                    $beacon[$rk].Add($(if ($t) { $t } else { (Get-Date).ToUniversalTime() }))
                    if ($beacon[$rk].Count -gt 200) { $beacon[$rk].RemoveAt(0) }
                }
            }

            $hits = New-Object System.Collections.Generic.List[object]
            # NB: analyzers return their findings as ONE array object; iterate the parenthesized result directly
            # (wrapping it in @() would yield a single nested array and garble alerts).
            if ($newProcs.Count) { foreach ($f in (Invoke-WfxProcessAnalyzer -Process $newProcs -HostName $hn)) { $hits.Add($f) } }
            if ($newConns.Count) { foreach ($f in (Invoke-WfxNetworkAnalyzer -Connection $newConns -HostName $hn)) { $hits.Add($f) } }
            # Periodically re-evaluate beaconing (needs several samples).
            if ($iter % 6 -eq 0) {
                $bIn = foreach ($rk in $beacon.Keys) { if ($beacon[$rk].Count -ge 6) { [pscustomobject]@{ Remote = $rk; Times = @($beacon[$rk]) } } }
                foreach ($f in (Invoke-WfxBeaconAnalyzer -Beacon @($bIn) -HostName $hn)) { $hits.Add($f) }
            }

            foreach ($f in @($hits | Where-Object { $_ -and $rank[[string]$_.Severity] -le $minRank })) {
                $ak = "$($f.Id)|$($f.Entity)"
                if ($alerted.ContainsKey($ak)) { continue }
                $alerted[$ak] = $true
                $alertCount++
                $fk = switch ($f.Severity) { 'Critical' { 'Bad' } 'High' { 'Bad' } 'Medium' { 'Warn' } default { 'Dim' } }
                Write-WfxConsole ("[{0:HH:mm:ss}] [{1,-8}] {2}" -f (Get-Date), $f.Severity, $f.Title) -Kind $fk
                try { Add-Content -LiteralPath $alertPath -Value (($f | ConvertTo-Json -Compress -Depth 6)) -Encoding UTF8 } catch { Write-Verbose "alert write failed: $_" }
            }
        }
    } finally {
        $null = Complete-WfxCase
        Write-WfxConsole ''
        Write-WfxConsole ("Monitor stopped. {0} alert(s) at/above {1}. Case: {2}" -f $alertCount, $MinSeverity, $case.Path) -Kind Info
    }
}

function ConnKey {
    param($C)
    "$($C.Protocol)|$($C.LocalAddress):$($C.LocalPort)|$($C.RemoteAddress):$($C.RemotePort)|$($C.State)"
}


# ===== Public/Test-WfxCase.ps1 =====
function Test-WfxCase {
    <#
    .SYNOPSIS
        Verifies a case folder against its manifest.json: re-hashes every listed file and reports files that
        changed, are missing, or were added after the case was closed. Prints the manifest's own SHA-256 so it
        can be compared with the value recorded at collection time.
    .PARAMETER Path            Case folder (or any file inside it).
    .PARAMETER ExpectedManifestSha256  Optional: the manifest hash you recorded out-of-band.
    .EXAMPLE
        Test-WfxCase -Path E:\cases\WFX_PC01_20261103-101500Z
    #>
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$Path, [string]$ExpectedManifestSha256 = '')
    $root = if (Test-Path -LiteralPath $Path -PathType Leaf) { Split-Path -Parent $Path } else { $Path }
    if ((Split-Path -Leaf $root) -eq 'raw') { $root = Split-Path -Parent $root }
    $mp = Join-Path $root 'manifest.json'
    if (-not (Test-Path -LiteralPath $mp)) { throw "No manifest.json in '$root' — not a completed WinForensicX case." }
    $root = (Resolve-Path -LiteralPath $root).Path
    $m = Get-Content -LiteralPath $mp -Raw -Encoding UTF8 | ConvertFrom-Json
    $mHash = (Get-FileHash -LiteralPath $mp -Algorithm SHA256).Hash.ToLowerInvariant()
    $rows = New-Object System.Collections.Generic.List[object]
    $listed = @{}
    foreach ($f in @($m.files)) {
        $full = Join-Path $root ([string]$f.path -replace '/', [IO.Path]::DirectorySeparatorChar)
        $listed[$full.ToLowerInvariant()] = $true
        if (-not (Test-Path -LiteralPath $full)) { $rows.Add([pscustomobject]@{ File = $f.path; Status = 'MISSING' }); continue }
        $h = (Get-FileHash -LiteralPath $full -Algorithm SHA256).Hash.ToLowerInvariant()
        $rows.Add([pscustomobject]@{ File = $f.path; Status = $(if ($h -eq [string]$f.sha256) { 'OK' } else { 'CHANGED' }) })
    }
    Get-ChildItem -LiteralPath $root -Recurse -File | Where-Object { $_.Name -ne 'manifest.json' -and -not $listed.ContainsKey($_.FullName.ToLowerInvariant()) } |
        ForEach-Object { $rows.Add([pscustomobject]@{ File = $_.FullName.Substring($root.Length).TrimStart('\', '/'); Status = 'ADDED AFTER CLOSE' }) }
    $bad = @($rows | Where-Object Status -ne 'OK')
    $expectedOk = if ($ExpectedManifestSha256) { $ExpectedManifestSha256.Trim().ToLowerInvariant() -eq $mHash } else { $null }
    $valid = ($bad.Count -eq 0) -and ($expectedOk -ne $false)
    Write-WfxSection 'Case verification'
    Write-WfxConsole ("Case {0}  host {1}  completed {2}" -f $m.case, $m.host, $m.completed) -Kind Dim
    Write-WfxConsole ("Manifest SHA-256: {0}{1}" -f $mHash, $(if ($null -ne $expectedOk) { if ($expectedOk) { '  (matches the recorded value)' } else { '  (DOES NOT match the recorded value!)' } } else { '' })) -Kind $(if ($expectedOk -eq $false) { 'Bad' } else { 'Dim' })
    foreach ($b in $bad) { Write-WfxConsole ("  {0,-18} {1}" -f $b.Status, $b.File) -Kind Bad }
    Write-WfxConsole $(if ($valid) { "VALID — all $($rows.Count) files match the manifest." } else { "NOT VALID — $($bad.Count) problem(s) found." }) -Kind $(if ($valid) { 'Ok' } else { 'Bad' })
    if ($null -eq $expectedOk) { Write-WfxConsole 'Compare the manifest SHA-256 above with the value recorded when the case was collected.' -Kind Dim }
    [pscustomobject]@{ Path = $root; Valid = $valid; ManifestSha256 = $mHash; Files = $rows.Count; Problems = $bad }
}


